window.__D("text/maamarei-admur-hazaken/c007",{"p":[[2100990149,"<b>ובזה</b> יובן מ\"ש ועתה יגדל נא כח אד' בשם זה באד' דוקא כו'. כי הנה שם זה דאד'<sup data-n=\"3851\">49</sup> שמורה על בחי' הדין דדינא<sup data-n=\"3852\">50</sup> דמלכותא דינא כנ\"ל יש מדרגה זו ג\"כ עד רום המעלות כי בכל מקום מבחי' מל' שבעליון נעשה כתר לתחתון וע\"כ כמו שיש שם אד' למטה שהוא מל' דאצי' שנעשה בחי' ע\"י לבריא' כך יש בחי' מל' בשם אד' גם לפני האצי' כולו וכמ\"ש בתקוני זוהר אם עוונות תשמור י\"ה כד מטו חובין לאו\"א עילאי' אד' מי יעמוד פי' שם אד' שלפני או\"א מי יעמוד כו' כי או\"א המה בחי' התחלה להשתלשלו' עולם האצי' וכד מטו עונו' לבחי' או\"א שהוא שם י\"ה אזי גם בחי' אד' שלפני או\"א מי יעמוד כי בחי' אד' שלפני או\"א היינו בבחי' ח\"ס כי שם אל שבא ראשונה בי\"ג תקוני דיקנא הוא בא מבחי' מל' דח\"ס כמבואר בע\"ח ואל זה בשם אד' ע\"י צירוף והוא הנק' דינא דמלכותא להיות בבחי' כתר מלכו' בעולם האצי' כולו ולהיו' כי סוף מעשה עלה במחשבה תחלה היינו בחי' מ' דאצי' שם אד' שלמטה שעלה במחשבה סתימא' ג\"כ בבחי' שם אד' והוא שם אד' זה שלפני או\"א וע\"כ כד מטו חובין עד או\"א אזי שם אד' זה שעלה במחשבה תחלה האיך יעמוד כי אחר שנעוץ<sup data-n=\"3853\">51</sup> תחלתן בסופן וסופן בתחלתן הכל ענין א' הם התחלה והסוף ודינא דמלכותא דלתתא במל' דאצי' מעורר דינא דמלכותא דלעילא בבחי' שם אד' שבח\"ס דא\"א כו' וזהו אם<sup data-n=\"3854\">52</sup> עוונו' תשמור י\"ה אד' מי יעמוד וד\"ל (וגם יש לפרש בהיפוך אם עונו' תשמור י\"ה אזי שם אד' שבח\"ס יעמוד ע\"י בחי' מי שבח\"ס והוא מה שאמר אד' מי יעמוד כלומר מ\"י יעמוד אותו וכמבואר &lt;רנט&gt;\nבשמו' שיש שם אד' מי וזה יוכל לעמוד ולא אל אד' כי אל אד' הוא רק מבחי' מ\"ל דח\"ס אבל מי אד' הוא למעלה ממנו כו' וד\"ל) וזהו שאמר גם כאן יגדל נא כח אד' דוקא והוא שם אד' שברצון העליון שהוא בחי' הדיבור בבחי' ח\"ס ונק' מל' דח\"ס ושם מאיר ומלובש מבחי' מל' דא\"ק להיו' נמשך מבחי' מל' דא\"ק בכתר דאצי' בחי' הארו' מקיפי' די\"ג ת\"ד כנ\"ל וזהו הנק' כח אד' דוקא וד\"ל.\n<b>והנה</b> הטעם למה שנמשך בבחי' אד' דוקא מבואר למעלה שהוא ע\"י בחי' מעשה המצוה בלתי כוונה והוא הנק' מצות המלך שמעורר למעלה מעלה מבחי' מל' דא\"ק ולהיו' בחי' כח נבדל יוצא בשם אד' בח\"ס כנ\"ל וזהו ועתה יגדל נא כח אד' פי' שיגדל הכח הפנימי הבא מפנימי' עצמות אור א\"ס בשם אד' שבח\"ס שנק' כח נבדל ולהאיר בו בתוספת עוז וכח להיו' בוקעין ונמשכין בחי' הארו' המקיפין די\"ג תיקונין כאשר דברת לאמר פי' כאשר כבר יצא כח נבדל זה בבחי' דיבור דח\"ס לאמר בהעלם הארו' הי\"ג ת\"ד כו' אך מפני שחטא המרגלים הי' גדול וכבד מאד הי' צריך משה להמשכה יתירה להיות בתוספת אור בבחי' כ\"ח אד' מעצמו' המאציל כדי להיו' נושא גם עון המרגלים וכנ\"ל בפי' נושא עון ועובר על פשע שהזדונו' נעשו כזכיו' ונעשה מפשע שפע כו' והכל ע\"י הגדלת כח זה הפנימי מבחי' עצמו' המאציל שיגדל כח אד' שבח\"ס והוא בהיפוך ענין הפסוק אד' מי יעמוד אם עוונו' תשמור י\"ה כנ\"ל אבל כשיגדל כח זה אדרבה שם אד' מי יעמוד דוקא להיו' נושא עון ועובר על פשע כו' וד\"ל.",[["3851","49","<b>דאד' שמורה על בחי' דין</b>: ראה זח\"ב קיח, א. וראה לקו\"ת נצבים נא, ג ואילך. המשך תער\"ב ע' תתקצא. לעיל ע' תקיח."],["3852","50","<b>דדינא דמלכותא דינא</b>: גיטין י, ב. וש\"נ."],["3853","51","<b>שנעוץ תחלתן בסופן</b>: ס\"י פ\"א מ\"ז."],["3854","52","<b>אם עונו' תשמור י\"ה</b>: תהלים קל, ג."]]],[2100990150,"<b>ואחר</b> כל הנ\"ל עדיין יש להבין מה שאמר ועתה יגדל כו' ועתה דוקא ולא באלף השביעי כמבואר למעלה. דהנה מבואר למעלה הטעם בזה לפי שנעוץ תחלתן בסופן כו' מבחי' הכתר כו' וזה אינו אלא בעוה\"ז דוקא ולא בעוה\"ב ויש להבין שרש הטעם לזה, וגם יש להבין שרש ענין מנוחה לחיי העולמי' מהו, דהנה פי' חיי העולמי' הוא בחי' הקו והחוט שנמשך מעצמו' אור הא\"ס והוא מתעגל וחוזר ומתעגל כו' עד סיום עולם האצי' בפרסא שמפסקת כו' ואח\"כ בוקע האור דרך המסך כו' עד רגלי עולם העשי' ובכללו' ההשתלשלו' הרי הוא נקרא בשם חיי העולמי' כי בחי' הקו והחוט הזה הוא מקור וחיו' כל העולמי' מריש כל דרגין עד סוף כל דרגין באבי\"ע כו' וענין בחי' המנוחה לחיי העולמי' הזה היינו בחי' המנוחה לבחי' הקו והחוט הזה והענין הוא לפי שבחי' הקו והחוט הזה בחי' עולה ויורד הוא כל שיתא אלפי שני' כו' בהיות שהיחודי' העליוני' דאצי' שע\"י בחי' הקו הזה הרי מאיר בהם לפעמים בתוס' ולפעמים בגרעון כמו בחול בגרעון ובשבת בתוס' וכן ג' יו\"ט בפסח מתגלה בחי' זו ובשבועו' בחי' אחרת וסוכו' מדרג' אחרת ור\"ה ויו\"כ מדרג' אחרת, והכל הוא ענין עליו' וירידו' בכל חיי העולמים כולם שהוא בבחי' קו זה וא\"כ אין לו בחי' מנוחה, משא\"כ לע\"ל לא יהי' בו בחי' עליו' וירידו' הללו אלא יגיע לבחי' אור העצמו' שלמעלה מבחי' המשכה כלל ולא שייך שם בחי' עלי' וירידה ואז נק' מנוחה לחיי העולמים וכמו שהי' בבחי' מנוחה זו לפני ההשתלשלות דאבי\"ע שהי' הוא ושמו בלבד כו' וד\"ל.\n<b>ואמנם</b> בעוה\"ז דהיינו &lt;רס&gt;\nבכל שית אלפי שני כו' הגם שאין לו מנוחה מ\"מ יש בזה יתרון מעלה ממה שלע\"ל יהי' לו מנוחה כי ענין נעוץ תחלתן בסופן אינו אלא עכשיו דוקא כי סוף מעשה דוקא הוא שעלה במחשבה תחלה דהיינו מה שעלה ברצונו להאציל בתחלת המחשבה כו' הוא בשביל סוף מעשה דהיינו שיהא לו דירה בתחתוני' ע\"י תורה ומצות וכמרז\"ל במדרש במי<sup data-n=\"3855\">53</sup> נמלך בנשמתן של צדיקי' כו' וכמ\"ש במ\"א שזהו ענין העלא' מ\"ן בבחי' זווג דע\"י מיני' ובי' כו' וא\"כ הרי נעוץ תחלתן בסופן אינו אלא עכשיו דוקא דהיום לעשותם דוקא והיום הוא דוקא בחי' סוף מעשה שעולה במחשבה תחלה כו' וד\"ל וע\"כ אמר ועתה יגדל נא כח אד' ועתה דוקא ולא באלף השביעי שיהי' בחי' מנוחה כי עכשיו יש בחי' עליו' וירידו' וזהו בחי' סוף המעשה שעלה במחשבה תחלה כו' וע\"כ גם לבחי' הגדלת כח בשם אד' להיו' נושא עון כו' ג\"כ אינו אלא עתה מפני שנעוץ סופן בתחלתן ופי' תחלתן היינו מבחי' מל' דא\"ק שמאיר בח\"ס כנ\"ל וזהו ג\"כ שבענין התשובה נק' ג\"כ ועתה לפי שהתשובה לאהפכא חשוכא לנהורא כו' הוא ג\"כ בחי' סוף מעשה כו' וזהו עיקר הטעם למה שאמרו ז\"ל דדוקא תשובה<sup data-n=\"3856\">54</sup> ומע\"ט ובעוה\"ז דוקא יפה מכל חיי העוה\"ב וד\"ל.",[["3855","53","<b>במי נמלך בנשמתן של צדיקי'</b>: ראה ב\"ר פ\"ח, ז. רות רבה פ\"ב ג."],["3856","54","<b>תשובה. . יפה מכל חיי העוה\"ב</b>: אבות פ\"ד, מי\"ז."]]],[2100990151,"<h3>ויאמר ה' אל אהרן אתה ובניך אתך תשאו</h3>\n<b>שבת פ' קרח בעזר\"ה</b>\n<b>ויאמר</b><sup data-n=\"3857\">1</sup> ה' אל אהרן<sup data-n=\"3858\">2</sup> אתה ובניך אתך תשאו את עון המקדש כו' וגם אחיך מטה לוי שבט אביך הקרב אתך וילוו עליך וישרתוך כו' ואתה ובניך לפני אהל העדות ושמרו משמרתך ומשמרת כל האהל אך אל כלי הקדש לא יקרבו כו' ונלוו אליך ושמרו כו' וזר לא יקרב אליכם, ע\"כ. ומתוך כללו' פ' זו מובן משמעות פשוטה שהלוים יהיו רק טפלים לכהנים וילוו עליהם וישרתום בלבד אבל הכהנים יהיו העיקר ואז וזר לא יקרב אליהם ממילא וחזר וכפל ענין זה בפ' זו באמרו עוד ואני<sup data-n=\"3859\">3</sup> הנה לקחתי הלוים כו' לכם מתנה נתונים לה' לעבוד עבודת אהל מועד אתה ובניך תשמרו את כהונתכם כו' עבודת מתנה כו' עד והזר הקרב יומת הרי גם בפסוקים הללו משמעות הפשט ע\"ד הנ\"ל שהלוים נתונים במתנה לכהנים אבל הכהנים ישמרו את כהונתם כי הם העיקר ואז ממילא והזר הקרב יומת ובלתי זה הי' זר יוכל ליקרב והי' קצף על בנ\"י אבל כאשר הלוים יהי' משרתי' להם והכהנים יהיו העיקר אזי יהי' כמו שהזכיר קודם באמרו וזר לא יקרב אליכם כו' ולא יהי' עוד קצף על בנ\"י כו' וד\"ל, ולכאורה אין לכל ענין זה שרש וטעם למה יהי' ע\"ד הזה דוקא שיהיו לוים טפלים כו' וגם למה תלוי' ריחוק הזר בדרך הזה דוקא כו'. אך הנה כל פ' זו יובן בהקדים תחלה כללות הטעם לפ' זו דהנה פ' זו נאמרה אחר מפלת קרח ועדתו דמשמע שמתוך מחלוקת &lt;רסא&gt;\nקרח ועדתו ואחר מפלתו עלה ברצון ה' כך שיהי' אהרן ובניו עיקר והלוי' טפלי' ואז לא יהי' עוד קצף כו' והזר הקרב יומת ויש להבין תחלה שרש ענין מחלוקת קרח ועדתו וטעם מפלתו.\n<b>דהנה</b> מבואר בזוהר<sup data-n=\"3860\">4</sup> בראש פ' זו בשרש הטעם למחלוקת קרח וז\"ל אוריי' חילא דימינא ושמאלא אתכליל בימינא מאן דעביד ימינא שמאלא ושמאלא ימינא כאילו אחריב עלמא. אהרן ימינא ליואי שמאלא. קרח בעא למיעבד חלופא דימינא לשמאלא בג\"כ אתענש ע\"כ וזהו סברת ר' אבא ור' יהודה הוסיף עליו ואמר שמאלא אתכלילת תדיר בימינא קרח בעא לאחלפא תקונא דלעילא ולתתא בג\"כ אתאביד מעילא ותתא ע\"כ. והנה הפשט הפשוט בפלוגתא דהני תרי תנאי כך הוא דר' אבא ס\"ל שרצה<sup data-n=\"3861\">5</sup> קרח לעשות בחי' הגבורו' עיקר והחסדי' יהי' בחי' טפל לגבורו' וזהו",[["3857","1","<b>ויאמר ה' אל אהרן אתה ובניך</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (סח, א). נמצא ג\"כ בכת\"י 2042 (קד, ב). בכותרת: ש\"פ קרח שנת תקפ\"ב.\nמאמר זה באריכות מכ\"ק אדמו\"ר האמצעי נדפס בס' מאמרי אדה\"א במדבר ח\"ד ע' א'שנז ואילך. אוה\"ת קרח ע' תשיח ואילך.\nוראה גם ד\"ה זה בתוס' ביאור כו' בסה\"מ תרס\"ט ע' קצב. תוכן המאמר נמצא ג\"כ בהנחת כ\"ק אדמו\"ר מהר\"ש משנת תרי\"ד — נדפס במאמרי אדמו\"ר הצ\"צ — הנחות תרי\"ד-תרט\"ו. ראה ד\"ה כל פטר רחם בסה\"מ תרכ\"ז ע' שמא.\nנוסח אחר (הנחת המהרי\"ל) נדפס לקמן ע' תקמב בהתחלה ”מאן דעביד ימינא שמאלא\"."],["3858","2","<b>ויאמר ה' אל אהרן. . וזר לא יקרב אליכם</b>: קרח יח, א-ד."],["3859","3","<b>ואני הנה לקחתי הלוים. . והזר הקרב יומת</b>: קרח יח, ו-ז."],["3860","4","<b>בזוהר בראש פ' זו</b>: זח\"ג קעו, א. וראה שם קעח, א-ב."],["3861","5","<b>שרצה קרח. . בחי' הגבורו' עיקר והחסדי'. ֿ. טפל</b>: ראה לקו\"ת מטות פו, ב. ואתחנן ז, סע\"ד. ס' מאמרי אדה\"ז על ענינים ע' שעז: וכמ\"ש בע\"ח. ֿ. ובפרדס. וראה מאמרי אדה\"א קרח ע' א'רצא. דברים ח\"א ס\"ע קפז ואילך. ביאוה\"ז לאדה\"א צד, ג."]]],[2100990152,"שא' קרח בעא למיעבד חלופא דימינא לשמאלא דהיינו שיהי' כח החסדי' שבקו הימין חח\"נ טפלי' ונכללי' בבחי' הגבורו' שבקו השמאל כמו שעכשיו בהיפוך שהגבורות שבקו השמאל אתכללו בימינא כמ\"ש אוריי' חילא דימינא כו' ור' יהודה ס\"ל דזה דעת קרח לעשו' מהגבורות עיקר עד שיהי' החסדים טפלים אליהם אלא רק רצה להפריד בחי' הגבורו' בלתי יתכללו בחסדי' ולא יהיו טפלי' להם בלבד אלא יהיו בחי' הגבורות בחי' ומדרגה בפ\"ע ולא יהיו בטילי' ונכללי' בחסדי' כו' וזהו שאמר קרח בעא לאחלפא תקונא דעילא ותתא פי' מפני שזהו רק היפוך בחי' התיקון דמ\"ה וב\"ן שיהי' הגבורות דוקא נמתקין ונכללי' בחסדי' שזהו ענין כל התורה והמצו' וכמ\"ש תחלה אוריי' חילא דימינא כו' והוא רצה לעשו' גם מבחי' הגבורות עיקר ושלא יהי' בטילי' בחסדי' ה\"ז היפוך בחי' התיקון בלבד אבל לא עלה על דעתו לעשו' מהגבורו' עיקר כ\"כ עד שיהיו החסדי' בטילי' כדעת ר' אבא ומ\"ש לשון עילא ותתא יתבאר בסמוך וזהו ענין הפשט הפשוט בטעם מחלוקת קרח ואיך שיש בזה ב' דיעות דהני תרי תנאי ר' אבא ור' יהודה כנ\"ל. ועתה יש להבין ביאור ענין זה למה רצה קרח לעשו' מבחי' הגבורות עיקר ואיך שנענש מפני שהחליף תקונא דלעילא ותתא לדעת ר\"י ולדעת ר\"א אחליף לגמרי ימינא בשמאלא כו'.\n<b>דהנה</b> ידוע שקודם שנמשך בחי' הקו<sup data-n=\"3862\">6</sup> והחוט מאור א\"ס הי' תחלה בחי' הצמצום הנק מקום פנוי כו' ואח\"כ נמשך בחי' הקו והחוט כו' וא\"כ מאחר שבחי' צמצום זה כבר קדם לבא לבחי' הקו והחוט הרי שרש בחי' הגבורות למעלה גבוהים מבחי' קו החסדים שהצמצום מבחי' גבורו' הוא כידוע להיותו בבחי' הסתלקו' מלמטה למעלה כו' וזהו עיקר הטעם באמת להכלל הנזכר בכל מקום במעלת הגבורו' על החסדי' כמו מעלת<sup data-n=\"3863\">7</sup> הזהב על הכסף כו' וכמו בענין הלוים<sup data-n=\"3864\">8</sup> שלעתיד יהיו הם כהנים לפי ששרש הלוים מבחי' גבורו' כמ\"ש כאן ליואי בשמאלא ושרש הגבורו' קודמי' לבחי' החסדי' מטעם הנ\"ל וד\"ל אך הנה בזה הי' טעות השגת קרח במה שהשיג במעלת הגבורו' שרש הלוים שגבוהי' הרבה מבחי' החסדי' כנ\"ל וע\"כ הי' חולק על אהרן אבל שגה ברואה כי הגם שבעצמו' המאציל באמת כך הוא שהצמצום בהכרח לבא קודם לבחי' החסד וההשפעה כידוע אבל אין זה אלא כשעדיין השפע הוא בעצמו' המשפיע שאז בהכרח שיבא בו בחי' הצמצום תחלה משא\"כ בהיותו כבר משפיע למקבל אז נהפוך &lt;רסב&gt;\nהוא שהחסדים הם העיקר והגבורו' שם אינו אלא בחי' טפל לחסדי' כמשי\"ת בסמוך והיינו בעולם האצילות שהוא כבר בחי' גילוי אור המאציל בבחי' מאין ליש להיו' בבחי' אורו' וכלים ממש כידוע שם החסדים עיקר והגבורו' טפל וכמ\"ש והחיות<sup data-n=\"3865\">9</sup> רצוא ושוב והיינו חיו' אור א\"ס בנאצלי' שהוא שם",[["3862","6","<b>הקו והחוט. . מקום פנוי</b>: ראה ע\"ח שער (א) דרוש עגולים ויושר ענף ב."],["3863","7","<b>מעלת הזהב על הכסף</b>: ראה תניא פ\"ז."],["3864","8","<b>הלוים שלעתיד יהיו הם כהנים</b>: ראה לקו\"ת (להאריז\"ל) בתחלת יחזקאל [ד\"ה ענין יחזקאל]. תניא פ\"נ (ובהנסמן בליקוט פירושים ומ\"מ שם). לקו\"ת קרח נד, סע\"ב. מאמרי אדה\"א ויקרא ח\"א ע' רלח. ביאוה\"ז להצ\"צ כרך א' ע' שמ ואילך."],["3865","9","<b>והחיות רצוא ושוב</b>: יחזקאל א, יד."]]],[2100990153,"ג\"כ בבחי' רצוא ושוב הרי בחי' השוב הוא עיקר להיותו עיקר המחי' והרצוא אינו אלא בחי' טפל כמשל הידוע מן הנשימה שברוח האדם שהיא ג\"כ בבחי' רצוא ושוב שאנו רואי' בחוש שבחי' השוב הוא עיקר המחי' וכו' וע\"כ נקרא אור החכמה<sup data-n=\"3866\">10</sup> דאבא מקור החסדי' בשם באר מים חיים כו' כמ\"ש בזוהר בכמה דוכתי לפי שהוא עד\"מ מים חיים שנובעי' בתמידו' כך מי החסדי' הולכי' מגבוה לנמוך להחיו' בתמידו' והשוב הוא עיקר הכוונה שם ובחי' הרצוא אשר יש שם אינו אלא בחי' טפל דהיינו רק כדי שיוכל להיו' אחרי הרצוא בחי' השוב דחסדי' וכל עיקר הרצוא אינו בא בשביל עצמו כלל רק הוא בא בשביל החסדי' דאח\"כ בלבד וזהו הנק' טפל שהוא בחי' משמש בכל מקום להעיקר וכך בחי' הרצוא דגבורו' אינם אלא בחי' משמשי' שיוכלו החסדי' לימשך אח\"כ ואינם באי' בשביל עצמם כלל כו' וזהו ענין עליי' שהיא רק לצורך ירידה בלבד דהיינו כדי שיוכל להיו' המשכה צריך להיו' תחלה בחי' העלא' והרי ההעלא' אינה ענין אמיתי מצד עצמו אלא רק כדי שיוכל לירד השפע אחר ההעלא' כו' והוא הנק' עלי' צורך ירידה וד\"ל והיינו ענין ביטול והתכללו' בחי' הגבורו' בחסדי' שהזכיר כאן במאמר זה שמאלא אתכליל בימינא אהרן ימינא ליואי שמאלא כו'.\n<b>ולהבין</b> ענין זה בתוספת ביאור איך שהעלי' יהי' רק לצורך ירידה כנ\"ל הנה יש להקדים ענין אחר והוא ביאור ענין י\"ב<sup data-n=\"3867\">11</sup> צרופי הוי' דז\"א שנק' יום והם י\"ב שעות היום וי\"ב צרופי אד' דמלכו' שנק' לילה מה הן דהנה כתיב כי<sup data-n=\"3868\">12</sup> אלף שנים בעיניך כיום אתמול ולכאורה אינו מובן דהלא ידוע בענין עצמו' אור א\"ס שהוא למעלה מבחי' גדר התחלקו' זמן ומקום כו' ואחר שהוא בודאי למעלה מן בחי' הזמן אפי' ממקור התהוו' הזמן א\"כ איך אומר כי אלף שנה הם כיום אתמול מהו יום אתמול הרי גם יום אחד הוא בגדר זמן כמו אלף שנה כו'. אך הענין הוא דבאמת בחי' עצמו' אור א\"ס הוא למעלה גם מבחי' מקור הזמן אלא שבחי' התחלקו' הזמן נסתעף ממנו בדרך סדר השתלשלו' דאבי\"ע מעילה לעילה כו' עד שנחלק הזמן לימים ושעו' ורגעים.\n<b>וביאור</b> הדברים יובן בתחלה ממה שאנו רואים בחי' התחלקו' הזמן היותר אחרון בהשתלשלו' שהן היום והלילה דהנה היום מובדל בשינויי' גדולים מן הלילה עד שאין היום דומה ללילה כלל לא במהות ואיכות מלבד שי\"ב שעו' היום מאירי' וי\"ב שעו' הלילה אפילי' הנה גם בהשפעה והמשכה שנמשך ביום משונה הוא מן ההשפעה וההמשכה שנמשך בלילה כמ\"ש ממגד<sup data-n=\"3869\">13</sup> תבוא' שמש וממגד גרש",[["3866","10","<b>החכמה. . מים חיים</b>: ראה זוהר (רעיא מהימנא) רלה, ב. לקו\"ת דרושים לסוכות ושמע\"צ פ, ב."],["3867","11","<b>י\"ב צירופי הוי'. . י\"ב שעות היום</b>: ראה תניא פמ\"א (נו, ב). ובליקוט פירושים ומ\"מ לשם. לקו\"ת ר\"ה סא, א. ס' מאמרי אדה\"ז הקצרים ע' שכט. סה\"מ תקס\"ז ע' קנח. שערי אורה ס, א. פיה\"מ לאדה\"א יד, א. אוה\"ת קרח ע' תרפח ואילך."],["3868","12","<b>כי אלף שנים בעיניך כיום אתמול</b>: תהלים צ, ד."],["3869","13","<b>ממגד תבואו' שמש</b>: ברכה לג, יד."]]],[2100990154,"ירחים הרי יש גידול תבואת שמש שמגדל ביום ויש גידול שמתגדל בלילה מן הירח דוקא ויש הבדל גדול ביניהם וא\"כ החיו' המקורי של היום בודאי מובדל בשינוי גדול משל לילה וגם באדם אשר חי ביום כמו בלילה וכן הבהמה וכל גדר החי ג\"כ אנו רואי' שיש בהם שינוי גדול מיום ללילה דביום חיו' האדם &lt;רסג&gt;\nבאופן יותר מאיר בשכל ומדו' וגם בשאר איבריו מכמו שהוא בלילה והיינו שיש פלוגתא<sup data-n=\"3870\">14</sup> בגמרא אם הלילה לשינה או לגירסא כו' וחד מ\"ד ס\"ל דהמשכת שפע חכמ' בלילה יותר מביום כו' ועכ\"פ משונים הם היום והלילה גם באדם וכל החי כו' וא\"כ מוכרח לומר שהיום יש לו חיות מיוחד נבדל והלילה יש לו חיות מיוחד נבדל בפ\"ע וא\"כ יובן עד\"ז עוד למעלה מהתחלקו' דיום ולילה שהוא ג\"כ ע\"ד הזה דהנה ידוע הטעם להתחלקו' השנה לשס\"ה יום דוקא לפי שיש בבחי' ההתחלקו' בחי' כלל ובחי' פרט כדרך כל התחלקו' שמתחלק לפרטי פרטי' שבהכרח שהראשון הוא כללי יותר מכולם וכשמתחלק הכלל הראשון לחלקים נק' החלקים כאו\"א בשם פרט וכאשר כאו\"א מתחלק לחלקים נק' כלל לגבי החלקים שמתחלקי' מאתו כו' וע\"ד זה יש כלל ופרט עד הפרט היותר אחרון כו' וד\"ל.\n<b>והדוגמא</b> מזה יובן למעלה בהתחלקו' הזמן שיש ג\"כ בחי' כלל ופרט בסדר השתלשלו' כנ\"ל דהנה התחלקו' הראשון בשנה הם י\"ב חדשים בלבד שהשנה מתחלקת לי\"ב חלקים בלבד וא\"כ נמצאת בחי' המשכה הכללית שכוללת י\"ב החדשי' כא' נק' ראש השנה וי\"ב החלקים הן י\"ב המשכו' פרטיות וכאו\"א מובדל בחיו' משונה בפ\"ע כנ\"ל בענין הבדל בין יום ללילה כו' ואח\"כ מתחלק כל חדש ללמ\"ד יום הרי הוא ג\"כ ע\"ד הזה שהחודש נק' כלל שכולל חיות כל הלמ\"ד יום כא' בלתי התחלקות ואח\"כ נמשך בבחי' התחלקות ללמ\"ד חלקי חיות וכאו\"א נבדל במהו' בפ\"ע כו' ואח\"כ היום מתחלק לי\"ב שעו' והלילה לי\"ב שעו' וכל שעה יש לה צירוף מיוחד כידוע בענין י\"ב שעו' שהם י\"ב צרופי הוי' בדרך פרט וי\"ב שעו' הלילה בחי' י\"ב צרופי אד' כו' ואמנם הנה לפ\"ז מובן הטעם שנק' כלל הראשון שכולל השס\"ה יום כולם בשם רא\"ש השנה וכן הכלל השני שכולל למ\"ד יום בשם ראש חדש כו' כי הנה עד\"מ הראש עם האיברים כולם באדם שאנו רואים בחוש שמן הראש יתפשט שפע חיות לכל האיברים כולם פנימיים וחיצונים כמו כח הראי' בעין נמשך ממוח שבראש וכן השמיעה והדיבור כו' וגם האיברים הפנימיי' כלב וריאה וקיבה כו' הכל מקבלי' מחיזוק המוחי' שבראש והמופת לזה שבאיבוד המוח יפסדו מקורם ויהיו כלא הי' מתחלה חיו' בהם כלל כמבואר בספרי הרפואה אך הנה התחלקו' זאת בעין לראו' וברגל להילוך וכיוצא בודאי אינה ניכרת כלל במוחי' שבראש כי אין שם כח הראי' בבחי' כח נבדל וההילוך בכח נבדל אלא כולל הוא כל כחו' המתחלקי' כא' בבלתי התחלקו' כלל ואח\"כ מתחלקי' ויוצאי' ממנו כאו\"א בפ\"ע ואעפ\"כ כולם כלולי' בו כו' וזהו הדמיון להבין להמשכה כללי' דשס\"ה יום שנק' ראש השנה כמו הראש שכוללת כל כחו' איברי' הפרטי' כו' וכך בר\"ה נשפע כל",[["3870","14","<b>פלוגתא בגמרא</b>: עירובין סה, א."]]],[2100990155,"שפע הבאה אח\"כ בשס\"ה יום בבת א' אלא שאח\"כ מתחלק כאו\"א בעתו ובזמנו כו' וכן החדש נק' ראש לגבי למ\"ד יום שמתחלקים ממנו ע\"ד הזה מפני שבר\"ח נשפע כא' כל הל' יום ואח\"כ מתחלקי' ללמ\"ד חלקי' אמנם כולם כלולים בר\"ח כו' ולכך נק' ראש חדש עד\"מ הראש עם האיברי' כנ\"ל וד\"ל.\n<b>וזהו</b> כי אלף שנה כיום אתמול, פי' דוד שאמר מזמור זה דתפלה למשה בודאי הי' לו רוח הקדש בשרש השגתו של &lt;רסד&gt;\nנשמתו שהי' ודאי באיזה מדרגה בג' העולמו' אם בי\"ס דיצי' או בי\"ס דבריאה אשר שם אלף שנה שלנו נחשבים רק כיום אתמול בלבד כי שיתא<sup data-n=\"3871\">15</sup> אלפי שני דהוי עלמא וחד חרוב אינה נקראת כלפי מקור המחי' כללו' הז' אלפי' אלא רק בשם ז' ימים בלבד ובבוא ההתחלקו' של יום אתמול זה למטה הוא שנתחלק לאלף חלקים ונעשי' אלף שנה בכל שנה פרט א' שנק' ר\"ה וכנ\"ל בהתחלקו' י\"ב חדשי' מר\"ה ול' יום מר\"ח ודוד השיג בבחי' ו\"ק דבריא' שמשם נמשך התחלקו' ז' אלפי שנים שלנו ושם הם נכללי' בכללות כהתכללו' למ\"ד יום בר\"ח וע\"כ נק' שם יום אתמול כללו' חיו' אלף שנה כא' ובו\"ק דאצי' גם ז' יומין דבריאה נכללי' כא' בו וד\"ל, ועד\"ז יובן בחי' התכללו' של ההתחלקו' עד רום המעלות דהנה בדרך אחר נק' ז' אלפי שנים שלנו בשם שמטה א' למעלה באצי' וז' שמטו' נכללי' כא' ונק' יובל וכו' ועד\"ז עד נ' אלפים יובלות כו' והרי יוכל להיו' התכללו' כזאת עד אין שיעור למעלה מעלה בעצמו' אור הא\"ס כי בחי' אור א\"ס אין לו שיעור למעלה בעילוי אחר עילוי כמאמר הכל<sup data-n=\"3872\">16</sup> ירוממוך כו' וכידוע אלא שדוד לא השיג בתפלת משה זו רק ביצי' או בבריא' לכך לא אמר רק כי אלף שנה כיום אתמול כו' וד\"ל.\n<b>ואחר</b> הקדמה זו יובן שרש ענין עלי' צורך ירידה הנ\"ל. דהנה מתבאר מתוך כל הנ\"ל בכל התחלקו' בפרט הוא בהכרח שיש חיות חדש בכל חלק וחלק בפ\"ע, עד שגם בפרט היותר אחרון כמו היום והלילה יש חיות מיוחד ליום בפ\"ע ולא יש שייכו' וחיבור עמו כלל מן הלילה ואין לחיו' הלילה שייכו' וחיבור עם יום הבא אחריו ועד\"ז מתחדש החיו' גם משעה לשעה ביום א' והוא ענין הצרופי' שיש בכל שעה צירוף שם הוי' מיוחד וכשבאה השעה השנית מתחדש לבא צירוף אחר חדש שלא הי' עדיין מעולם וזהו בהכרח לומר כי הפרט ודאי דומה לכלל וכמו שבכלל בכל ו'<sup data-n=\"3873\">17</sup> אלפי' שנה ששרשם בו\"ק דאצי' שנק' ו' יומין בכלל גם שם יש י\"ב צרופי הוי' בכל יום ובכלל יותר ביום הא' יש צירוף שם אל דחסד וביום הב' שם אלקי' דגבורה וכיוצא בזה א\"כ כמ\"כ כשנמשכי' מהם ו' אלפי' שנה למטה עד בפרט הימים די\"ב חדש יש ג\"כ בכל יום י\"ב צרופי' וזהו הענין הנ\"ל די\"ב צרופי הוי' הוא בבחי' ז\"א בכלל וי\"ב צרופי' דאד' הוא בבחי' מלכו' בכלל כי זו\"נ נק' יום ולילה בדרך הכללות כידוע וד\"ל ולפ\"ז הרי בכל צירוף פרטי מתחדש הוא עד רום המעלות מיום",[["3871","15","<b>כי שיתא אלפי שני דהוי עלמא</b>: ר\"ה לא, א."],["3872","16","<b>הכל ירוממוך</b>: ע\"פ ברכות ק\"ש דשבת."],["3873","17","<b>ו' אלפי' שנה. . בו\"ק</b>: ראה ג\"כ תו\"ח בראשית ד, ב ובהנסמן שם בהמ\"מ."]]],[2100990156,"לשנה ומשנה לאלף ואלף כו' כי הצירוף הבא מחדש יש לו שרש לשרש עד נ' אלף יובלו' הנ\"ל והכל בהתחדשו' כי היום מקבל חידושו בשנה ויש לו מקום מיוחד בו והשנה באלף כו' וא\"כ מובן שבבא צירוף חדש חידוש זה בא בהכרח ממקור הראשון הכללי יותר מכולם כו'. והנה ידוע בכל חידוש אור הבא מלמעלה בבחי' שפע והמשכה למטה צריך שיהי' תחלה אליו העלא' מלמטה כמאמר רוח<sup data-n=\"3874\">18</sup> אייתי רוח ואמשיך רוח כו' וכידוע בביאור ענין מ\"ן ומ\"ד וא\"כ יש להבין מהיכן הי' בחי' העלא' מלמטה עד שגרם זאת השפע מלמעלה למטה בחידוש אור צירוף הבא מחדש &lt;רסה&gt;\nביום או בלילה כו'.\n<b>אך</b><sup data-n=\"3875\">*18</sup> הענין הוא דהעלאה היתה מיום הקדום שנסתלק וחלף והלך לו אותו הצירוף של היום והוא הגורם ירידת אור צירוף החדש ביום או בלילה שלאחריו וענין הסתלקו' ועלי' שלו הוא שנכלל ועלה בכלל שלו תחלה כמו היום בר\"ח שהוא חלק א' מלמ\"ד שבו כנ\"ל והחדש עולה ונכלל בשנה והשנה באלף כו' כי הרי יש לאותו צירוף מקום מיוחד לעלות עד רום המעלו' עד היותר כללי מכולם כנ\"ל ואז בהגיע להכלל הראשון חוזר ויורד שפע והמשכת צירוף חדש עד שנעשה יום חדש למטה והיינו ענין העליה שהיא רק לצורך ירידה בלבד כי לא הי' ענין עלי' היום הקדום רק לעורר ירידת יום חדש כו' וזהו יום<sup data-n=\"3876\">19</sup> ליום יביע אומר כו' וקאי בין בבחי' הפרט בין בבחי' הכלל בו' יומין דאצי' שיום הא' הוא אלף שנה הראשון של חסד עלה למעלה והוא יביע אומר ליום השני דהיינו אלף שני שירד ויומשך למטה וכן מובן בזוהר<sup data-n=\"3877\">20</sup> ע\"פ זה יום ליום יביע כו' ע\"ש וד\"ל ומכל כיוצא בזה יובן ענין התכללו' בחי' הגבורו' בחסדי' איך שאין הרצוא רק בשביל השוב דחסדי' כנ\"ל וד\"ל.\n<b>וזהו</b> כללות ענין הלוים שהיו נושאים את המשכן כמ\"ש ונשאו<sup data-n=\"3878\">21</sup> הלוים כו', דהנה ענין המסעות שבמדבר מ\"ב מסעו' היו כולם בחי' עליות כידוע שזהו כללו' ענין שם מ\"ב וידוע דהמשכן וכל כליו הוא בחי' מל' דאצי' ששורה בעולמו' בבחי' אורו' וכלים וא\"כ כאשר נשאו את המשכן בנסיעתם הי' בחי' עליי' והסתלקו' למשכן שהוא בחי' מל' דאצי' למעלה ברום המעלו' ולפי שהלוים היו מבחי' הגבורו' היו הם הנושאי' דוקא כמו ענין והחיו'<sup data-n=\"3879\">22</sup> נושאו' הכסא כו' וכמשל הידוע במרכבה שמגביה את הרוכב ונושאו למקום שאין ביכולתו להגיע מצד עצמו כמו הסום שנושא את הרוכב עליו כו' ועלי' זו עד רום המעלות היתה והנה כדוגמת עלי' של הצרופי' הנ\"ל כך עיקר עלי' זו הי' רק בשביל הירידה של אח\"כ והוא ענין החנייה שהיו חונים אחר נסיעתם כו' כמ\"ש<sup data-n=\"3880\">23</sup> עפ\"י ה' יחנו כו' כי עיקר הרצוא הוא בשביל בחי'",[["3874","18","<b>רוח אייתי רוח ואמשיך רוח</b>: ראה זח\"ב קסב, ריש ע\"ב. זח\"א צט, ריש ע\"ב."],["3875","*18","<b>אך הענין</b>: ראה סה\"מ תרכ\"ז ע' שדמ."],["3876","19","<b>יום ליום יביע אומר</b>: תהלים יט, ג."],["3877","20","<b>בזוהר ע\"פ זה</b>: זח\"ב קלו, ב."],["3878","21","<b>ונשאו הלוים</b>: ראה בהעלותך י, יז. ושם כא. לקו\"ת פקודי ה, ג. וראה תו\"ח פקודי [הוצאת קה\"ת תשס\"ג] תמה, א."],["3879","22","<b>והחיו' נושאו' הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א, ספ\"ד."],["3880","23","<b>כמ\"ש ע\"פ ה' יחנו</b>: ראה ג\"כ פירוש המלות מ, ג."]]],[2100990157,"השוב דחסדי' הבאי' אח\"כ והוא בחי' ביטול והתכללות הגבורו' בחסדים כנ\"ל וזהו הנק' ג\"כ בשם בחי' המתקת הגבורו' בחסדים וכמ\"ש ואל<sup data-n=\"3881\">24</sup> אישך תשוקתך והוא ימשול בך פי' ואל אישך תשוקתך הוא בחי' הרצוא והוא ימשול בך הוא בחי' המשכת המ\"ד דחסדי' דדכורא שממתיקין בחי' הגבורו' דנוק' שהוא העיקר וההעלא' מ\"ן דגבורו' הי' רק בחי' טפל כנ\"ל וד\"ל.\n<b>וזהו</b> שרש ענין מחלוקת קרח שלא רצה שיהיו בחי' הגבורו' בטילי' ונכללי' בחסדי' כמבואר במאמר זוהר הנ\"ל ולדעת ר' אבא רצה להחליף שיהיו בחי' החסדי' בטילי' בגבורות והיינו ענין ירידה צורך עלי' ולדעת ר\"י לא רצה רק שלא יהיו הגבורו' בטילי' בחסדי' אלא יהי' עבודת הלוים מדרגה בפ\"ע בלתי יצטרכו לבא בבחי' ביטול והתכללו' בחסדי' כנ\"ל והיינו שאמר קרח מדוע<sup data-n=\"3882\">25</sup> תתנשאו על קהל ה' כלומר למה יהיו גם הלוים כפופים אליכם הלא בחי' הגבורו' מדרגה בפ\"ע הם כו' בהשווא' א' למדרגת החסדים כו' והנה משמעות הענין הוא שהיו הלוים כפופים לכהנים מכל צד ופנה עד שלא הי' מקום מעלה ללוים בעבודתם בפ\"ע כלל בלתי הכהנים.\n&lt;רסו&gt;\n<b>והענין</b> הוא כי במסעות שבמדבר היו ג\"כ עיקר העבודה בכלי המשכן ע\"י הכהנים וכל עבודת הלוים הי' ג\"כ ע\"י הכהנים כי ידוע ומבואר דקודם שניתן ללוים כל כלי המשכן תחלה כיסו כהנים במכסה עור תחש לכל כלי המשכן ולא היו הלוים רשאים לעמוד בשעת הכיסוי וכמ\"ש ולא<sup data-n=\"3883\">26</sup> יראו כבלע את הקדש כו'. והענין הוא כי ידוע דהמסעות היו במדבר דוקא כדי לברר וללבן ג' קליפו' הטמאו' לגמרי אשר משכנם במדבר דוקא ונק' נחש שרף ועקרב כמ\"ש במדבר<sup data-n=\"3884\">27</sup> הגדול והנורא כו' ולהיות כן הרי כשהי' נוסעי' במסע להיות שהוא בחי' עליי' לבחי' מל' דאצי' שהוא המשכן כנ\"ל ובכל עליי' והסתלקו' יכולי' החיצוני' ג\"כ לעלות כי ק\"ך<sup data-n=\"3885\">28</sup> צרופי' אלקי' יש כידוע וע\"ב צרופים הם דקדושה ומ\"ח צרופים יונקים מהם גם החיצונים שנק' אלקים אחרים וזהו ענין אותות<sup data-n=\"3886\">29</sup> ומופתים באדמת בני חם כו' וא\"כ בכל נסיעה הי' מקום לעליו' אלקים אחרים שבמדבר ולכך היו הכהנים מכסים תחלה לכלי המשכן במכסה עור תחש ובבגד תכלת כו' שהם בחי' אורו' מקיפי' להלביש מבחוץ ולשומרם מיניקו' החיצונים ולזה הטעם גם הלוים לא היו רשאי' לעמוד בשעת הכיסוי של הא\"מ הנ\"ל כי הלוים שרשם מבחי' הגבורו' וכמ\"ש ליואי בשמאלא ובקו השמאל יש מקום לעליו' החיצונים ג\"כ אך מפני המקיפי' המה בורחים כי המקיפים דוחי' החיצונים וכידוע דמקיף דהתכלת מסמא עיני החיצונים כו' וע\"כ גם בלוים נא' ולא יראו כבלע את הקדש כו' ואמנם זאת העבודה להמשיך מקיפי' א\"א כ\"א בכהנים דוקא להיו' שרשם",[["3881","24","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["3882","25","<b>מדוע תתנשאו</b>: קרח טז, ג."],["3883","26","<b>ולא יראו כבלע את הקדש</b>: במדבר ד, כ."],["3884","27","<b>במדבר הגדול והנורא</b>: לשון הכתוב — עקב ח, טו."],["3885","28","<b>ק\"ך צרופי' אלקי'. . ומ\"ח צרופים</b>: ראה ס' הליקוטים להאריז\"ל ר\"פ בא. פע\"ח שער חג המצות פ\"ה. שער הכוונות ענין הפסח. ע\"ח שט\"ו פ\"ו. ש' מד פ\"ד ופ\"ז. מבוא שערים שער ד ח\"ב פ\"ט-י."],["3886","29","<b>אותות ומופתים באדמת בני חם</b>: ע\"פ ברכת אמת ואמונה (תפלת ערבית)."]]],[2100990158,"בבחי' החסדי' דאור אבא שהוא בחי' ביטול בחשאי שזה הי' עבודת הכהנים כמ\"ש בזוהר<sup data-n=\"3887\">30</sup> כהני ברעותא דלבא בחביבותא כו' אהבה שבבחי' הביטול משא\"כ הלוים עבודתם בשיר בגילוי התלהבו' מלמטה למעלה כו' וע\"כ המשכת המקיפי' ששרשם מן החסדי' דאבא א\"א כ\"א ע\"י הכהנים דוקא ולכך לא היו הלוים רשאי' לעמוד בשעה שכיסו הכהנים למשכן במקיפי' הנ\"ל אלא אחר שכיסו מסרוהו לידי הלוים ולא הי' ללוים עבודה בלתי הכהנים שהכינו להם בתחלה ובאם שלא היו מכיני' הכיסוי הרי היו יניקו' החיצונים דוקא ע\"י הלוים להיותם מבחי' הגבורו' כנ\"ל ולכך נתקנא קרח במה שנמסרו הלוים שיהי' תלוי' גם כל עבודתם בכהנים וד\"ל.\n<b>והנה</b> מלבד ענין זה שהמשיכו מקיפי' מלמעלה שלא ינקו החיצוני' כנ\"ל הנה גם שיוכלו הלוים להעלות המשכן בבחי' התעוררו' גבורו' באתעדל\"ת הנק' העלא' מ\"ן הי' ג\"כ תלוי' בכהנים כי הנה ידוע בפי' בא\"י כו' מלך העולם שברכה זו היא בחי' אתדל\"ע שלפני אתעדל\"ת והוא נק' כח המעלה מ\"ן והיינו מבחי' אור מקיף אלא שהוא רק הארה בעלמא וא\"כ הרי מכל צד ופנה הי' תלוי עבודת הלוים בכהנים בין מלמעלה בהמשכת מקיפי' הנ\"ל ובין מלמטה שיהא ללוים כח להעלות כו' ולזה הטעם הי' עיקר קנאתו של קרח ואמר מדוע תתנשאו כו' כלומר כך הי' טענתו מה לכם אצלינו לקחת גם מה שבחלקינו וגורלינו להיו' גם כל עבודתינו תלוי' רק בכם די לכם במדרגה שלכם והוא בעבודת המשכו' החסדי' ואמנם לא יגרע חלק עבודתינו והוא להיו' בחי' העלאו' הגבורו' מצדינו דוקא ואח\"כ תמשיכו החסדי' ולמה לא נוכל לעלות בלתי &lt;רסז&gt;\nהמשכה שלכם תחלה והרי אין לנו מקום כלל בלתיכם ומדוע תתנשאו בכל עלינו כו' אך טעה קרח טעות גדול בזה וכמ\"ש דאחליף תקונא דלעילא ותתא וכמשי\"ת בעזר\"ה וד\"ל.\n<b>וזהו</b> וידבר ה' אל אהרן אתה ובניך תשאו את עון המקדש כו' ואת אחיך שבט הלוי הקרב אתך כו' וילוו עליך וישרתוך וכו'. עד וזר לא יקרב אליכם. פי' כללו' ענין פ' זו היינו אחר שנענש קרח והי' קצף על בנ\"י בעונו הוצרך לתקן עון קרח כי עיקר חטא קרח היה מה שרצה לעשו' מהגבורו' ג\"כ ענין מדרגה בפ\"ע ולא יהיו בטילי' בחסדי' ולזה ציוה ה' לאהרן לתיקון זה שיהי' ההיפוך מדעת קרח והוא שהחסדי' יהיו דוקא העיקר והגבורו' יהיו בטילים ונכללי' בחסדי' כמו שהוא מן הראוי לפי רצון המאציל למעלה שאין גבורו' ההעלא' באצי' רק בשביל ההמשכה דחסדים וכמ\"ש למעלה בענין המסעות בענין עלי' צורך ירידה כו' וזהו מ\"ש במאמר הנ\"ל דהיינו תקונא דעילא ותתא פי' כי עיקר התיקון באצי' ובבי\"ע בכלל הוא רק ע\"י ביטול והתכללו' הגבורו' בחסדים כי עי\"ז לא יוכל להיו' יניקו' החיצונים כלל בהעלא' שמצד הגבורו' כי החסדי' דאור מקיף הוא המכסה עליהם כנ\"ל בפי' הכיסוי דכלי המשכן וגם בגופה של ההעלא' מצד עצמה שיוכל התחתון לעלו' מלמטה למעלה ג\"כ הוא בא מבחי' החסדי' דמקיפי' דכהנים שרשם המה מבחי' נצח דיסוד אבא כידוע ומשם נמשך שרש כל החסדי' שבקו הימין כו' והיינו",[["3887","30","<b>בזוהר כהני ברעותא דלבא בחביבותא</b>: ראה זח\"ג לט, א. קעז, ב. ובכ\"מ."]]],[2100990159,"פי' תקונא דעילא ותתא פי' לעילא הוא בחי' התיקון שבא מאור המקיף להכניע החיצונים שלא יעלו גם הם למעלה כנ\"ל ותיקון דלתתא היינו שיוכלו התחתונים לעלות כנ\"ל וד\"ל.\n<b>וזהו</b> וידבר ה' אל אהרן אתה ובניך כו' פי' אתה ובניך יהיו בחי' העיקר בעבודת המקדש וכמבואר למעלה שהכהני' עיקר בין בהכנה שלפני הנסיעה של הלוים שהכהנים כיסו באורו' מקיפי' ובין אחרי הנסיעה והרצוא שהעיקר הוא החנייה כנ\"ל וגם בכאן הוא אומר אתה ובניך הם העיקר בין בעיקר העבודה בין בהכנה שלפני העיקר בעיקר העבודה שהוא המשכת הגילוי אלקו' בבחי' השוב אמר אח\"כ באמרו ואתה ובניך לפני אהל העדו' להקריב הקרבנו' כו' ובין בהכנה שלפני העבודה היינו שאמר בתחלה אתה ובניך אתך תשאו את עון המקדש וחזר וכפל לומר תשאו את עון כהונתכם והענין הוא כי בהכנה שלפני העבודה היינו הענין הנ\"ל להכניע כחות החיצונים בתחלה שלא יעלו גם המה למעלה ויפגמו האורו' עליונים ע\"כ אמר שזהו ג\"כ בכהנים תלוי' שהם ישאו עון המקדש כלומר שהם יכפרו העון וינקו אותו במה שלא יעלו החיצונים גם הם והוא בבחי' א\"מ שימשיכו ע\"י הכיסוי וכנ\"ל וכיוצא בזה וזהו תשאו את עון המקדש והיינו עון כהונתכ\"ם לפי ששרשם מבחי' המקיפי' דאבא כנ\"ל וד\"ל.\n<b>ואת</b> אחיך שבט הלוי הקרב כו' פי' וגם את שבט הלוי תקריב אליך שיהיו בבחי' טפל בלבד אליך ויהיו רק משמשים ומשרתים אליך וילוו עליך וישרתוך אבל אתה ובניך לפני האהל ולא הלוים כו' וזהו שאמר מיד הטעם לזה ושמרו את משמרתך ומשמרת כל האהל כו' עד וזר לא יקרב אליכם, פי' &lt;רסח&gt;\nהטעם לזה שאנכי או' וילוו עליך וישרתוך בלבד דהיינו דוקא שיהיו הגבורו' בטילי' ונכללי' בחסדי' כנ\"ל היינו מפני שעי\"ז ישמרו משמרתך כו' וזר לא יקרב ממילא אליכם כי ע\"י בחי' הביטול שלהם בתכלית אל החסדי' לא יהי' כח ליניקו' החיצונים הנק' זרים להתקרב כלל לעלו' גם הם כי יראים הם מפני בחי' המקיפי' דחסדי' דאבא שנק' משמרת האהל והוא ג\"כ מ\"ש משמרתך מפני שהם המקיפי' שנמשך ע\"י הכהנים דוקא כו' וכל שמירה הוא בחי' מקיף כידוע משא\"כ אם לא יהיו הלוים בטילי' וכפופים בתכלית לכהנים הרי מפני שהלוים שרשם מבחי' הגבורו' יוכלו גם החיצוני' שהם מבחי' פסולת הגבורו' להתקרב גם הם לקדוש' האלקי' ויוכל להיו' קצף על בנ\"י כמו שגרם קרח כשהבדיל מדרג' הלוים כנ\"ל, וזהו וזר לא יקרב אליכם שממילא יהי' כן שזר לא יקרב אליכם מפני בחי' ביטול הלוי' לגבי כהנים כאשר ילוו עליך וישרתוך בלבד וד\"ל, ונמצא ב' דברים צריך לענין הכנעת החיצוני' א' שהכהנים ישאו העון להמשיך א\"מ כמ\"ש למעלה בפי' התחלת הפ' אתה ובניך תשאו כו' והב' וגם את שבט הלוי כו' ע\"י ביטול הגבורו' בחסדי' כי אם לא בחי' ביטול הלוי' לא יועיל המשכת א\"מ דכהנים בלבד והיינו מ\"ש ושמרו משמרתך כו' וד\"ל. וחזר וכפל ענין מצוה זו באמרו עוד ואני<sup data-n=\"3888\">31</sup> הנה לקחתי הלוים לכם מתנה נתונים כו' ואתה ובניך כו'",[["3888","31","<b>ואני הנה לקחתי הלוים</b>: קרח יח, ו."]]],[2100990160,"עד והזר הקרב יומת כלומר יומת ממילא כי אין מקום לחיצונים לעלו' לקדושה בשום צד אחר מצוה זו כנ\"ל וא\"כ יומת ממילא וד\"ל.\n<b>ויובן</b> כל זה בתוספ' ביאור עפ\"י המבואר בע\"ח<sup data-n=\"3889\">32</sup> בשרש טעם הנגעים שהקליפו' יונקי' מהם דהיינו לפי שהנגע באה מסיבת הסתלקו' אור אבא כמ\"ש<sup data-n=\"3890\">33</sup> בזוהר צרעת סגירו דנהורא עילא' כו' ואין מאיר רק אור אימא בלבד ואימא מינה דינין מתערי' בסופה ע\"כ הנגע היא כלי מוכן להשרא' קליפה וכשהנגע הובא אל הכהן שהוא ממשיך מבחי' אור אבא ממילא נטהרה ואין מקום ממנה ליניקת חיצוני' והענין מבואר<sup data-n=\"3891\">34</sup> במ\"א באריכו' מפני שהחכמה נק' מקור החיים וכמ\"ש והחכ'<sup data-n=\"3892\">35</sup> תחי' וכתיב ימותו<sup data-n=\"3893\">36</sup> ולא בחכמ' שאין בחי' מיתה ושבירה בחכמ' ע\"כ בהמשכת אור אבא<sup data-n=\"3894\">37</sup> שרש הכהני' אין מקום ליניקו' החיצוני' שנק' מות כמ\"ש רגליה<sup data-n=\"3895\">38</sup> יורדו' מות וממילא מובן כאן שהלוים שהם מבחי' אור אימא בלבד כשלא יוכללו בכהנים שהם מאור אבא יוכלו החיצוני' לינק מהם וע\"כ ציוה וילוו עליך כו' ואז וזר לא יקרב אליכם ממילא דכתיב ימותו ולא בחכמה כו' וד\"ל.",[["3889","32","<b>בע\"ח בשרש טעם הנגעים</b>: ראה ע\"ח שער לאה ורחל (של\"ח) פ\"ז. לקו\"ת מצורע כד, ג. מאמרי אדה\"א ויקרא ח\"ב ע' תנג וע' תעג ואילך. דרמ\"צ ק, א ואילך. ובכ\"מ."],["3890","33","<b>כמ\"ש בזוהר צרעת סגירו דנהורא עילא'</b>: זח\"ג מט, ב."],["3891","34","<b>מבואר במ\"א באריכו' מפני שהחכמה נק' מקור החיים</b>: ראה לקו\"ת חקת ס, ג."],["3892","35","<b>והחכ' תחי'</b>: קהלת ז, יב."],["3893","36","<b>ימותו ולא בחכמה</b>: איוב ד, כא."],["3894","37","<b>אור אבא. . אין מקום ליניקו' החיצוני'</b>: ראה ע\"ח שער שבה\"כ (ש\"ט) פ\"ב ואילך. מבוא שערים ש\"ב ח\"א פ\"א. תו\"א קי, ד ואילך. קיח, ג. סידור מה, ב. ביאוה\"ז קיא, א. תו\"ח וישלח נד, א. פיה\"מ פקכ\"ו (פב, א). אוה\"ת משפטים ע' א'שז. ועוד."],["3895","38","<b>רגליה יורדות מות</b>: משלי ה, ה."]]],[2100990161,"<h3>נוסח שני: זוהר קרח מאן דעביד ימינא שמאלא</h3>\n<b></b><b>זהר<sup data-n=\"3896\">1</sup> פ' קרח תקס\"ו לפ\"ק</b>\n&lt;שצ&gt;\n\nמאן<sup data-n=\"3897\">2</sup> דעביד ימינא שמאלא ושמאלא ימינא [כו'] קרח בעא למעבד חלופא דימינא לשמאלא ר' יוסי<sup data-n=\"3898\">3</sup> אמר שמאלא איתכלל תדיר בימינא קרח בעא לאחלפא תיקונא דלעילא ותתא כו', הנה הלוים<sup data-n=\"3899\">4</sup> הם מבחי' גבו' ששרשם מאוד נעלה יותר מן החסדים וכנודע מעלת<sup data-n=\"3900\">5</sup> הזהב על הכסף ששרש הגבורות בבחי' הצמצום ומקום פנוי",[["3896","1","<b>זהר פ' קרח</b>: הנחת המהרי\"ל. נעתק מכת\"י 284 (צז, ב).\nהנחת כ\"ק אדה\"א ממאמר זה נדפס לעיל ע' תקלג.\nבהוצאה הקודמת של מאמרי תקס\"ו נדפס מאמר זה בהוספות."],["3897","2","<b>מאן דעביד. . שמאלא</b>: זוהר קרח קעו, א."],["3898","3","<b>ר' יוסי</b>: כ\"ה בהכת\"י, ולכאו' זה טעות המעתיק וצ\"ל: רבי יהודה."],["3899","4","<b>הלוים הם מבחי' גבו'</b>: ראה גם תו\"ח בראשית לו, א ובהערה 8."],["3900","5","<b>מעלת הזהב על הכסף</b>: ראה תו\"א תולדות כ, ב. תשא פו, ב. לעיל ע' תקלד."]]],[2100990162,"כו' ואח\"כ נמשך הקו והחוט בחי' חסדים ולכך לע\"ל<sup data-n=\"3901\">6</sup> יהי' הלוים כהנים כו' אלא שכ\"ז לפני אצי' אבל באצי' בעולם האצי' העיקר הם החסדים שהם בחי' שו\"ב המשכות א\"ס ב\"ה למטה וזהו ענין באר מים חיים עד\"מ כמו הבאר שנובע להיות מים שיורדים כו' והגבורות הם בחי' רצוא שהוא בחי' העלאת, ועלי' זו צורך ירידה היא כמו שיתבאר, וקרח סבר שהגבורות עיקר כמו שהן בשרשן לכך אמר מדוע<sup data-n=\"3902\">7</sup> תתנשאו כו', ויש בזה פלוגתא חד מ\"ד סבר שרצה שיהי' כמו בשרשן ממש שהחסדים בטלים להגבורות וא\"כ יהי' אהרן ומשה כפופים ובטלים אצלו וחד מ\"ד סבר שזה לא עלה על דעתו אלא להיות שמאלא איתכלל כו' והוא רצה שיהי' נפרדים להיות הגבו' בפ\"ע שלא להיות בטל אל החסד כו', והאמת הוא כי צריך להיות הגבורות בטלים להחסדים כי עלי' צורך ירידה הוא.\n<b>והענין</b> הוא כי הנה כתיב אלף<sup data-n=\"3903\">8</sup> שנים בעיניך כיום אתמול כו' ולהבין זה אם הוא בעצמות הא\"ס הרי כשמו כן הוא בלתי מוגבל ואיך יתכן בו המספר אלף שנה ויום והלא למעלה אינו נופל לשון זמן כלל אלא דהיינו בהשתלשלות הזמן כו' כי הזמן הוא השתלשלות מכלל לפרט כענין ראש השנה שנמשך כלל החיות על כל השנה ולכך<sup data-n=\"3904\">9</sup> נק' ר\"ה כמו שבראש נמשך כלל החיות שבאברים כי הגם שאין בו כח ההולכה של הרגל ממש מ\"מ החיות של כח זה כלול בראש תחילה ומשם נמשך ומתפשט באברי' לכאו\"א לפי תכונתו ואח\"כ מתחלק לפרטים כמ\"ש אדם<sup data-n=\"3905\">10</sup> נידון בכל יום כו' בכל רגע כו' וכן ר\"ח הוא ראש כלל החיות של למ\"ד יום ויש כלל יותר שית אלפי שנין<sup data-n=\"3906\">11</sup> כל אלף כלל בפ\"ע, וגם כלל יותר כל הז' אלפי שנין שהוא שמטה ועד\"ז יובל כו' ודהמע\"ה בתפלה למשה מיירי באותו כלל של אלף שנה שדוד ידע מקום השגתו של משה בתפילה זו בבריאה או ביצי' ששם הוא הכלל הזה כו' ובאמת שזה כלל מיירי בבריאה ומאי כיום אתמול כי יעבור הכלל של אלף הוא יום כי יום א' חסד כו' ושית אלפי שנין הוי עלמא שמשם נמשך זה ההשתלשלות עד שמתחלק לפרטים. והנה הפרטים הם רבים מאד, עד שי\"ב<sup data-n=\"3907\">12</sup> שעות היום הם י\"ב צרופי הוי' וי\"ב שעות הלילה הם י\"ב צרופי אדנ\"י שיש שינוי בהמשכות כח החיות בין יום ללילה וכמארז\"ל לא<sup data-n=\"3908\">13</sup> איברי לילה אלא לגירסא ולחד מ\"ד לשינה, ויש פירות שצומחין ביום דוקא ממגד<sup data-n=\"3909\">14</sup> תבואות שמש ויש ממגד גרש ירחים, והנה המשכות כח התחלקות בפרטים רבים הוא מקור הגבורות והוא ע\"י הלוים &lt;שצא&gt;\nוהם קבלו מי\"ב<sup data-n=\"3910\">15</sup> נשיאים והם י\"ב",[["3901","6","<b>לע\"ל יהי' הלוים כהנים</b>: ראה ספר הגלגולים פכ\"ג. תניא פ\"נ. לעיל ע' תקלד."],["3902","7","<b>מדוע תתנשאו</b>: קרח טז, ג."],["3903","8","<b>אלף שנים בעיניך</b>: תהלים צ, ד."],["3904","9","<b>ולכך נק' ר\"ה</b>: ראה ג\"כ עטרת ראש בתחלתו."],["3905","10","<b>אדם נידון בכל יום</b>: ר\"ה טז, א."],["3906","11","<b>שית אלפי שנין</b>: ראה ר\"ה לא, א."],["3907","12","<b>שי\"ב שעות. . י\"ב צירופי הוי'</b>: ראה תניא פמ\"א (נח, ב). ובס' שיעורים בתניא שם. וראה רשימות מכ\"ק אדמו\"ר זי\"ע חוברת קמא. לעיל ע' תקלה."],["3908","13","<b>לא איברי לילה אלא לגירסא</b>: ראה עירובין סה, א."],["3909","14","<b>ממגד תבואות שמש</b>: ברכה לג, יד."],["3910","15","<b>מי\"ב נשיאים והם י\"ב גבולי אלכסון</b>: ראה ספר הבהיר (סמ\"ב) סצ\"ד-ה. מאמרי אדה\"א דברים ח\"ב ע' תסז. וש\"נ."]]],[2100990163,"גבולי אלכסון שש<sup data-n=\"3911\">16</sup> עגלות צב ושנים עשר בקר כו' וכענין י\"ב<sup data-n=\"3912\">17</sup> בקר והים עליהם מלמעלה ועי\"ז ונשאו<sup data-n=\"3913\">18</sup> את המשכן ואת הארון ממכ\"ע הכל בחי' העלאות ועד\"ז הי' כל המסעות כנודע ואח\"כ והוא ימשל בך להיות המשכות מ\"ה החסדים והוא ענין המתקת הגבורות וגם מתחילה קודם שנשאו כתיב ובא<sup data-n=\"3914\">19</sup> אהרן ובניו וכיסו כו' ולא יבוא לראות כבלע כו' לפי שהמסעות שלהם הי' במדבר מקום יניקת החיצונים ולכן עשו הכהנים כיסוי מכסה עור תחש כו' בחי' מקיפים שמסמא עיני החיצונים ולא היו רשאים לעמוד אצל זה כי צריך להיות בחי' כהנים דוקא בחשאי כו'. וע\"י המקיפים נעשה ב' פעולות א' שלא יהי' יניקה לחיצונים כי הם מקבלים ממ\"ח<sup data-n=\"3915\">20</sup> צירופי אלקים באדמת בני חם אבל בהע\"ב הנותרים אין להם יניקה כלל. והב' שכדי שיהי' להתחתון כח לעלות מוכרח לירד הארת מקיף עליון כענין ברוך א\"י אמ\"ה כו' ונודע שלפני אתעדל\"ת קדמה אתעדל\"ע כו' והרי נתבאר שעיקר הדבר נעשה ע\"י הכהנים בין בתחילה בהמשכת הכיסויים בין בסוף בהמשכות החסדים שעליות הלוים צורך ירידה היא להיות המתקות הגבורות בחסדים כנ\"ל.\n<b>אך</b> קרח לא רצה זה ואמר מדוע תתנשאו כו' כלומר למה האתם העיקר לבלתי היות אפי' עליות הלוים בלי המשכות המקיפים כו' ולא רצה ליכלל באהרן שהוא בנצח אבא בחי' החסדים, ולכן אחר שנענש קרח כתיב ואני<sup data-n=\"3916\">21</sup> הנה לקחתי את אחיכם הלוים כו' מתנה נתונים, וילוו<sup data-n=\"3917\">22</sup> עליך וישרתוך היפך כוונת קרח וזר<sup data-n=\"3918\">23</sup> לא יקרב עליכם כלומר שלא יהי' יניקת החיצוני' כי אהרן<sup data-n=\"3919\">24</sup> בחי' אבא והוא ביטול יניקתם וכענין שמבואר שהם סגירו<sup data-n=\"3920\">25</sup> דנהורא דאבא פי' שהם בעצמם אינו קליפה כלל רק שבמניעת נהורא דאבא רק בחי' אימא יש יניקה לחיצונים ולכן יבוא אל הכהן בחי' אבא וכמ\"ש ימותו<sup data-n=\"3921\">26</sup> ולא בחכמה כי החכמה<sup data-n=\"3922\">27</sup> תחי' כו' וד\"ל.",[["3911","16","<b>שש עגלות צב ושנים עשר בקר</b>: נשא ז, ג."],["3912","17","<b>י\"ב בקר והים עליהם</b>: מלכים-א ז, כה. מד. דברי הימים-ב ד, טו."],["3913","18","<b>ונשאו את המשכן</b>: ראה נשא ד, כה."],["3914","19","<b>ובא אהרן ובניו וכיסו</b>: ראה נשא ד, ה."],["3915","20","<b>ממ\"ח צירופי אלקים באדמת בני חם</b>: ראה פע\"ח שער (כא) חג המצות פ\"ה ע\"ח שער (טו) הזיווגים פ\"ו. שער (מד) השמות פ\"ה."],["3916","21","<b>ואני הנה לקחתי את אחיכם הלוים</b>: קרח יח, ו."],["3917","22","<b>וילוו עליך וישרתוך</b>: שם ב."],["3918","23","<b>וזר לא יקרב</b>: שם ד."],["3919","24","<b>אהרן בחי' אבא</b>: ראה סידור שער בהמ\"ז קז, ב. מאמרי אדה\"א שמות ח\"ב ע' שלד וע' תקד. וש\"נ."],["3920","25","<b>סגירו דנהורא דאבא</b>: ראה זהר תזריע מט, ב. ע\"ח (שער לאה ורחל) של\"ח, פ\"ז."],["3921","26","<b>ימותו ולא בחכמה</b>: איוב ד, כא."],["3922","27","<b>החכמה תחי'</b>: ראה קהלת ז, יב."]]],[2100990164,"<h3>אז ישיר ישראל</h3>\n<b>שבת פ' חקת בלק</b>\n&lt;רסט&gt;\n\nאז<sup data-n=\"3923\">1</sup> ישיר ישראל את השירה הזאת עלי באר ענו לה. באר חפרוה שרים כרוה נדיבי עם במחוקק במשענותם<sup data-n=\"3924\">2</sup>. כתיב מעיין<sup data-n=\"3925\">3</sup> גנים באר מים חיים ונוזלים מן לבנון, פי' כנ\"י נקראת באר מים חיים כי הנה עד\"מ הבאר שהמעיינות נובעין בו מתחת לארץ כי ארעא<sup data-n=\"3926\">4</sup> חלחולי מחלחלא כו' ודרך<sup data-n=\"3927\">5</sup> סולמא דפרת נובעים המים מתחת לארץ מלמטה למעלה ובתחלה הרי המים נמשכי' המה מלמעלה כמ\"ש למטר<sup data-n=\"3928\">6</sup> השמים תשתה מים וכתי' ונהר<sup data-n=\"3929\">7</sup> יוצא מעדן כו' אך אז הן נקראי' עדיין מים עליונים וכאשר אח\"כ דרך סולמא דפרת חוזרין ונובעין דרך עובי הכדור מלמטה למעלה נק' מים חיים והן מים שבבארות דוקא שנקראו מים חיים לפי שעברו מלמטה למעלה דרך עובי עפר הארץ ונתבררו ונעשי' צלולים ואזי חיין ומתוקין המה משא\"כ קודם עברם את עפר הארץ מלמטה למעלה אלא המה באי' ונמשכי' בד' נהרות מלמעלה למטה לא נקראו עדיין בשם מים חיים כו' והרי מובן לפ\"ז שכל עיקר הבאת המים בעפר הארץ הוא כדי שיתוקנו ויקראו בשם מים חיים וכך יובן הנמשל בכנ\"י שנקראת באר מים חיים דוקא לאחר ירידת הנשמו' בגופים בעוה\"ז לפי שישראל<sup data-n=\"3930\">8</sup> עלה במחשבה הקדומה היינו כמו שהנשמו' המה בבחי' שרש ומקור הראשון דכנ\"י שהוא ע\"ד דוגמא מנהר שיוצא מעדן כו' (והוא מבחי' מיין<sup data-n=\"3931\">9</sup> דוכרין) וירדו אח\"כ מלמעלה למטה בסדר בחי' השתלשלו' העולמו' עד שבאים ומתלבשים בחומר גופני בעוה\"ז שהוא כדוגמת משל עפר הארץ בחי' דומם גשמי ומשם הנשמות חוזרי' ונובעים לצאת ממחשך החומריו' הזאת בתשובה (שהוא בחי' מ\"נ) ואזי נקראו הנשמו' בשם מים חיים דוקא כי עי\"ז עולי' בבחי' בירור מלמטה למעלה וזהו ביום<sup data-n=\"3932\">10</sup> ההוא יצאו מים חיים מירושלים חציים אל הים הקדמוני כו' וכמ\"ש בסמוך.\n<b>אך</b> הנה כדי להבין ביאור הדברים תחלה יש להבין מהו פי' מעיין גנים שהוא ענין ירידת כנ\"י מלמעלה למטה בתחלה כנ\"ל. הנה כתיב ונהר יוצא מעדן להשקות את הגן, פי' עד\"מ הגן הגשמי צריך הוא להיות בו מעיינות הולכי' ומשקין אותו בתמידו' בכדי שיהי' הגן רוה ממשקה המים ויצמיח כל טובי הארץ מפירו' ואילנו' וכל מיני תענוגי בנ\"א כי המים<sup data-n=\"3933\">11</sup> מצמיחי' כל מיני תענוג ואם אין המעיינו' מספיקין",[["3923","1","<b>אז ישיר</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק אדה\"א 1025 (עב, א).\nמאמר זה זה באריכות מכ\"ק אדמו\"ר האמצעי נדפס במאמרי אדה\"א חוקת ע' א'תמז ואילך.\nהנחת המהרי\"ל נדפס בלקו\"ת חוקת סב, ב. ובתוס' הגהות באוה\"ת חוקת ע' תתס. וראה שם ע' תתעט — מהו נהר ומעיין [מגוכתי\"ק 1114 בכותרת: שייך לעלי באר תקס\"ו]."],["3924","2","<b>אז ישיר. . במשענותם</b>: חוקת כא, יז-יח."],["3925","3","<b>מעיין גנים באר מים חיים</b>: שה\"ש ד, טו."],["3926","4","<b>ארעא חלחולי מחלחלא</b>: חגיגה כב, א."],["3927","5","<b>ודרך סולמא דפרת</b>: ראה בכורות נה, ב."],["3928","6","<b>למטר השמים תשתה מים</b>: עקב יא, יא."],["3929","7","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["3930","8","<b>שישראל עלה במחשבה</b>: ב\"ר בתחלתו."],["3931","9","<b>מיין דוכרין</b>: ראה גם לקו\"ת עקב יז, ד. שה\"ש לז, ב."],["3932","10","<b>ביום ההוא יצאו מים חיים מירושלים</b>: זכרי' יד, ח."],["3933","11","<b>המים מצמיחי' כל מיני תענוג</b>: ראה תניא פ\"א (ה, סע\"ב)."]]],[2100990165,"צריך להביא מים בכתף ולהשקות את הגן ומלבד מטר השמים דלא סגי בלא\"ה כו' וכל זאת ההשקאה הוא רק להגדיל הצמחים וכך יובן הנמשל במעיין גנים העליונים דכתיב ונהר יוצא מעדן להשקות את הגן היינו בחי' גילוי אלקות שמתגלה ומאיר בג\"ע העליון ובג\"ע התחתון שהן הנקראים בשם גנים עד שהנשמו' נהנין שם מזיו השכינה כו' ותענוג זה נגדל ונצמח דהיינו בתוספת אור וגילוי תמיד מפני סיבת ההשקאה ממעיינו' שנובעי' בגנים הללו ג\"ע עליון ותחתון והיינו מ\"ש ונהר יוצא מעדן להשקו' את הגן פי' להשקו' ג\"ע עליון ותחתון והיינו להיו' כי הנהר<sup data-n=\"3934\">12</sup> הוא בחי' בינה ושם מתגלה בחי' מקור כל התענוגי' שנק' כתר עליון שלמעלה גם מן החכמה ומשם נעשה בחי' זיו השכינה למטה כלומר בחי' &lt;ער&gt;\nמקור כל התענוגי' שמתענגי' הנשמו' ונהנין מזיו כו' וה\"ז ממש כמעיין המשקה את הגן ועי\"ז בא סיבת גידול צמחים שבו כו'.\n<b>אך</b> מ\"ש ונהר יוצא מעדן דמשמע שיוצא מן ההעלם לבחי' גילוי כמו המעיין שנובע בהעלם כו' כי הנה הוא ית' נקרא סתימו<sup data-n=\"3935\">13</sup> דכל סתימין וצריך להביאו לבחי' גילוי מן ההעלם להיו' מקור המעיין וזהו פי' מעיין גנים כו' מפני שזהו נעשה ע\"י ירידת כללו' נ\"י מלמעלה שעלו במחשבה סתימאה ואח\"כ למטה בהתלבשו' בגופים ועושין מצות מעשיו' נקראו באר מים חיים כי ירידה זאת צורך עלי' היא כו' כי הנה כתיב ויניחהו<sup data-n=\"3936\">14</sup> בג\"ע לעבדה ולשמרה לעבדה זו רמ\"ח מ\"ע ולשמרה שס\"ה מצות ל\"ת ואע\"פ שכבר נברא גן בעדן מקדם אך להוסיף ולהגדיל הצמח בג\"ע הניחו לאדם שם שיעבוד וישמור הג\"ע והוא ע\"י המצות שיעשה האדם דוקא והענין הוא לפי שהמצות בשרשן המה בחי' פנימי' רצון העליון והוא הנק' רצון הפשוט הנעלם והם הנק' ג\"כ רמ\"ח<sup data-n=\"3937\">15</sup> איברי' דמלכא אח\"כ והיינו כשבא הרצון לידי סוף<sup data-n=\"3938\">16</sup> מעשה כמאמר סוף מעשה עלה במחשבה תחלה פי' סוף מעשה הוא בחי' מעשה המצות למעלה בגשמיות להיו' חסד<sup data-n=\"3939\">17</sup> אל כל היום להחיו'<sup data-n=\"3940\">18</sup> רוח שפלים כו' זהו מצות צדקה וכיוצא בזה וסוף מעשה זה עלה דוקא בתחלת המחשבה עליונה שהוא בחי' הרצון הפשוט כו' דלית מחשבה תפיס' שם אפי' מחשבה דא\"ק והטעם ידוע משום דנעוץ<sup data-n=\"3941\">19</sup> תחלתן בסופן דוקא וכמשל אבן ראש החומה שהיתה עומדת יותר בגובה כשנופלת החומה תמצא בתחתית יותר כו' כך תחלת המחשבה תמצא דוקא בסוף מעשה כו' וד\"ל.",[["3934","12","<b>הנהר הוא בחי' בינה</b>: זהר (אדרא דמשכנתא) משפטים קכג, ב."],["3935","13","<b>סתימו דכל סתימין</b>: זח\"ב פט, א. קמו, ב. וראה תקו\"ז בהקדמה (יז, א)."],["3936","14","<b>ויניחהו בג\"ע לעבדה ולשמרה לעבדה זו רמ\"ח מ\"ע</b>: בראשית ב, טו. זח\"א כז, א. תקו\"ז תכ\"א בסופו."],["3937","15","<b>רמ\"ח אברי' דמלכא</b>: ראה תק\"ז ת\"ל (עד, סע\"א)."],["3938","16","<b>סוף מעשה עלה במחשבה תחלה</b>: פיוט לכה דודי."],["3939","17","<b>חסד אל כל היום</b>: תהלים נב, ג."],["3940","18","<b>להחיו' רוח שפלים כו' זהו מצות צדקה</b>: ישעי' נז, טו. ראה תו\"ח לך לך פג, ב. שערי אורה יב, א. כה, ב. ובכ\"מ."],["3941","19","<b>דנעוץ תחלתן בסופן</b>: ס\"י פ\"א מ\"ז."]]],[2100990166,"<b>וע\"כ</b> בעבודת האדם במעשה המצות ג\"כ למטה כמו בג\"ע הארץ הנה הוא מוסיף בו אור גדול מפני שמרחיב את המקור של המעיין שיצא וימשך בגילוי רב מבחי' ההעלם ואע\"פ שנאמר כבר ונהר יוצא מעדן מן ההעלם לגילוי כו' זה הי' רק בצמצום כפי המדה הראשונה אבל להוסיף אור אין זה אלא ע\"י המצו' מטעם שנעוץ תחלתן בסופן ומעוררי' תחלת המחשבה שהוא בחי' הרצון הפשוט שלמעלה גם מבחי' חכמה דא\"ק כו' וזהו ביום ההוא יצאו מים חיים מירושלים חציים אל הים הקדמוני כו' משום דסוף מעשה עלה במחשבה תחלה וד\"ל.\n<b>וזהו</b> מעיין גנים באר מים חיים פי' עד\"מ המים העליונים שיורדים ומסבבי' לארץ מתחת וחוזרים ונובעים דרך עובי הכדור מלמטה למעלה ואז נקראו דוקא מים חיים כך הנשמות שעלו במחשבה תחלה כשיורדי' למטה ומתלבשים בגופים גשמיים ובאים לידי בחי' סוף מעשה שהוא מעשה המצות הנה עי\"ז נק' עד\"מ בשם מים חיים כי הרי נתבררו בעברם בחומריו' הגוף ובפועל המעשה של המצו' שמלובשים בענינים גשמיים כמו צמר הציצית וקלף התפילין וכו' אך מפני שסוף מעשה זו דוקא עלה בתחלת המחשבה שהוא הרצון הפשוט יש בכחן להמשיך תוספת גילוי מן ההעלם להיו' מקור למעיינו' ההולכי' בג\"ע העליון והתחתון כמו הבאר שמים החיים שבו נובע מן ההעלם שמתחת לארץ והוא נעשה מקור למעיינו' שבגובה הארץ כו' וזהו שאמר ויניחהו בג\"ע לעבדה כו' וכנ\"ל והיינו שאמר תחלה מעיין גנים ואח\"כ &lt;רעא&gt;\nבאר מים חיים כי תחלת אור השפע באה בג\"ע עליון ותחתון מלמעלה למטה כנ\"ל ואח\"כ ע\"י הנשמות שבעוה\"ז עולה אור השפע למעלה מלמטה דוקא ומזה נמשך להיות המעיין בגנים למעלה בתוספת גילוי אור כו' (והוא בבחי' אור חוזר כמ\"ש<sup data-n=\"3942\">20</sup> במ\"א בפי' הראיני את מראייך כו') וד\"ל. וזהו ענין הברכו' של המצות בא\"י הוא בחי' המשכה מלמעלה למטה להיו' מלך העולם בגילוי אור בג\"ע העליון והתחתון כנ\"ל ואח\"כ אשר קדשנו במצוותיו כו' מלמטה למעלה כנ\"ל וכל ניצוץ אלקי טרם בואו לעוה\"ז בגוף כבר עבר דרך הגנים הנ\"ל וירד למטה בשביל עבודת ג\"ע להוסיף ולהגדיל האור ולהיו' על ידו נעשה באר מים חיים כו' וד\"ל.\n<b>והנה</b> כללות<sup data-n=\"3943\">21</sup> כל המצות הוא מצות הצדקה כידוע ומתוכה נבין בעיקר ענין המצות שהוא ע\"ד הנ\"ל להיו' מהם מקור למעיין גנים הנ\"ל כי הנה הצדקה ידוע שעיקר מצוותה מהשגת ידו דוקא והיינו במה שטרח וייגע ומרויח ממנו ביגיעת כפו במה שנשא ונתן באמונה כו' והרי מו\"מ זה בעניני' גשמיים מאד ודאי מגשימי' הנפש האלקי' ג\"כ ואמנם אח\"כ הוא נותן פרוטה לעני מיגיעה זו והפרוטה נעשה חיו' לעני בב' מדרגו' בבחי' א\"פ והוא המזון לחם וכיוצא וא\"מ והן הלבושים כמ\"ש כי<sup data-n=\"3944\">22</sup> תראה ערום וכסיתו כו' וזהו מצות הצדקה בגשמיו' ובאתעדל\"ת",[["3942","20","<b>כמ\"ש במ\"א בפי' הראיני את מראייך</b>: שה\"ש ב, יד. וראה לקו\"ת שה\"ש טז, ב."],["3943","21","<b>כללות כל המצות הוא מצות הצדקה</b>: ראה ב\"ב י, א."],["3944","22","<b>כי תראה ערום וכסיתו</b>: ישעי' נח, ז."]]],[2100990167,"אתעדל\"ע ג\"כ מעורר מצות הצדקה למעלה והוא להחיו' רוח שפלים מאין ליש להיו' השפעה לנשמו' ומלאכי' בג\"ע עליון ותחתון כו' היינו ג\"כ ע\"ד הזה דהיינו מבחי' המעשה דרמ\"ח איברי' דמלכא במה שטרח וייגע לעבודת הברורי' דרפ\"ח כו' בכל ו' ימי המעשה ואע\"פ שהגשימו בזה האור כמשל המו\"מ כו' לפי ערך מ\"מ ע\"י מצות הצדקה להחיו' רוח שפלים זה בגילוי אור לנשמו' ומלאכי' מתעלה כל מה שירד מן האור כו' והכל מפני שסוף מעשה דוקא עלה בתחלת המחשבה וד\"ל והצדקה עליונה הזאת נעשי' לנשמו' ומלאכי' בג\"ע בחי' א\"פ ובחי' א\"מ והן בחי' מזון ולבוש כמשל צדקה למטה בפרוטה לעני כנ\"ל וזהו מ\"ש אז<sup data-n=\"3945\">23</sup> תתענג על הוי' כו'.\n<b>דלכאורה</b> אינו מובן מהו על הוי' למעלה משם הוי' כו' אך הענין הוא דכאשר הנשמו' נהנין מזיו השכינה בג\"ע יש בזה ב' מדרגו' הא' אשר משיגים בהשגה ממש כמו שמשיג האדם איזה שכל וסברא שאז נתפס אור אלקי ומוקף בתוך השגתם והשגתם מקפת לאור האלקי שהשיגו וכנראה בחוש במשיג שכל המושג דהדבר המושג מוקף בתוך השכל המשיגו וזהו הנק' בחי' א\"פ והיינו שנק' מזון לנשמו' כמ\"ש ותורתך<sup data-n=\"3946\">24</sup> בתוך מעי ממש כו' וזהו אז תתענג על הוי' ששם הוי' הוא בחי' ממלא כ\"ע הוא הנק' זיו השכינה ולהיותו מוקף בהשגה שמשיגי' אותו הנשמו' כנ\"ל הרי השגו' הנשמו' מקיפי' אותו ולכך הם על הוי' למעלה משם הוי' כו' כי נתפס בתוך השגתם אבל מה שא\"א להתקבל בהשגתם כלל ואז נשאר האור עליהם בבחי' מקיף וחופף עליהם זהו הנק' לבושי' בג\"ע וזהו מ\"ש אז<sup data-n=\"3947\">25</sup> יבקע כשחר אורך כו' עד והלך לפניך צדקך בבחי' א\"פ וכבוד הוי' יאספך פי' בבחי' מקיף יסבב אותך כו' והן בחי' א\"פ וא\"מ שהן כמו מזונות ולבושי' לעני למטה &lt;ערב&gt;\nוהיינו רק ע\"י מעשה המצות שעשו הנשמו' בעוה\"ז דוקא וכמ\"ש והלך לפניד צדקך כי נקראי' סוף מעשה כנ\"ל אך הצדקה היא כללו' כולם ואמנם מתוכה נבין בעיקר כל המצות שהם רק בחי' ברורי' שכאשר עולין מן ההגשמה אזי עולין בתכלית הבירור עד\"מ המים שעוברי' עפר הארץ שנעשי' צלולי' בתכלית ומזה נעשה מקור לגנים להיו' א\"פ וא\"מ לנשמות וד\"ל (ומזה יובן שיש שיעור בזה לנשמות בכל חד לפום שיעורא דילי' למעלה אם יהי' עוסק במו\"מ הרבה או מעט כי עסק המו\"מ נמשל לעפר שמגשם האור דנפש האלקי' כנ\"ל ולפי ערך הגשמת העפר את המים אם רב כמאה אמה או מעט כי' אמות בעומק עובי הארץ כך יהי' ערך הגשמת מו\"מ לנשמו' בהתלבשו' שלהם בגופים בעוה\"ז אם רב או מעט והוא כפי הרצון המצטרך מן הברורי' דרפ\"ח כו' ולפי אותו ערך שרש הנשמה למעלה כמו שהיא במחשבה עילא' כו' וד\"ל).\n<b>וזהו</b> אז ישיר ישראל עלי באר כו' באר חפרוה שרים כו'. פי' ישראל הוא בחי' ניצוץ האלקי שבאדם דישראל עלה במחשבה עילאה כנ\"ל וירד מלמעלה",[["3945","23","<b>אז תתענג על הוי'</b>: ישעי' נח, יד."],["3946","24","<b>ותורתך בתוך מעי</b>: תהלים מ, ט."],["3947","25","<b>אז יבקע כשחר. . והלך לפניך צדקך. . וכבוד ה' יאספך</b>: ישעי' נח, ח."]]],[2100990168,"למטה דרך הגנים הנ\"ל ונתלבש בחומר גופני בעוה\"ז לקיים מצות מעשיו' וירידה זו צורך עלי' וע\"כ אמר אז ישיר ישראל דוקא עלי באר פי' כי ע\"י המעיין גנים הנ\"ל מקבל מבחי' באר והוא בחי' מים תחתונים שנובעי' מלמטה למעלה ע\"י המצות שמגלין למעלה מן ההעלם דרצון הפשוט מטעם שסוף מעשה דוקא עלה במחשבה תחלה והיינו עלי באר לתחלת המחשבה וד\"ל.\n<b>באר</b> חפרוה שרים כו' פי' ענין חפירת אותו הבאר הוא להסיר העפר הגס המונע ומעכב גילוי בקיעת המים החיים שיהיו נובעים מלמטה למעלה כו' כך ניצוץ האלקי להיותו מוסתר ומלובש בחומר נפש הבהמיו' המחשיך מאד ומונע גילוי אור הנפש האלקי' לעלו' מלמטה למעלה בבחי' באר מים חיים כנ\"ל וע\"כ צריך לחפור ולהסיר עפר חומר הבהמיו' והיינו בב' דברי' א' בהתבוננו' בנפש המשכלת להבין ולהשכיל בגדולת ה' איך שבמאמר א' נבראו הכל וכולא<sup data-n=\"3948\">26</sup> קמי' כלא כו' וצבא<sup data-n=\"3949\">27</sup> השמים כולם הם בבחי' הביטול במציאות בתמידו' שהרי נא' משתחווים לשון הווה ולא ישתחוה או השתחוה ולהתבונן במשל הידוע איך שהדיבור בטל הוא ונכלל במחשבה כך דיבור העליון דבדבר<sup data-n=\"3950\">28</sup> ה' שמים נעשו וברוח פיו כל צבאם בטל ונכלל בעצמו' אור האלקי כמ\"ש לך<sup data-n=\"3951\">29</sup> ה' הגדולה כו' והיינו שאו' בב\"ש וכל פסוקי דזמרה מענין ביטול המלאכי' וכו' וכמו והאופנים<sup data-n=\"3952\">30</sup> ברעש גדול כו' ואזי כשמגיע לק\"ש ממילא בא לאהבת בכל לבבך ובכל מאדך כו' שהוא ביטול הרצון במס\"נ כמ\"ש אליך<sup data-n=\"3953\">31</sup> ה' נפשי אשא וכמאמר בע\"כ<sup data-n=\"3954\">32</sup> אתה חי כו' להיו' החיו' בגוף בע\"כ וגם בכל צרכי פרנסה יהי' העסק בע\"כ כמאן<sup data-n=\"3955\">33</sup> דשדי בתר כתפי' והוא דרך מעבר בלבד ולא דרך קבע כו' וביטול רצון זה ישנו בב' מדרגו' הא' בבחי' האהבה לה' כמ\"ש מי<sup data-n=\"3956\">34</sup> לי בשמים ועמך לא חפצתי כו' וכנ\"ל והב' בביטול רצון זר היפך אלקו' והוא להיו' סור מרע בפ\"מ גם בתאוו' היתר באהבה לה' יבטל הרצון שיעשה הטוב יותר מכפי &lt;רעג&gt;\nטבעו ורגילותו כמו בלימוד התורה ללמוד יותר מחפצו בטבע וכן במצות מעשיות לעשות נגד הרצון הטבעי כמו בפיזור ממון לצדקה וכיוצא ובסור מרע לכבוש תאוו' היתר ג\"כ וכל אלה המה בחי' ביטול עצמותו ואינם באים אלא ע\"י חפירה כמו עד\"מ החופר בקרקע קשה כך חפירת הרע הוא בכפייה לאכפייא ולכבוש יצרו כו' וזהו כמשל החופר ומסיר עפר הגס ועב כמו גוש וחתיכה גדולה והיינו פי' חפרוה והוא בסור מרע כנ\"ל ופי' כרוה היינו עפר הדק ואינו בחתיכו' גסות כ\"כ ג\"כ יסיר ויחפור והיינו משל להסרת הרע הגשמי ביותר ולדק ביותר וזה בא ע\"י ב' דברים א' ע\"י ההתבוננות כנ\"ל והב' ע\"י לאכפייא כו' וכל זה נק' חפירה עד\"מ וזהו באר חפרוה כו' ואז ממילא נעשי' הנשמ' האלקי' בבחי' באר מים חיים כנ\"ל וד\"ל.",[["3948","26","<b>וכולא קמי' כלא</b>: זח\"א יא, ב."],["3949","27","<b>וצבא השמים. . משתחווים</b>: נחמי' ט, ו."],["3950","28","<b>דבדבר ה' שמים נעשו</b>: תהלים לג, ו."],["3951","29","<b>לך ה' הגדולה</b>: דברי הימים-א כט, יא."],["3952","30","<b>והאופנים ברעש גדול</b>: נוסח התפלה."],["3953","31","<b>אליך ה' נפשי אשא</b>: תהלים כה, א."],["3954","32","<b>בע\"כ אתה חי</b>: אבות ספ\"ד."],["3955","33","<b>כמאן דשדי בתר כתפי'</b>: ראה תניא פכ\"ב (כז, ב). קונטרס ומעיין מאמר ב פרק ב ואילך. מאמר ז ואילך."],["3956","34","<b>מי לי בשמים ועמך לא חפצתי</b>: תהלים עג, כה."]]],[2100990169,"<b>ומה</b> שאמר באר חפרוה שרים היינו האבות שנקראו שרים והיינו ע\"י בחיר<sup data-n=\"3957\">35</sup> האבות דוקא שהוא יעקב הנק'<sup data-n=\"3958\">36</sup> בריח התיכון כו' ולכך נא' בו ואלקי<sup data-n=\"3959\">37</sup> יעקב בוי\"ו שהוא המחבר הכל כו' והטעם שנק' בשם שרים כי ביעקב נאמר כי שרית<sup data-n=\"3960\">38</sup> עם אלקים ועם אנשים, פי' אלקים<sup data-n=\"3961\">39</sup> הוא בחי' הצמצום כידוע דשם אלקים הוא המצמצם ומסתיר אור האלקי להיות מלכותו<sup data-n=\"3962\">40</sup> בכל משלה ואם לא בחי' הצמצום הזה לא הי' נמצא מציאת עולמו' הנבראי' יש מאין כמ\"ש במ\"א וכאשר מסירי' בחי' ההסתר הזה ממילא נגלה אור האלקי שלמעלה מן העולמו' והסרת הצמצום וההסתר הזה הוא ע\"י יעקב וזהו שנא' בו כי שרית עם אלקים כלומר שעשה באלקים בחי' השתררות להשתרר על הצמצום הזה להיו' מתגלה מן ההעלם ומושל בו להיו' מן ההעלם גילוי וזהו שאמר יעקב והי'<sup data-n=\"3963\">41</sup> הוי' לי לאלקים פי' במקום שם אלקים המצמצם יהי' בחי' הוי' שהוא בחי' התגלו' אלקו' כמו שהוא לפני הצמצום והיינו שהוי' דוקא יהי' לי לאלקים ולא שם אלקים עצמו שהוא בחי' הצמצום וד\"ל.\n<b>ועם</b> אנשים, פי' אנשים הם המלאכי' כמו באברהם דכתיב וירא<sup data-n=\"3964\">42</sup> והנה ג' אנשים נצבים כו' שבאו ג' מלאכים בשביל ג'<sup data-n=\"3965\">43</sup> שליחות א' לבשר את שרה וכו' כידוע הטעם מפני שאין<sup data-n=\"3966\">44</sup> מלאך אחד עושה ב' שליחות והענין הוא כי בחי' מלאך היינו בחי' השפעה שנשפעת ע\"י שליח מלמעלה והוא כמו הצינור שבו יעבור אור השפע מלמעלה למטה שההשפעה עוברת דרך כלי דוקא למקבלים ואין כח בכלי אחד לקבל שתי שליחות לפי שכל שליחו' ענין השפעה בפ\"ע והכלי מיוחדת רק להשפעה א' וע\"כ אין כח במלאך לקבל ולסבול ב' שליחות אלא כל א' עושה שליחותו בלבד כו' וזהו מטעם שהמלאכים המה מבחי' עולם הפירוד וכמ\"ש ומשם<sup data-n=\"3967\">45</sup> יפרד כו' ונק' ג'<sup data-n=\"3968\">46</sup> עולמות בשם עלמא דפרודא כידוע וע\"כ אין מלאך א' יכול לקבל ב' שליחו' כי בבחי' עולם הפירוד השפע בחי' התחלקות באה להיו' כל חלק מיוחד בפ\"ע וע\"כ כל השפעה בכלי מיוחד ואין כלי א' סובלת ב' חלקי השפעה כא' כנ\"ל וכל זה מפני שהמלאכים לא קיבלו את התורה כי התורה מלמעלה מבחי' ההתחלקו' היא",[["3957","35","<b>בחיר האבות. . יעקב</b>: שער הפסוקים תולדות כז, כה. וראה ג\"כ ב\"ר רפע\"ו. זח\"א קיט, ב. קמז, ב."],["3958","36","<b>הנק' בריח התיכון</b>: ראה זהר תרומה קעה, ב."],["3959","37","<b>ואלקי יעקב בוי\"ו</b>: ראה ג\"כ תו\"א ויצא כג, א. ויקהל קטו, ד. לקו\"ת דרושים לר\"ה נו, א."],["3960","38","<b>כי שרית עם אלקים ועם אנשים</b>: וישלח לב, כט."],["3961","39","<b>אלקים הוא בחי' הצמצום</b>: נסמן לעיל ע' תלט."],["3962","40","<b>מלכותו בכל משלה</b>: לשון הכתוב תהלים קג, יט."],["3963","41","<b>והי' הוי' לי לאלקים</b>: ויצא כח, כא."],["3964","42","<b>וירא והנה ג' אנשים נצבים</b>: וירא יח, ב."],["3965","43","<b>ג' שליחות א' לבשר את שרה</b>: ב\"מ פו, ב."],["3966","44","<b>שאין מלאך אחד עושה ב' שליחות</b>: ב\"ר פ\"נ, ב. מדרש הנעלם (ח\"ש קכז, א). וברש\"י וירא יח, ב. וראה גם ביאוה\"ז נח, ו. בלק צט, ב. לקו\"ת אמור לז, ג. שה\"ש מ, ג. סה\"מ תקס\"ח ח\"ב ס\"ע תרטז ואילך. ועוד."],["3967","45","<b>ומשם יפרד</b>: בראשית ב, י."],["3968","46","<b>ג' עולמות בשם עלמא דפרודא</b>: ראה ע\"ח שער מג (שער ציור עולמות) בהקדמה להדרוש. ובכ\"מ."]]],[2100990170,"ולישראל<sup data-n=\"3969\">47</sup> דוקא ניתנה ולא ניתנה למלאכי' הגם שביקשו תנה<sup data-n=\"3970\">48</sup> הודך על השמים כידוע והטעם כי אוריי'<sup data-n=\"3971\">49</sup> מחכמה עילא' נפק' וישראל ג\"כ עלה במחשבה כו' וכמאמר תלת<sup data-n=\"3972\">50</sup> קשרין אינון כו' ולזה הטעם שהתורה בבחי' החכמה עילאה היא ע\"כ היא &lt;עדר&gt;\nלמעלה מבחי' ההתחלקו' בכלים וע\"כ יכול להיות בה היפך ענין הנ\"ל במלאך שאינו יכול לעשו' שתי שליחות אבל בתורה נא' אחת<sup data-n=\"3973\">51</sup> דבר אלקים שתים זו שמעתי דאע\"פ שהדיבור אחד הוא בלבד שומעים ממנו שתים כי דבר א' יסבול ב' דברים וכיוצא בזה בכל דברי תורה גם באות א' שבתורה יכולים למצוא כל חלקי התורה וכמ\"ש<sup data-n=\"3974\">52</sup> על מ\"ש וכפטיש יפוצץ סלע מה פטיש זה ניצוץ א' מתחלק לכמה חלקים כו' ועיקר הטעם הוא כי התורה מחכמ' עילא' היא ששם הוא למעלה מבחי' התחלקו' אלא הוא בבחי' ההתכללו' לכלול הכל כא' משום דבאור א\"ס שבחכמה אמרו דאיהו<sup data-n=\"3975\">53</sup> וחיוהי וגרמוהי חד פי' כולא חד בבחי' ההתכללות ע\"כ גם בפסוק א' או הלכה אחת נכלל כל התורה כולה וד\"ל.\n<b>וזהו</b> ועם אנשים לפי שיעקב הוא בחי' תורה שהרי הוא בריח התיכון כנ\"ל וע\"כ נאמר בו כי שרית עם אלקי' ועם אנשים שהם המלאכי' וכמ\"ש בו וישר<sup data-n=\"3976\">54</sup> אל מלאך ויוכל לו כו' להיות כי המלאכי' הם באי' בבחי' התחלקו' והוא להיותו בבחי' התכללו' כנ\"ל ע\"כ השתרר עליהם וע\"כ נק' יעקב ש\"ר מטעם שנא' בו כי שרית כו'.\n<b>וזהו</b> באר חפרוה שרים שהוא יעקב שנא' בו כה<sup data-n=\"3977\">55</sup> אמר ה' ליעקב אשר פדה את אברהם כי הנה בחי' אברהם<sup data-n=\"3978\">56</sup> הוא מדת האהבה והדביקו' כמ\"ש אברהם<sup data-n=\"3979\">57</sup> אוהבי ונק' איש החסד כידוע והנה יש ב' מיני אהבה כמו שאמר זכור<sup data-n=\"3980\">58</sup> אב נמשך אחריך כמים לפי שיש התפעלו' אהבה ברשפי אש הצמאון בתפלה והוא ע\"י ההתבוננו' ואח\"כ חולפת ועוברת ואינה מתקיימת כל היום אבל אהבה שנמשכת כמים ה\"ז ממש כטבע המים<sup data-n=\"3981\">59</sup> שמגדלי' כל מיני תענוג וכל מיני צמח כו' כך ע\"י אהבה שנמשך הלב כמים היא בחי' ניצחית כל היום ומגדלת כל מיני התפעלו' עונג",[["3969","47","<b>ולישראל דוקא</b>: ראה שבת פח, ב ואילך."],["3970","48","<b>תנה הודך על השמים</b>: תהלים ח, ב."],["3971","49","<b>אוריי' מחכמה עילא' נפק'</b>: זוהר בשלח סב, ב. יתרו פה, א. (רע\"מ) משפטים קכא, א. ועוד."],["3972","50","<b>תלת קשרין אינון</b>: ראה זהר אחרי עג, א. מאמרי אדה\"א ויקרא ח\"ב ע' צט. וש\"נ."],["3973","51","<b>אחת דיבר אלקים שתים זו שמעתי</b>: תהלים סב, יב. מכות כד, א."],["3974","52","<b>וכמ\"ש על מ\"ש וכפטיש יפוצץ סלע</b>: ירמי' כג, כט. וראה סה\"מ תקס\"ה ח\"א ע' תקז. תו\"ח יתרו [הוצאת קה\"ת — תשס\"ג] רעו, א."],["3975","53","<b>דאיהו וחיוהי וגרמוהי חד</b>: ת\"ז בהקדמה (יז, א)."],["3976","54","<b>וישר אל מלאך</b>: הושע יב, ה."],["3977","55","<b>כה אמר ה' ליעקב</b>: ישעי' כט, כב. וראה מאמרי אדה\"א הנחות תקע\"ז ע' ח."],["3978","56","<b>אברהם הוא מדת האהבה</b>: ראה ספר הערכים — חב\"ד ערך אבות בתחלתו. וש\"נ. וראה תו\"א סג, א. סז, א. עה, ג. צ, א."],["3979","57","<b>אברהם אוהבי ונק' איש החסד</b>: ישעי' מא, ח. ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן לשם."],["3980","58","<b>זכור אב נמשך אחריך כמים</b>: ברכת ”גשם\"."],["3981","59","<b>המים שמגדילי' כל מיני תענוג</b>: ראה תניא פ\"א (ה, סע\"ב)."]]],[2100990171,"להתענג על ה' בבחי' המשכו' גילוי אלקו' כל היום בלימוד התורה ומצות כו' וד\"ל. ואמנם גם זאת האהבה נפדית ע\"י יעקב דוקא כמ\"ש ליעקב אשר פדה את אברהם והענין הוא כי יעקב<sup data-n=\"3982\">60</sup> הוא מדת הרחמנו' כשמעורר רחמי' רבים כמו שאו' בא\"ר אבינו<sup data-n=\"3983\">61</sup> אב הרחמן רחם עלינו ותן בלבינו בינה כו' בזה מתגלה בחי' האהבה דאברהם מן ההעלם שהרי נק' אהבה מסותרת שמסותרת בתוך החושך דנפש הבהמיו' וכשמתגלה האהבה מאיר בה בחי' חכמה שבתורה שהוא בחי' יעקב ג\"כ כמ\"ש למעלה בפי' כי שרית כו' וע\"כ נק' אז המים בשם מים חיים כי החכמה נק' חיים וכמ\"ש והחכמה<sup data-n=\"3984\">62</sup> תחי' כו' וזהו שנק' באר מים חיים דוקא כנ\"ל.\n<b>וזהו</b> בא\"ר חפרוה שרים זה יעקב שפדה את אברהם ועשה בחי' שלימו' במים בחפירת הבאר שיהיו חיי\"ם אחר החפירה וגם קודם החפירה הרי ברחמי' האהבה מתגלה מן ההעלם דעפר שעלי' כו' והיינו שאומרי' בו ואלקי יעקב בוי\"ו נוספת כי הוא מחבר הכל להיותו בחי' בריח התיכון כנ\"ל וד\"ל, ופי' כרוה נדיבי עם היינו ענין הנ\"ל בחפרוה שרים אלא שענין זה בא להוסיף עוד לומר שע\"י חפירה וכריי' זו נעשה גם מלך על עם כמאמר אין<sup data-n=\"3985\">63</sup> מלך בלא עם והיינו נדיבי עם כמ\"ש בהתנדב<sup data-n=\"3986\">64</sup> עם כו' וד\"ל.\n&lt;ערה&gt;\n<b>במחוקק</b> במשענותם. הנה בפי' חקיקה מבואר במ\"א<sup data-n=\"3987\">65</sup> ע\"פ אם בחוקותי תלכו שיש ב' חקיקות א' חקיקה מבפנים לעשות כלי בית קיבול כו' וחקיקה שנית כמו להעביר החלודה מבחוץ וליפותו והוא ענין המשכו' ב' אורו' א\"פ וא\"מ והכל ע\"י המצות שנק' כלי המחזיק ברכה כו' ע\"ש וגם בכאן אומר באר חפרוה שרים כו' לעשות בחי' כלי במחוקק בחקיקו' שע\"י התורה והמצות כמבואר שם וד\"ל.\n<b>במשענותם</b>, הנה כתיב עץ<sup data-n=\"3988\">66</sup> חיים היא למחזיקי' בה זהו בחי' תמכין דאוריית' כמו יששכר וזבולון דכתיב שמח<sup data-n=\"3989\">67</sup> זבולון בצאתך ויששכר באהלך דהקדים זבולון ליששכר אע\"פ שיששכר עוסק בתורה וזבולון אינו אלא המחזיק אותו בסחורה שעוסק ואינו אלא בחי' תמכין דאוריי' כי מאחר שזבולון מחזיקו לתורתו בזה יש יתרון מעלה לזבולון על יששכר כי הרי יששכר נקרא מקבל וזבולון נק' משפיע והטעם הוא כי מלמטה למעלה הוא היפך מלמעלה למטה ואע\"פ שמלמעלה למטה נק' יששכר פנימי' וזבולון חיצוניו' אבל מלמטה למעלה נהפוך הוא שזבולון קודם וראשון במעלה ליששכר ולכך הקדים לזבולון שמח זבולון",[["3982","60","<b>יעקב הוא מדת הרחמנו'</b>: נסמן לעיל אברהם. . החסד."],["3983","61","<b>אבינו אב הרחמן רחם עלינו</b>: ברכת ק\"ש."],["3984","62","<b>והחכמה תחי'</b>: קהלת ז, יב."],["3985","63","<b>אין מלך בלא עם</b>: בחיי וישב לח, ל. וראה הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."],["3986","64","<b>בהתנדב עם</b>: שופטים ה, ב."],["3987","65","<b>במ\"א ע\"פ אם בחוקותי תלכו</b>: ראה לקו\"ת בחוקותי. ולעיל (ח\"א) ד\"ה אם בחוקותי ובהביאורים."],["3988","66","<b>עץ חיים היא למחזיקי' בה</b>: משלי ג, יח."],["3989","67","<b>שמח זבולון בצאתך ויששכר באהלך</b>: ברכה לג, יח."]]],[2100990172,"בצאתך כמשל הרגל שמעמיד הראש שבזה הוא גבוה מן הראש וכמ\"ש במ\"א וד\"ל, ודוגמא לדבר זה ממה שמצינו בדברי רז\"ל דבע\"ת גדולים מצדיקי' גמורי' ובמקום<sup data-n=\"3990\">68</sup> שבע\"ת עומדי' צג\"מ א\"י לעמוד כו' כי הצדיקי' הם מבחי' התורה והמצות ובע\"ת הם רק כמו בחי' תמכין דאוריי' בלבד כי על ידם הרי יש קיום חזק לתורה כי ע\"י בע\"ת נתהפך חשוכא לנהורא כו' וכמ\"ש כיתרון<sup data-n=\"3991\">69</sup> האור מתוך החושך דוקא משא\"כ בצדיקי' ולכך א\"י לעמוד במחיצת בע\"ת עפ\"י הנ\"ל בזבולון דקודם ליששכר כי מלמטה למעלה בחי' תמכין דאוריי' גבוה מהתורה עצמ' אחר שעל ידם יש עלי' וחיזוק לתורה כמ\"ש למחזיקים<sup data-n=\"3992\">70</sup> בה וד\"ל.\n<b>וזהו</b> אז ישיר ישראל עלי באר כו' פי' עלי מלמטה למעלה וכל מלמטה למעלה התחתון גבוה מן העליון כנ\"ל בפי' ובמשענותם והיינו כמו ע\"י תמכין דאוריי' או ע\"י בע\"ת שבהם ועל ידם דוקא עליית בחי' הבאר שהם כנ\"י להיו' נקרא' בשם באר מים חיים וכנ\"ל וד\"ל. ובזה יובן מ\"ש ביום ההוא יצאו מים חיים מירושלים חציים אל הים הקדמוני, פי' ים הקדמונ\"י הוא ים החכמה והיינו חכמה<sup data-n=\"3993\">71</sup> שבתורה<sup data-n=\"3994\">72</sup> שנק' ים ונק' קדמוני מפני שהתורה<sup data-n=\"3995\">73</sup> קדמה לעולם כידוע וזהו כאשר יאמר משל הקדמוני כו' ומים חיים שיצאו מירושלים היינו בחי' באר מים חיים הנ\"ל שעולין מלמטה למעלה אחר בחי' הברורי' מחושך לאור וכמו בחי' בע\"ת הנ\"ל ולהיו' כי שרש חיו' הקליפ' דנוגה נפלו מעולם התוהו כידוע<sup data-n=\"3996\">74</sup> בזוהר בפי' ואלה המלכי' כו' לכך כשעולין המתבררי' לשרשם הם עולין שהוא למעלה מבחי' התיקון שהוא התורה שנק' ים הקדמוני וכענין בע\"ת שגדולי' מצדיקי' מטעם הנ\"ל דהנה ידוע<sup data-n=\"3997\">75</sup> הכלל דכל דבר שהוא נראה למטה בהשפלת המדרגה ביותר מוכרח לומר ששרשו למעלה מקודם שירד היה בעילוי המדרגה ביותר דלכך נפל לעומק ירידה כ\"כ וכמשל אבן ראש החומה שנופלת למרחק יותר כו' וגם כאן אחר שבע\"ת &lt;רעו&gt;\nנפלו תחלה בעומק רע ומוכרח ששרש זה הרע הי' קודם השבירה מעולם התוהו שגבוה הרבה כו' וע\"כ ירד מאד למטה א\"כ כששבים מן הרע הרי חוזרי' לשרשם הגבוה ביותר והיינו שאמר יצאו מים חיים מירושלים בבחי' א\"ח מלמטה למעלה ע\"י הברורי' דרפ\"ח כו' ואז יהיו הם למעלה מים הקדמוני כי הם ישפיעו לים הקדמוני דתורה",[["3990","68","<b>ובמקום שבע\"ת עומדי' צ\"ג א\"י לעמוד</b>: ראה ברכות לד, ב. לקו\"ש חי\"ז ע' 361, וע' 363."],["3991","69","<b>כיתרון האור מתוך החושך</b>: ע\"פ קהלת ב, יג."],["3992","70","<b>למחזיקים בה</b>: משלי ג, יח."],["3993","71","<b>חכמה שבתורה שנק' ים ונק' קדמוני</b>: ראה אוה\"ת חוקת שם ע' תתע."],["3994","72","<b>שבתורה. . כאשר יאמר משל הקדמוני</b>: שמו\"א כד, יג. וראה רש\"י שם. רש\"י משפטים כא, יג. רש\"י מכות י, ב ד\"ה והאלקים. תו\"א ולקו\"ת כמצויין במפתח ענינים שם מערכת משל."],["3995","73","<b>שהתורה קדמה לעולם</b>: ראה מדרש תהלים צ, ד. ב\"ר פ\"ח, ב. תנחומא וישב ד. וש\"נ. זח\"ב מט, א."],["3996","74","<b>כידוע בזוהר בפי' ואלה המלכי'</b>: וישלח לו, לא. ראה סה\"מ תקס\"ח ח\"א ע' י. ח\"ב ע' תרנב. ביאוה\"ז פינחס קיז, ג. תו\"א מקץ מא, ב. ובכ\"מ."],["3997","75","<b>ידוע הכלל</b>: ראה הנסמן בס' המפתחות (קה\"ת תשמ\"א) לספרי אדה\"ז ערך כל הגבוה כו'. סידור (עם דא\"ח) עא, ד. שג, ג. שערי אורה נח, א ואילך. סה, א ואילך. ובכ\"מ."]]],[2100990173,"וזהו אל הים הקדמוני וד\"ל. ובזה יובן ג\"כ מה שמצינו שהקדב\"ה יושב ושומע לקול הקורא בתורה וכמ\"ש<sup data-n=\"3998\">76</sup> רז\"ל ע\"פ ויקשב ה' וישמע כו' וגם אמרו שהקדב\"ה<sup data-n=\"3999\">77</sup> יושב ושונה כנגדו כו' ולכאורה יפלא מאד למה לא יקרא הקדב\"ה בתורה גם מבלתי קריאת קול בתורה בעוה\"ז וכי צריך הוא להתעוררו' שיעוררו אותו מלמטה כו' אך הענין הוא דהתורה שלומד האדם למטה הרי היא באה הכל מבחי' ברורי' דתוהו כי מלובשת בענינים גשמיים דעוה\"ז והבל פה הקורא בה ג\"כ נלקח מבחי' נוגה דעשי' כו' ואמנם כאשר יקרא הקורא באוי\"ר ופרחת לעילא אזי נק' באר מים חיים שעולין בבחי' א\"ח אל הים הקדמוני להשפיע התורה העליונה כמו שהיא למעלה וזהו שאע\"פ שהקדב\"ה<sup data-n=\"4000\">78</sup> הוא נק' קדוש וברוך דהיינו ממלא וסובב כו' מ\"מ כתיב בו ויקשב ה' וישמע לקול קורא בתורה למטה או יושב ושונה כנגדו מטעם שמבואר למעלה בפי' חציים אל הים הקדמוני לפי ששרש התורה שלמטה גבוה מתורה שלמעלה וד\"ל.\n<b>וזהו</b> אז ישיר ישראל עלי באר פי' שיצאו מים חיים מירושלים אל הים הקדמוני כנ\"ל ע\"י תשובה ומצות מעשיו' שנעשי' תחת השמש מברורי' דרפ\"ח כו' אך הנה גם בחי' עליי' זו צריך שיומשך לה כח ועוז מלמעלה כמו שאנו מבקשי' והחזירנו<sup data-n=\"4001\">79</sup> בתשובה כו' ותן<sup data-n=\"4002\">80</sup> בלבינו בינה פי' להבין הרחמנות כו' וזהו ענ\"ו לה להמשיך לה כח להיו' עולה למעלה בבחי' א\"ח כו' וד\"ל ועני' זו הוא ענין הקריאה בפסוקים בתורה כמו פסד\"ז שלפני התפלה כו' כמאמר חכמה<sup data-n=\"4003\">81</sup> בראש חכמה בסוף כו' פי' חכמה בראש הוא אתעדל\"ע שלפני אתעדל\"ת שאינה אלא לעורר אתעדל\"ת והוא התורה שלפני התפלה וחכמה בסוף היינו בחי' אתעדל\"ע שאחר אתעדל\"ת והוא כמו ענין תמכי אוריי' הנ\"ל שגורמין גילוי אור התורה אח\"כ ממש שהוא ענין במחוקק במשענותם כנ\"ל וד\"ל.",[["3998","76","<b>וכמ\"ש. . ע\"פ ויקשב ה' וישמע</b>: מלאכי ג, טז. וראה לקו\"ת חקת סג, ב."],["3999","77","<b>שהקדב\"ה יושב ושונה כנגדו</b>: תדא\"ר רפי\"ח. יל\"ש איכה רמז תתקלד."],["4000","78","<b>שהקדב\"ה הוא נק' קדוש וברוך</b>: ראה ברכות ג, א. וראה לקו\"ת מסעי צא, ג. אוה\"ת סידור ע' קפב-ד."],["4001","79","<b>והחזירנו בתשובה</b>: ברכת תפלת שמו\"ע."],["4002","80","<b>ותן בלבינו בינה</b>: ברכת ק\"ש."],["4003","81","<b>חכמה בראש חכמה בסוף</b>: זח\"א כו, א."]]],[2100990174,"<h3>להבין שרשי הדברים</h3>\n<b>בעזר\"ה</b>\n&lt;רעז&gt;\n\nלהבין<sup data-n=\"4004\">1</sup> שרשי הדברים הנ\"ל. הנה בע\"ח<sup data-n=\"4005\">2</sup> בשער מ\"ן ומ\"ד מבואר ששרש מ\"ן דנוק' מבחי' המוחי' שבה הוא נמשך כמו שמ\"ד דדכורא מבחי' המוחי' שבו נמשך והיינו מבחי' חכמה דנוק' נמשך המ\"ן והנה ידוע דמ\"נ דנוק' הוא מבחי' המלכים דתוהו שנשאר עדיין להתברר וכמ\"ש שם באריכות, וא\"כ הרי יש בחכמה דנוק' בחי' הכת\"ר דתוהו ג\"כ אחר שהחכמה<sup data-n=\"4006\">3</sup> מאי\"ן<sup data-n=\"4007\">4</sup> תמצא דהיינו מבחי' הכת\"ר כידוע והכת\"ר<sup data-n=\"4008\">5</sup> לעולם הוא בחי' ממוצע בין אור א\"ס לנאצלי' כידוע הרי יש הארת אור א\"ס בכתר זה דתוהו והארה זו היא גבוה גם מהארת חכמה ובינה דתיקון שנק' ים הקדמוני כי ע\"ס דא\"ח דתוהו גבוהי' מע\"ס דא\"י דתיקון ובירור ז' המלכים בשם ב\"ן דנוק' עולין הם בבחי' א\"ח וזהו שרש ענין בחי' באר מים חיים הנ\"ל שנעשה ע\"י המצות מפני שנעשי' בבחי' ברורי' דתוהו בעוה\"ז וע\"ז נא' ביום ההוא יצאו מים חיים מירושלים חציים אל הים הקדמוני.\n<b>ולהבין</b> ביאור הדברים הנה איתא בס' הבהיר דיש ע\"ס מלמטה למעלה וע\"ס מלמעלה למטה ומלמעלה למטה ידענו ומלמטה למעלה לא ידענו וע' פרד\"ס<sup data-n=\"4009\">6</sup> שער מלמטה למעלה כי מלמטה למעלה הוא בחי' ע\"ס דנוק' בבחי' מ\"נ שבה שהם בבחי' א\"ח והכלל ידוע שבע\"ס דא\"ח הכתר עולה ראשון ובע\"ס דא\"י הכתר יורד ראשון ואח\"כ החכמה עד שהמל' אחרון והנה המצות שרשם מבחי' כתר שהרי נק' תר\"ך עמודי אור והתורה שהיא פי' המצות הוא בחי' החכמה ואמנם מאחר שהתורה והמצו' כולם המה בבחי' עשי' גשמית הרי המה בבחי' כתר וחכמה דתוהו שמתבררי' בבי\"ע ע\"י שם ב\"ן וע\"כ מצד התורה והמצות שמלובשי' בעשי' נק' הנפש באר מים חיים מפני שעולי' בבחי' א\"ח ראשונה והם משפיעי' לבחי' כתר וחכמה דתיקון דהיינו פי' מעיין גנים כנ\"ל. כי הנה ענין מעיין גנים הנ\"ל היינו בחי' בינה דאצי' שנק' ים הקדמוני שיורדת לבי\"ע ע\"י ההתלבשו' תחלה בבחי' מלכו' דאצי' שנעשית עתיק לבריא' כידוע ואח\"כ בבחי' בינה שבמל' דאצי' מאיר בחי' עתיק דבריא' והיינו מה שהנשמו' נהנין מזיו כו' בג\"ע העליון כי אימא<sup data-n=\"4010\">7</sup> מקננא בכורסייא וכן עד\"ז הולך ויורד עוד מבריא' ליצירה ומיציר' לעשי' בג\"ע התחתון דהיינו בחי'",[["4004","1","<b>להבין שרשי הדברים</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (עג, ב).\nנדפס בשינויים בלקו\"ת חוקת סג, ב. ובתוס' הגהות באוה\"ת חקת ע' תתעב ואילך.\nנוסח אחר (הנחת המהרי\"ל) נדפס לקמן ע' תקסה בהתחלה: עלי באר."],["4005","2","<b>בע\"ח שער מ\"ן ומ\"ד</b>: שער לח."],["4006","3","<b>שהחכמה מאין תמצא</b>: איוב כח, יב."],["4007","4","<b>מאין. . דהיינו מבחי' הכתר כידוע</b>: ראה תו\"א ויצא כב, ד. וישלח כו, ג. הוספות יתרו קט, א. תו\"ח בראשית מא, ד. ובכ\"מ."],["4008","5","<b>והכתר. . ממוצע</b>: ע\"ח שער דרושי אבי\"ע (שמ\"ב) פ\"א. שער מוחין דצלם (שכ\"ג) פ\"ח. וראה לקו\"ת בחוקותי מו, ג. שלח מט, ג."],["4009","6","<b>פרדס שער מלמטה למעלה</b>: שט\"ו, פ\"ד. וראה לקו\"ת שה\"ש כ, ב ואילך."],["4010","7","<b>כי אימא מקננא בכורסייא</b>: ת\"ז ת\"ו (כג, א)."]]],[2100990175,"מל'<sup data-n=\"4011\">8</sup> דבריאה נעשה בחי' עתיק ליצי' וכו' עד שבג\"ע דעשי' הוא בבחי' בינה שבמל' דיצי' שמאיר בה מבחי' עתיק דיצי' ושם הנשמו' נהנין ג\"כ מזיו כו' וב' ג\"ע הללו נק' גנים והמעיין המשקה אותם ממקורם האמיתי שהוא בחי' בינה דאצי' שנק' ים הקדמוני היינו בחי' מל' דאצי' להיותה בחי' ממוצע בין האצי' לבריא' כידוע דבחי' הכתר הוא בחי' ממוצע בכל מקום והרי המל' נעשית בחי' כתר לנבראים וא\"כ על ידה דוקא נשפע האור ממקורו הראשון והוא בחי' בינה דאצי' עצמה שהוא המקור למעיין גנים זה ואמנם היא אינה יורדת למטה אלא ע\"י אמצעות בחי' מל' דאצי' שנק' כתר דבריא' הממוצע והמחבר כנ\"ל וד\"ל.\n<b>והנה</b> השבח הזה במעיין גנים על כנ\"י נאמר משום דשבוחי הוא דקא משבח לכנ\"י שנקראת מעיין גנים ואח\"כ משבח אותה בשבח אחר שהיא ג\"כ &lt;רעח&gt;\nבאר מים חיים כו' וא\"כ זהו בהכרח בשני מדרגות שא\"א להיות השבח הכל במדריגה א', ומה שמשבח בתחלה שהיא מעיין גנים היינו מלמעלה למטה והוא בבחי' א\"י דתיקון דהיינו איך שהאור אלקי נשפע בע\"ס כח\"ב בתחלה ומבינה דאצי' יורד האור עד בחי' בינה דעשי' שבג\"ע התחתון כנ\"ל ואח\"כ משבח אותה מלמטה למעלה במה שיש בה ע\"ס דא\"ח בבחי' מ\"ן דילה והוא במה שנקרא' באר מים חיים.\n<b>והענין</b> הוא כי המ\"ן דנוק' לא נשלם בו הבירור והתיקון מהשבירה עדיין ואפי' בחי' המל' עצמה דהיינו בנין קומתה כבר נשלם בה הבירור והתיקון אך בחי' כלי ההולדה שלה בלבד שהוא בחי' מ\"ן לא נשלם בה הבירור וכמ\"ש בע\"ח ובחטא אדה\"ר נפל גם בחי' מ\"ן דאימא כו' וצריכי' עכ\"פ בירור בבחי' העלא' דא\"ח כי ז' המלכי' עולי' רק בבחי' א\"ח כנ\"ל וידוע דהנשמו' נולדי' מיחוד דזו\"נ ממ\"ד ומ\"ן וע\"כ יש בירור ותיקון במ\"נ בנשמות בג' מדרגו' דבי\"ע בדרך כלל מזמן החורבן דבית שני עד ביאת משיח ב\"ב דהיינו כמו בימי<sup data-n=\"4012\">9</sup> התנאי' שאחר החורבן הי' הבירור והתיקון מבחי' מ\"נ דנוק' נשמות שהם בבחי' מוחי' חב\"ד דבריא' ובזמן האמוראי' הי' בחי' בירור ותיקון בנשמו' דמ\"נ דבחי' חג\"ת דיצירה ואח\"כ בימי הגאונים עד דורו' האחרוני' הכל נחשב בבחי' עקבות משיחא שהן בחי' נה\"י דעשי' והיינו מ\"ש רז\"ל עד<sup data-n=\"4013\">10</sup> שיכלו כל הנשמו' שבגוף פי' נשמו' שצריכי' בירור והיינו אותם שמלובשי' עדיין באוצר<sup data-n=\"4014\">11</sup> א' ששמו גוף והוא בחי' מ\"נ דנוק' ולפי שהן באין בשיעור קומה ראש ורגל כי המ\"נ נמשך מן המוח שבראש דוקא והולך ומתפשט עד בחי' נצח והוד דכליות ומשם עוד בבחי' ירכין כו' ע\"כ אמרו בזוהר<sup data-n=\"4015\">12</sup> דמי שבקי בשיעור קו המדה יוכל לשער שיעור גלותא דאתמשך כו' והוא עד כלות שיעור",[["4011","8","<b>מל' דבריאה נעשה בחי' עתיק ליצירה</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"ב."],["4012","9","<b>בימי התנאי' שאחר החורבן. . מבחי' מ\"נ</b>: ראה אוה\"ת חקת שם שמבאר זה באריכות."],["4013","10","<b>עד שיכלו כל הנשמו' שבגוף</b>: יבמות סג, ב. ובפרש\"י שם. ע\"ז ה, א ובפרש\"י ותוס' שם. רש\"י ותוס' הרא\"ש נדה יג, ב. זהר חדש [מדרש הנעלם] בראשית פ\"ד י, ב. לקו\"ש ח\"ה ע' 434 בהערה."],["4014","11","<b>באוצר. . ששמו גוף</b>: ראה גם ספר הערכים — חב\"ד בערכו (ח\"ב ע' שצג-ד)."],["4015","12","<b>בזוהר. . גלותא דאתמשך</b>: ראה זהר שמות רנח, א."]]],[2100990176,"ירכין דנוק' והיינו שאמר עד<sup data-n=\"4016\">13</sup> דמטו רגלין ברגלין וכמ\"ש ועמדו<sup data-n=\"4017\">14</sup> רגליו ביום ההוא על הר הזיתים כו' פי' עד כלות שיעור הברורי' גם מבחי' נשמו' דמ\"נ שהן בבחי' עקבות משיחא כנ\"ל ואמנם עיקר הבירור ע\"י המ\"ד שמברר מ\"ן אלא שהמ\"ן עצמו גם הוא בא בבחי' בירור תחלה אחר שיורד מן המוח דחכמה דנוקבא והמוח כבר נברר כי בנין הנוק' בכל קומתה כבר נברר בבחי' התיקון דאצי' כנ\"ל רק כלי ההולדה שלה שהוא המ\"ן לא נברר עדיין וה\"ז כמשל כלי ההולדה באשה גשמית שהוא דבר נבדל ממהותה העצמי כי אין הזרע שלה רק כח המוליד בדומה לעצמותה ולא שהיא מבחי' עצמותה ממש וכך יובן הדוגמא והמשל למעלה וד\"ל.\n<b>והנה</b> מבואר למעלה שבכל מקום בחי' הכתר הוא המחבר המאציל עם הנאצלי' וגם כאן בבחי' בירור דרפ\"ח ניצוצו' דתוהו במ\"נ דנוק' בבחי' א\"ח אחר שהחכמה דנוק' הוא שרש המ\"ן הזה א\"כ גם כאן בחי' הכתר דתוהו מאיר בחכמה זו כי החכמה מאין תמצא בכל מקום וכנ\"ל ובחי' כתר זה דתוהו הוא בחי' ממוצע כמו שכתר דתיקון הוא ממוצע במקומו רק שבבחי' התיקון בא בבחי' פרצופים ובבחי' התוהו בא בבחי' נקודו' זה תחת זה כו' ואמנם הנה בזאת יתרון מעלת בחי' התוהו על התיקון במה שהוא בא &lt;רעט&gt;\nבבחי' נקודו' שאין בזה ענין הגבלה וצמצום אור בבחי' קו המדה כלל אלא הם אורו' פשוטים וע\"כ מבלתי בחי' התיקון הי' אור התוהו חוזר לקדמותו מטעם זה כידוע אך גם לאחר שבאו בבחי' התיקון מ\"מ מצד שרשם כשהם עולים הם אורו' פשוטים וחוזרים למקורם בבלתי הגבלה בכלי כלל וע\"כ אורם ושפעם רב מאד וע\"כ כאשר עולי' בבחי' א\"ח לאחר הבירור דמ\"ן דנוק' כנ\"ל אזי עולין עד רום המעלו' דהיינו בעצמו' אור המאצי' שלפני בחי' התיקון הרבה ונעשה למעלה גם מבחי' כתר דתיקון.\n<b>וזהו</b> ביום ההוא יצאו מים חיים מירושלים בבחי' א\"ח חציים אל הים הקדמוני כו' להשפיע בחי' כתר וחכמ' דתיקון והמה משפיעי' לבינה דאצי' שנק' מעיין גנים כנ\"ל והמשל בזה יובן מעיגול גדול הסובב כמה עיגולים שבתוכו ובוקע אור ישר את כולם מראש העיגול עד אמצעיתו ביושר ומאמצעיתו עד למטה בתחתית העיגול מצד השני יש אור בוקע ועולה והנה לגבי ראש העליון שבעיגול נקרא ירידה למי שעומד שם והוא ירידת א\"י ולמי שעומד בתחתית העיגול מצד השני הרי נק' ירידת אור זה כשמגיע למטה בשם עליה כי העיגול מצדדיו הכל בהשוואה אחת הוא והכל נק' עליון בין בצד מזרחו או בצד מערבו כי אין בעיגול מעלה ומטה ממש שהרי למי שעומד בתחתיתו נק' ראש העליון מטה כידוע וא\"כ מובן ממילא דמי שעומד באמצעית הקו ההולך מעליונו של עיגול רחוק הוא בהשווא' א' לב' הצדדי' אבל מי שעומד למטה מאמצעית העיגול הרבה קרוב הוא לבא יותר לתחתיתו של עיגול שמצד השני וקרוב הוא יותר להגיע לשם מלבא ולהגיע לעליונו של עיגול",[["4016","13","<b>עד דמטו רגלין ברגלין</b>: ראה זח\"ב רנח, א. ובמק\"מ שם. ובהנסמן עוד במאמרי אדה\"א שמות ח\"ב ע' תקד."],["4017","14","<b>ועמדו רגליו ביום ההוא על הר הזיתים</b>: זכרי' יד, ד."]]],[2100990177,"וא\"כ העומד סמוך ממש לתחתונו של עיגול בודאי עומד במעלתו גבוה ממי שעומד רחוק מעליונו של עיגול בקו ההולך ממנו אע\"פ שהוא רחוק קצת כי זה כבר הגיע למעלה העליונה שבעגולת העיגול עצמו הסובב כולם וזה רחוק מעליונו של עיגול זה ועומד למטה בעיגולי' שבתוכו שהם למטה הרבה מעגולת העיגול הגדול כו' והנמשל מובן בבעלי תשובה וצדיקים דבע\"ת<sup data-n=\"4018\">15</sup> גדולים מצדיקי' גמורים מזה הטעם דהנה הנמשל הוא בבחי' הקו ההולך מעליונו של עיגול היינו הקו דתיקון בבחי' ע\"ס דא\"י שמתחיל מבחי' כתר דתיקון עד בחי' אמצעי' העיגול שהוא מסתיים שם והוא בחי' מל' דאצי' ומשם ולמטה עומדי' היכלות החיצוני' שהוא בין הכלים והמקיפי' אחוריהם אל המקיף כו' כמ\"ש בע\"ח עד תחתית העיגול מלמטה הוא קרוב אליהם יותר והבע\"ת כשהוא בעומק רע שנק' כתר דקליפה קרוב הוא יותר להגיע בתשובתו לבחי' סובב כ\"ע האמיתי כמ\"ש ומתחת<sup data-n=\"4019\">16</sup> זרועו' עולם יותר גם מבע\"ת שלא הגיע עדיין בחטאיו לעומק הרע כ\"כ כי רחוק הוא יותר ממנו להגיע לתחתית העיגול הגדול עד\"מ וע\"כ קרוב ונקל יותר לרשע גמור לעשות תשובה לפי שקרוב יותר לבחי' סובב שמתחתית הכל כו' ועכ\"פ מצדיקי' גמורים שהם מבחי' התיקון דהיינו קו שכבר הולך ביושר ונתרחק מעליונו של עיגול עד\"מ הרי בודאי הבע\"ת גבוהי' מהם במעלה שהרי הבע\"ת עומדים במעלת עגולת העיגול הגדול עצמו עד\"מ כנ\"ל וד\"ל.\n<b>ועפ\"י</b> כל זה יובן גם כאן דמטעם זה בנשמות העולין בבחי' בירור דא\"ח דתוהו &lt;רפ&gt;\nמשם ב\"ן דמלובשת בג' קליפו' דבי\"ע ודאי מובן שנשמות העולין באחרונה דוקא דהיינו מבחי' עקבות משיחא דהיינו עד בחי' נוגה דעשי' שמה עיקר ותכלית המעלה יותר מכולם כי קרובי' ומגיעי' לבחי' תחתית העיגול הגדול והיינו עד דמטו רגלין ברגלין הנ\"ל והיינו מ\"ש ביום ההוא כו' אל הים הקדמוני שהוא בחי' כתר וחכמה דקו התיקון כי עגולת זה העיגול מצד עצמו הרי עליון הוא מהכל וד\"ל וזהו מ\"ש בס' הבהיר דע\"ס מלמעלה למטה ידענו לפי שבא מהכתר באור שפע קו עכ\"פ אבל ע\"ס מלמטה למעלה לא ידענו משום דלית מחשבה תפיס' בי' להיותו למעלה מבחי' קו כי הרי הוא בבחי' עצמיו' הכתר הכללי מקור כל המקיפי' שאין בו בחי' מעלה ומטה כלל כמשל הנ\"ל וד\"ל.\n<b>וזהו</b> אז ישיר ישראל עלי באר ענו לה כו'. פי' ישראל<sup data-n=\"4020\">17</sup> עלה במחשבה היינו בבחי' התיקון דוקא והיינו במ\"ד דדכורא ואמנם בירידתה למטה ירידה צורך עלי' הוא כנ\"ל דהיינו להיו' באר מים חיים כנ\"ל והוא לברר ברורי' דתוהו שיעלו מלמטה למעלה כנ\"ל וזהו עלי באר כו' ועלי' זו למעלה מים הקדמוני דתיקון הוא מטעם המבואר למעלה וד\"ל.\n<b>אך</b> הנה ע\"י מה מגעת הנשמה למעלה זו דא\"ח דהיינו בחי' באר מים חיים להיו' מקור למעיין גנים דא\"י הנ\"ל היינו ע\"י המצות מעשיו' דתוהו כי הנה גופי",[["4018","15","<b>דבע\"ת גדולים מצדיקי'</b>: ראה ברכות לד, ב. לקו\"ש כרך יד ע' 361 וע' 363."],["4019","16","<b>ומתחת זרועו' עולם</b>: ברכה לג, כז."],["4020","17","<b>ישראל עלה במחשבה</b>: ב\"ר בתחילתו."]]],[2100990178,"מעשה המצות הרי המה נעשים מבחי' הנוגה דוקא כמו קלף עור בהמה דתפילין וצמר דציצית כנ\"ל והגם שהשרש של המצות<sup data-n=\"4021\">18</sup> הוא בכתר כנ\"ל שנק' תר\"ך עמודי אור כו' זהו בבחי' הכתר דתוהו דוקא אחר שהמצו' המה בדברים גשמיים דבחי' נוגה דתוהו כו' ולטעם זה יובן מה שנחלקו המצות לג' מדרגות נגד בירור ג' קליפו' נוגה דבי\"ע הא' הכונה במחשבה במוח ולב והן המצו'<sup data-n=\"4022\">20</sup> שצריכי' כונה כמו ק\"ש ומצות אוי\"ר שתלוי' בכונה במוח דוקא וכוונות שאר כל המצות וכונה זו במוח היינו בבחי' המוחי' דנוק' שמשם נמשך המ\"נ והרי זה בירור ראשון והב' מצו'<sup data-n=\"4023\">19</sup> התלויו' בדיבור כמו ת\"ת וק\"ש וכיוצא וכן אוי\"ר שבלב בלא שכל כו' הכל מבחי' חג\"ת דיצי' והג' המצות התלויות במעשה דוקא והוא בחי' נה\"י דעשי' וכולם מלובשי' בבחי' נוגה ונמצא כל המצו' המה בג' מדרגו' בי\"ע שהן מחשבה דו\"מ והמה נעשי' בדברים שהמה מבחי' נוגה דבי\"ע וכולם עולי' בבחי' א\"ח בעשות המצוה עד בחי' כתר דתוהו שהוא שרש המצות הנעשות כאן בעוה\"ז וד\"ל.\n<b>והנה</b> מטעם זה יובן שרש ענין הנ\"ל איך שמן התורה והמצות נעשי' בחי' א\"פ ובחי' א\"מ וכמ\"ש אז<sup data-n=\"4024\">21</sup> יבקע כשחר אורך והלך לפניך צדקך עד וכבוד ה' יאספך דהנה בצדקה שהיא כללות כל המצות יש ג\"כ ב' מדרגו' הנ\"ל א' מ\"ש פרוס<sup data-n=\"4025\">22</sup> לרעב לחמך והוא בחי' א\"פ והב' כי תראה ערום וכסיתו שהוא בחי' א\"מ ועל שניהם אומר אח\"כ שאז יבקע כשחר אורך להיו' ג\"כ השכר לנפש בב' מדרגו' הללו בבחי' א\"פ וא\"מ והוא מ\"ש והלך<sup data-n=\"4026\">23</sup> לפניך בבחי' א\"פ ואח\"כ כבוד ה' יאספך בבחי' א\"מ וכך הוא בכללו' המצות כי הנה המצו' נק' לבושי' לנפש כמ\"ש והיתה<sup data-n=\"4027\">24</sup> נפש אדני צרורה בצרור החיים כו' ומהתורה נעשה מזון &lt;רפא&gt;\nלנפש והיינו ענין מ\"ש אז<sup data-n=\"4028\">25</sup> תתענג על ה' שהוא כמ\"ש שרפים<sup data-n=\"4029\">26</sup> עומדים ממעל לו וא' בזוהר<sup data-n=\"4030\">27</sup> ממעל לשכינתא לפי שנכנס בו אור האלקי בבחי' א\"פ והנפש מקיף על אותו האור והיינו כמו בחי' מזון לנפש שנכנס בתוך הגוף וכך כתיב ותורתך<sup data-n=\"4031\">28</sup> בתוך מעי כו' משא\"כ האופני' שרחוקי' יותר נא' בהם רעש כו' וד\"ל אבל המצו' בכלל נק' לבושי' בחי' מקיפי' להקיף לנפש מלמעלה וז\"ש כבוד ה' יאספך כו' ושני מדרגו' אלו פנימי ומקיפי'",[["4021","18","<b>המצות. . תר\"ך עמודי אור</b>: ראה תורת העולה להרמ\"א ח\"ג פל\"ח (לב, א). של\"ה יתרו שו, א. מאו\"א מערכת תר\"ך סנ\"ו."],["4022","20","<b>מצו' התלויו' בדבור כמו ת\"ת</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב הי\"ב. תניא רפל\"ז. ספמ\"ט. תו\"א נח ח, ג. וראה מאמרי אדה\"א דברים ח\"א ע' רמ ובהנסמן שם."],["4023","19","<b>המצות שצריכי' כוונה כמו ק\"ש</b>: עירובין צה, סע\"ב."],["4024","21","<b>אז יבקע כשחר</b>: ישעי' נח, ח. ראה זהר אמור קד, א שיעקב אמר פסוק זה. וראה תו\"ח ויצא קעט, ג. קפה, ב. קפט, ג."],["4025","22","<b>פרוס לרעב לחמך. . כי תראה ערום וכסיתו</b>: שם נח, ז."],["4026","23","<b>והלך לפניך. . כבוד ה' יאספך</b>: ישעי' נח, ח."],["4027","24","<b>והיתה נפש אדני צרורה</b>: שמואל-א כה, כט."],["4028","25","<b>אז תתענג על ה'</b>: ישעי' נח, יד."],["4029","26","<b>שרפים עומדים ממעל לו</b>: ישעי' ו, ב."],["4030","27","<b>וא' בזוהר ממעל לשכינתא</b>: ראה לקו\"ת ברכה צט, ד. סה\"מ תקס\"ח ע' רטז וע' שלא. סה\"מ תרל\"ג ח\"ב ע' תקא. ובכ\"מ."],["4031","28","<b>ותורתך בתוך מעי</b>: תהלים מ, ט."]]],[2100990179,"באי' לנפש בג\"ע ע\"י מעיין גנים הנ\"ל שהוא בחי' מל' דאצי' שנעשה עתיק לבריא' והיינו אז יבקע כשחר אורך כו' אבל סיבת זאת ההארה מלמעלה למטה באה דוקא ע\"י מעשה המצות ולימוד התורה שהן בחי' כתר וחכמה דתוהו וזהו באר מים חיים ענין נביעו דמים חיים הללו בתוך הבאר הוא נביעת חכמה שבתורה שמלובשת בעניני מעשה המצו' בגשמיו' ולכך נק' מים חיים כי היא מבררת רפ\"ח ניצוצי' דתוהו כו' וכנ\"ל כי כל התורה היא רק פירוש וביאור המצות והבאר הוא הכתר עצמו וכמו החכמה שמלבשת לרצון בלבד וכמ\"ש במ\"א ע\"פ עוטה אור כשלמה כו' וד\"ל וזהו הטעם שנעשה מתורה ומצות דתוהו בחי' א\"פ וא\"מ לנפש בג\"ע ממעיין גנים כמ\"ש ביום ההוא יצאו מים חיים מירושלים שהוא בחי' מל' כשמבררת ברורי' דתוהו כנ\"ל חציים אל הים הקדמוני דתיקון כנ\"ל ומטעם המבואר למעלה באריכות וד\"ל.\n<b>וזהו</b> פי' המשך הפסוק דשיר השירי' מעיין<sup data-n=\"4032\">29</sup> גנים באר מים חיים ונוזלי' מן לבנון, פי' בתחלה משבח אותה בבחי' התיקון דא\"י והוא מה שנק' מעיין גנים כנ\"ל ולפי שעיקר התהוו' האור בג\"ע הוא מבחי' בינה דאצי' כנ\"ל והמל' הוא המעיין המשקה הגן כנ\"ל, ואח\"כ משבח אותה בבחי' הברורים דתוהו שע\"י תורה ומצות שנק' בזה באר מים חיים שנובע מלמטה למעלה עד שחציים אל הים הקדמוני דתיקון מטעם הנ\"ל, ונוזלים מן לבנון, פי' אע\"פ שברורי' דא\"ח הנ\"ל מגיעי' עד למעלה מעלה בעצמו' המאציל למעלה מבחי' התיקון מטעם הנ\"ל מ\"מ צריך בתחלה להיות לזה בחי' גילוי הארה מבחי' לבנון דהיינו בחי' התיקון דמ\"ד דדכורא כדי לעורר העלא' המ\"ן דנוקבא כי א\"א לה להיו' התעוררות להעלות מ\"ן מצד עצמה בלתי אם לא שיהא נמשך כח האור לעוררה לזה מלמעלה וכמ\"ש אני ישנה<sup data-n=\"4033\">30</sup> שזהו בגלותא ולבי ער קול דודי דופק כו' וכמ\"ש<sup data-n=\"4034\">31</sup> במ\"א שיש אתעדל\"ע שאחר אתעדל\"ת ויש אתעדל\"ע שלפני אתעדל\"ת שאינה אלא כדי לעורר אתעדל\"ת וההפרש ביניהם הוא שהאתעדל\"ע שאחר אתעדל\"ת היא באה בבחי' שפע אור ממש והוא בחי' מ\"ד שנשפע בשעת היחוד וכיוצא משא\"כ בחי' אתעדל\"ע שלפני אתעדל\"ת אינה באה בבחי' השפעה עצמיית אלא רק בחי' הארה בעלמא בלבד אחר שהוא רק לעורר את המקבל כו' וכמ\"ש במ\"א באריכות וד\"ל.\n<b>וזהו</b> ונוזלים מן לבנון פי' בחי' באר מים חיים הנ\"ל שיוכלו לעורר ולהעלות כמ\"ש עלי באר זהו בא מבחי' לבנון דתיקון ומה שאמר לשון נוזלים מלשון הזלה לפי שבאה זאת ההתעוררו' לעורר למטה מבחי' י\"ג מדה\"ר שנק' י\"ג תיקוני דיקנא דא\"א והמה נמשכי' ובאי' מבחי' מזלו' דא\"א כידוע דמזל<sup data-n=\"4035\">32</sup> ונוצר הוא מזל הח' ומזל",[["4032","29","<b>מעיין גנים באר מים חיים</b>: שה\"ש ד, טו."],["4033","30","<b>אני ישנה. . בגלותא</b>: שה\"ש ה, ב. זהר אמור צה, א."],["4034","31","<b>וכמ\"ש במ\"א שיש אתעדל\"ע שאחר אתעלד\"ת</b>: ראה לקו\"ת שה\"ש לח, ג."],["4035","32","<b>דמזל ונוצר הוא מזל הח'</b>: ראה זהר (אד\"ז) האזינו רפט, ב. ע\"ח שער הכללים פ\"ה."]]],[2100990180,"ונקה הוא מזל הי\"ג כו' ומהם נמשך הארת הכרוזין שב\"ק<sup data-n=\"4036\">33</sup> מכרזת בכל יום &lt;רפב&gt;\nשובו בנים שובבים כו' וכמ\"ש במ\"א וזהו שאמר ונוזלים מן לבנון וד\"ל.\n<b>וזהו</b> ג\"כ פי' אז ישיר ישראל כו' עלי באר ענו לה פי' עלי באר ע\"י ישראל הוא שהוא בחי' התיקון כי המ\"ד מברר מ\"ן כנ\"ל אך מ\"מ צריך שיעוררו בתחלה שיהי' להמל' כח להעלות מ\"ן ולבא לידי בחי' בירור אח\"כ ע\"כ אמר עוד ענו לה פי' ענו לה בחי' מ\"ד משרש בחי' התיקון לעורר בה העלא' מ\"ן כנ\"ל בפי' ונוזלים מן לבנון והיינו ג\"כ שרש הברכות של המצות כולן שהן ברורי' דתוהו וכדי שיוכלו לעלו' אומרי' בתחלת עשיתן הברכה בכונה לעורר העלא' מ\"ן והיינו בא\"י מן ההעלם לגילוי כידוע והיינו ענו לה וד\"ל.\n<b>באר</b> חפרוה שרים כרוה נדיבי עם כו'. פי' החפירה בבאר הוא לעשות אח\"כ בחי' כלי בית קיבול במלכו' דאצי' וכמ\"ש בע\"ח ובפרע\"ח בפי' מקדש ה' כוננו ידיך שהן בחי' ידים עליונים דבינה כו' וכמ\"ש ויבן<sup data-n=\"4037\">34</sup> ה' אלקי' את הצלע דאו\"א תקינו לה כו' והיינו חפרוה שרים שהן בחי' או\"א אך לא מבחי' או\"א עצמם אלא מבחי' חג\"ת נה\"י שבהם והיינו כרוה נדיבי עם שהן בחי' נה\"י כו' וביאור ענין החפירה הזאת היינו ע\"י התפלה לברר הטוב מן הרע שהוא ע\"י ביטול רצון דוקא כמ\"ש למעלה והוא להסיר העפר החומרי מבחי' נוגה שמחשיך על ניצוץ האלקי ואז ממילא נגלה ניצוץ הטוב כי יש בחי' אהבה מסותרת בכל ניצוץ מישראל אלא שהוא נעלם ומוסתר בעפר חומריו' נפש דנוגה כו' ומעורב הטוב הזה ברע דנוגה וע\"י אור חו\"ב דוקא נחקק בחי' הכלי בניצוץ האלקי והוא ע\"י שחופר תחלה ומסיר העפר דנוגה הסובב עליה ואח\"כ נעשית בחי' כלי כו' והוא כמ\"ש במחוקק כו' וכמ\"ש בסמוך ואמנם כללו' ענין חפירה זו הוא כדי שתהא נק' בשם באר מים חיים הנ\"ל משא\"כ אם לא חפרוה שרים הנ\"ל לא היתה נק' באר מים חיים דתורה ומצוה כי יש בור שאין בו מים חיים הנ\"ל אלא הוא ריקן מכל וכמ\"ש והבור ר\"ק מים אין בו וכשמים דאוריי' אין בו ממילא נחשים ועקרבים יש בו דהיינו ג' קליפו' נחש שרף ועקרב שיונקי' שם כו' וזה הי' כל עיקר ענין חפירת בארו' דאבות כדי לעשו' בחי' כנ\"י שתהא נקראת דוקא באר מים חיים כנ\"ל וד\"ל.\n<b>והנה</b> הבחיר<sup data-n=\"4038\">35</sup> שבאבות הוא יעקב כי בו נא' כי<sup data-n=\"4039\">36</sup> שרית עם אלקים ועם אנשים כו' וע\"כ נא' ביעקב אשר<sup data-n=\"4040\">37</sup> פדה את אברהם דהיינו שהוא עיקר המשלים בנין החפירה הנ\"ל דחפרוה שרים והיינו שפודה את אברהם ויצחק להיו' שלימו' בחפירת בארו' שלהם כו' והטעם הוא מבואר למעלה בפי' כי שרית עם אלקי'",[["4036","33","<b>שב\"ק מכרזת בכל יום</b>: ראה זהר נשא קכו, א. מאמרי אדה\"א ויקרא ח\"א ע' ט."],["4037","34","<b>ויבן ה' אלקי' את הצלע</b>: בראשית ב, כב."],["4038","35","<b>הבחיר שבאבות הוא יעקב</b>: שער הפסוקים להאריז\"ל תולדות כז, כה. וראה ג\"כ ב\"ר רפע\"ו. זח\"א קיט, ב. קמז, ב."],["4039","36","<b>כי שרית עם אלקים</b>: וישלח לב, כט."],["4040","37","<b>אשר פדה את אברהם</b>: ישעי' כט, כב."]]],[2100990181,"דהיינו שם ב\"ן המצמצם כו' ועם אנשים דהנה באברהם נא' והנה ג'<sup data-n=\"4041\">38</sup> אנשים נצבים עליו ופי' עליו היינו בבחי' מקיף וא\"כ הי' גדולי' המלאכי' הללו ממנו אחר שהיו נצבים עליו וביעקב נאמר וישר<sup data-n=\"4042\">39</sup> אל מלאך ויוכל לו כו' בכה ויתחנן לו כו' שהמלאך הי' בטל ונכנע לו בתכלית והענין הוא כי שרש האבו'<sup data-n=\"4043\">40</sup> בכלל הן בחי' חג\"ת דז\"א שהוא בחי' המדו' דאצי' בכלל והמדות הללו דאבות הם קדמו לתורה שניתנה אח\"כ כי האבות<sup data-n=\"4044\">41</sup> היו בחי' מרכבה למדו' דאצי' עד שלא ניתנה התורה כידוע ואמנם בחי' יעקב הי' בו יתרון מעלה בכלל במה שהי' מאיר בו בחי' חכמה שבתורה כידוע המאמר &lt;רפג&gt;\nדמשה<sup data-n=\"4045\">42</sup> מלגיו יעקב מלבר וא\"כ כמו שמשה הי' שרש להמשכת חכמה שבתורה מלגיו בבחי' הפנימי' להיותו מבחי' אור אבא כך יעקב<sup data-n=\"4046\">43</sup> הי' בו ג\"כ מבחי' חיצוניו' המשכה זו והוא חיצוניו' התורה כי להיותו בחי' בריח התיכון המבריח מן הקצה לקצה הגיע לקצה היותר עליון שהוא בחי' הכתר דתורה כו'.\n<b>והנה</b> ידוע שבחי' ההתחלקו' במדו' חג\"ת היינו שיש לכל מדה ומדה מקום וכלי בפ\"ע נבדל מזולתה והן בחי' האבו' שהיו מרכבה למדו' דאצי' שהן באין בהתחלקו' בכלים נבדלים דוקא והיינו שג' אנשים מפני שהיו בבחי' כלים נבדלים היו נצבים על אברהם כו' אבל שרש חכמה שבתורה הגם שהתורה באה ג\"כ במדו' כמו כשר פסול טמא טהור אבל מ\"מ יש בחי' חכמה במדו' הללו שהיא באה בבחי' ההתכללות שכוללת כל המדו' יחד כמו עד\"מ הידוע דהגם שיש באדם שכל פרטי בכל דיבור הרי יש בכללו' כל דבריו שכל כללי הכוללם יחד וא\"כ גם בפרט א' נמצא מכללות הכל כו' כך יש במדו' דאצי' חכמה כללית שכוללם הכל והוא אור התורה שנא' בה אחת דבר אלקי' שתים כו' וכמ\"ש כפטיש<sup data-n=\"4047\">44</sup> יפוצץ סלע שדיבור א' מתחלק כו' לפי שהיא בחי' ההתכללות מריבוי כללות החיות כולם כנ\"ל ע\"כ גם בדיבור פרטי נמצא מהכלל כולו משא\"כ במדות שאין מאיר בהם בחי' ההתכללו' דתורה כמו במדו' דאבו' יש לכל מדה התחלקות בפ\"ע ויש לה כלי נבדל בהכרח כו' ודוגמא לדבר זה ממה שמבואר במ\"א בביאור ענין כי אלף שנה כיום אתמול שאלף השנה נמשכי' בבת א' ואח\"כ מתחלק לאלף חלקי' כו' ע\"ש כך אור חכמה שבתורה נמשכת בריבוי גדול בבת א' דהיינו בבחי' ההתכללו' הנ\"ל וע\"כ כל דיבור שמתחלק אח\"כ יש בו מכללו' הכל כו' והעיקר הוא להיות כי התורה באה בבחי' התכללו' ובבת א' כנ\"ל ע\"כ לא הי' צריך יעקב למלאך שהוא בחי' כלי נבדל כנ\"ל ואברהם הי' צריך לג' מלאכי' שהם ג' כלים והוא להיותו בא בבחי' התחלקו' כנ\"ל אבל יעקב הי' שרשו למעלה מבחי' התחלקו' כנ\"ל וא\"כ גם כלי א' לא הי' צריך וזהו וישר אל",[["4041","38","<b>והנה ג' אנשים נצבים עליו</b>: וירא יח, ב."],["4042","39","<b>וישר אל מלאך ויוכל לו</b>: הושע יב, ה."],["4043","40","<b>האבו'. . חג\"ת</b>: ראה מאו\"א מערכת אבות סכ\"ז. פרדס (שער הכינויים) שכ\"ב, פ\"ד. ע\"ח (שער אנ\"ך) שי\"ט, פ\"ג. סידור שער חגה\"ס רנז, ג."],["4044","41","<b>האבות היו בחי' מרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה סידור שער נפ\"א צב, ב."],["4045","42","<b>דמשה מלגיו יעקב מלבר</b>: תקו\"ז תי\"ג (כט, א)."],["4046","43","<b>יעקב. . מבריח מן הקצה</b>: ראה זהר תרומה קעה, ב."],["4047","44","<b>כפטיש יפוצץ סלע</b>: ירמי' כג, כט."]]],[2100990182,"מלאך ויוכל לו וע\"כ בכה המלאך שיהא לו לבחי' כלי ויתחנן לו ולא רצה יעקב לקבלו מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> כי שרית עם אלקי' שהוא שם ב\"ן המצמצם ועושה התחלקו' לג' אנשי' בכלל שהן מט\"ט וס\"נ כו' וע\"כ כשיעקב השתרר עליו מצד שהי' בחי' גופא דאוריי' כי יעקב מלבר כנ\"ל לכך נא' בו אשר פדה את אברהם דהיינו לעשו' בחי' שלימו' בחפירת הבאר הנ\"ל והוא ע\"י מדתו של יעקב שהוא בחי' הרחמנו' כמ\"ש למעלה וד\"ל.\n<b>כרוה</b> נדיבי עם במחוקק במשענותם. פי' נדיבי עם, עם הוא בחי' מל' דאצי' כמאמר אין<sup data-n=\"4048\">45</sup> מלך בלא עם והוא מדת המלכו' שמלכותו<sup data-n=\"4049\">46</sup> בכל משלה ונדיבי עם היינו כמ\"ש בת<sup data-n=\"4050\">47</sup> נדיב בתו של אברהם שנק' נדיב כי מבואר למעלה דהבונים לבחי' מל' הוא אברהם ויצחק שהן חג\"ת ונה\"י וזהו כמ\"ש והוכן<sup data-n=\"4051\">48</sup> בחסד כסא דהיינו בהארה והשפעה מלבר שבאה מחסד זה דאברהם הוכן בנין המל' שנק' כסא והוא כמשל הנדיבו' באדם למטה שהוא ענף מעצמות החסד בלבד, וזהו בהתנד\"ב ע\"ם שמתנד\"ב להיו' בחי' עם שהוא אין מלך בלא עם כנ\"ל וכן ענין המתנדבי' בעם כו' וד\"ל.\n&lt;רפד&gt;\n<b>במחוקק</b> במשענותם. הנה מחוקק<sup data-n=\"4052\">49</sup> זה משה דכתיב בי' כי<sup data-n=\"4053\">50</sup> שם חלקת מחוקק ספון וכידוע והוא בחי' יסוד אבא שנק' מחוקק דהיינו הדבר שבו חוקקי' ולא גוף החקיקה עצמה והענין הוא מבואר במ\"א<sup data-n=\"4054\">51</sup> ע\"פ אם בחוקותי תלכו שיש ב' חקיקו' א' להעביר החלודה מבחוץ והב' לעשו' חקיקת בית קיבול מבפנים כו' וביאור שרש הדברים הוא לפי שמשה הי' מבחי' כח<sup data-n=\"4055\">52</sup> מה דחכמה והוא בחי' ביטול וכמ\"ש ונחנו<sup data-n=\"4056\">53</sup> מה וע\"כ אנו מוצאי' שמשה<sup data-n=\"4057\">54</sup> קיבל התורה הרבה פרשיות בסקירה אחת ובבת א' ואח\"כ חלק אותה לחלקי' ולמדה לבנ\"י פרקי פרקי וכידוע לפי שבחי' הביטול הוא כלי המחזיק ברכה בלי שיעור וגבול כי ע\"י בחי' הביטול בתכלית השפלות נעשה עי\"ז בחי' בית קיבול בעומק ביותר כמשל חקיקת כלי כשחקוק בו בעומק עד שמגיע בעומק התהום יכול להתקבל בו עד אין שיעור כו' כך בחי' ביטול דמשה הי' עמוק כ\"כ עד שהי' עניו<sup data-n=\"4058\">55</sup> מכל האדם אשר ע\"פ האדמה לכך הי' מתקבל בו אור התורה כולה בבת א' ואח\"כ הי' צריך לחלקה לחלקי' כדי ללמדה לבנ\"י לפי שיעורם כו'",[["4048","45","<b>אין מלך בלא עם</b>: ס' החיים פ' גאולה פ\"ה. בחיי וישב לח, ל. עמה\"מ שער שעשועי המלך רפ\"א. לעיל ע' תקנב."],["4049","46","<b>שמלכותו בכל משלה</b>: ראה תהלים קג, יט."],["4050","47","<b>בת נדיב בתו של אברהם</b>: שה\"ש ז, ב. סוכה מט, ב."],["4051","48","<b>והוכן בחסד כסא</b>: ישעי' טז, ה."],["4052","49","<b>מחוקק זה משה</b>: ראה ב\"ב טו, א. ביאוה\"ז בשלח מד, סע\"ד. סה\"מ תקס\"ד ע' קעו. ועוד."],["4053","50","<b>כי שם חלקת מחוקק</b>: ברכה לג, כא."],["4054","51","<b>במ\"א ע\"פ אם בחוקותי תלכו</b>: ראה לקו\"ת בחוקותי מז, ג ואילך."],["4055","52","<b>כח מה דחכמה</b>: זח\"ג לד, א."],["4056","53","<b>ונחנו מה</b>: ראה בשלח טז, ז. ח. וראה מאמרי אדה\"א בראשית ע' כב."],["4057","54","<b>שמשה קיבל התורה</b>: אבות רפ\"א."],["4058","55","<b>עניו מכל האדם אשר ע\"פ האדמה</b>: בהעלותך יב, ג."]]],[2100990183,"וכיוצא בזה מצינו בהאריז\"ל שפ\"א הי' ישן והשיג בחלומו רזין דאוריי' הרבה כ\"כ עד שהיו צריכין לכתוב ס' שנה כמ\"ש בשבחי<sup data-n=\"4059\">56</sup> האריז\"ל והיינו שהשיג בפ\"א ובסקירה א' מה שהי' צריך אח\"כ לכתוב ס' שנה וכל זה מפני בחי' הביטול דהיינו בחי' מ\"ה שאור א\"ס שורה שם מטעם שהוא בחי' הביטול כידוע וזהו שנק' משה מחוקק לפי שהי' חקוקי' בו כל אותיו' שבתורה בבת א' ואח\"כ חקקה לחלקי' כנ\"ל ובדרך כלל בב' חקיקו' מבפנים ומבחוץ והוא בחי' שלימו' כלי בית קיבול כשנעשה בחי' באר מים חיים במחוקק זה גם בבחי' הפנימי' כי משה מלגיו ויעקב מלבר כנ\"ל וד\"ל.\n<b>במשענותם</b> הם תמכי<sup data-n=\"4060\">57</sup> אוריי' כו'. פי' כמו ביששכר וזבולון דכתיב שמח<sup data-n=\"4061\">58</sup> זבולון בצאתך ויששכר באהליך דהנה הסנהדרין היו משבט יששכר<sup data-n=\"4062\">59</sup> יודעי בינה כו' והם נקראי'<sup data-n=\"4063\">60</sup> עיני העדה בבחי' חכמה שבמל' דאצי' וזבולון<sup data-n=\"4064\">61</sup> לחוף ימים ישכון לסחורה ולהאכיל ולהלביש ליששכר והגם שמלמעלה למטה הסנהדרין בחי' חב\"ד והעוסקי' במו\"מ הם שבט זבולון בחי' נה\"י אבל מאחר שנה\"י מעמיד את הראש הרי בהכרח לומר שמלמטה למעלה בחי' נה\"י גבוהי' מחב\"ד והענין הוא לפי שבבחי' א\"ח הכתר דתוהו גבוה מבחי' התיקון כולו כנ\"ל בפי' חציים אל הים הקדמוני, וע\"כ החיות של הסנהררין הוא מבחי' נה\"י דזבולון כמו שיחי' המאכל את הנפש כו' וכמ\"כ המאכל של זבולון גורם חיות התורה דסנהדרין כו' וד\"ל.\n&lt;רפה&gt;\n<b>ובזה</b> יובן מ\"ש בזבולון עמים<sup data-n=\"4065\">62</sup> הר יקראו לפי שזהו צ\"ל בחלקו של זבולון דוקא והענין הוא דעמים הם רפ\"ח כו' המתבררי' מבחי' השבירה דתוהו עד שנפל בעקבו' משיחא והוא בחי' נה\"י דזבולון כו' ושם דוקא עמים הר יקראו כלומר שעולים בתכלית הבירור היותר נעלה והוא כמ\"ש מי<sup data-n=\"4066\">63</sup> יעלה בהר ה' ומי יקום במקום קדשו נקי כפים ובר לבב דתמוהי קא מתמה מי הוא אשר יכול לעלו' כ\"כ במדרגה הגבוה בהר ה' אלא רק נקי כפים הוא בחי' נה\"י שבמעשה והוא להיותו במדרגה היותר תחתונה ונעוץ תחלתן בסופן כנ\"ל בפי' חציים אל הים הקדמוני כו' וע\"כ בזבולון דוקא נא' עמים הר יקראו שהעמים יתבררו שם ויעלו להר ה' שהוא עלי' ובירור היותר נעלה מכל מה שקדם להיות גם בזמן בהמ\"ק וזה יהי' לעתיד דוקא בימות המשיח כידוע וזהו ויהי<sup data-n=\"4067\">64</sup> נועם ה' לעתיד דוקא כו' לפי שמעשה ידינו דוקא כוננה עלינו ומעשה ידינו כוננהו וד\"ל וזהו במשענותם תמכי אוריי' דוקא.",[["4059","56","<b>בשבחי האריז\"ל</b>: ראה פע\"ח (שער קשעהמ\"ט) שט\"ז, פ\"א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסד ובהנסמן בהמ\"מ לשם. שה\"א צג, א ובהערה 9. תו\"ח שמות קג, א. של, א."],["4060","57","<b>תמכי אוריי'</b>: ראה זהר בהקדמה ח, א."],["4061","58","<b>שמח זבולון בצאתך</b>: ברכה לג, יח. ראה ב\"ר פצ\"ט, ט. ורש\"י ברכה שם."],["4062","59","<b>יששכר יודעי בינה</b>: דברי הימים-א יב, לב."],["4063","60","<b>נקראי' עיני העדה</b>: ראה שלח טו, כד. ויקרא ד, יג. ע\"ח שער (ח) דרושי הנקודות פ\"א."],["4064","61","<b>וזבולון לחוף ימים</b>: ויחי מט, יג."],["4065","62","<b>עמים הר יקראו</b>: ברכה לג, יט."],["4066","63","<b>מי יעלה בהר ה'. . נקי כפים</b>: תהלים כד, ג-ד."],["4067","64","<b>ויהי נועם ה'</b>: תהלים צ, יז."]]],[2100990184,"<h3>נוסח שני: עלי באר ענו לה</h3>\n<b>[ביאור אז ישיר]</b>\n<b>עלי</b><sup data-n=\"4068\">1</sup> באר<sup data-n=\"4069\">2</sup> ענו לה, איתא בע\"ח בשער מ\"ן ומ\"ד שהיחוד דזו\"נ הוא מבחי' המוחין דזו\"נ שאף המ\"ן הוא ממוחין דנוק' תתאה והוא מבחי' הרפ\"ח ניצוצין דתהו ע\"ש בעיון, הנה בתהו הי' נקודות זת\"ז לכן נשברו ונפלו בס\"ג דבי\"ע והאצילות תקנו פרצופין התכללות כנ\"ל.\n<b>והנה</b> לכך עפ\"י ההשתלשלות מלמעלה למטה אזי כתר הראש ומל' סוף, אבל בהעלאה מלמטה למעלה הוא להיפוך כו', מפני שבמ\"ן דנוק' הוא בחי' מוחין דתהו, שהחכמה<sup data-n=\"4070\">3</sup> מאין תמצא, כתר מחבר מאציל ונאצלים עצמות א\"ס ולכך מלמטה למעלה המ\"ן הוא הוא הכתר דתהו הוא משפיע מים חיים חכמה דתהו לים הקדמוני בינה דתיקון דאצילות, מפני שהחכמה דתהו הוא למעלה מחכמה דתיקון, וזהו ענין המצות כתר דתהו והתורה שלמטה בעשי' הוא חכמה דתהו הם מים חיים ים הקדמוני, והיינו מעין גנים מל'<sup data-n=\"4071\">4</sup> דאצי' עתיק לבריאה וג\"ע העליון בינה דבריאה בהתלבשות בינה דאצי' מקורו בי' ג\"ע התחתון בינה דעשי' אכן מקור הג\"ע הוא בינה דאצי' אינה יורדת להתלבש זולת ע\"י אמצעות המל' כתר דבריאה ממוצע ומחבר כנ\"ל.\n<b>והרי</b> הוא המעין מקור לגן המשקה אותו וכן מל' דיצירה עתיק כו', וזהו מלמעלה למטה, שבוחי הוא דקא משבח לכנ\"י מל' דאצי', הוא מעין גנים והדר משבח אותה בשבח אחר באר מים חיים בבחי' המ\"ן דילה מכתר חכמה דתהו שבה מתבררים בירורים דבי\"ע בימי התנאים<sup data-n=\"4072\">5</sup> נשמות דבריאה ואח\"כ האמוראים דיצירה ועתה עקבא דמשיחא ירדו בעשי' לברר עד דמטו רגלין כו', ומי שבקי בקו המדה עד כלות שיעור משך תכלית הבירורים יכול לידע עת ביאת מלכא משיחא, כי מל' מברר ג\"כ רק תכלית גמר של הבירור הוא ע\"י מ\"ד דמ\"ה כנודע, גם זה ידוע שמתברר רק המ\"ן דילה הזרע בחי' כח המוליד בדומה וכל השיעור קומה העצמיות כבר נתברר כמו באדם זרע ההשפעה ולא עצמותו, וזהו באר מים חיים היוצאים מירושלים חצים אל הים הקדמוני כי זה הכלל כל שבבי\"ע מרפ\"ח נצוצין דתהו כל התו\"מ דבי\"ע מלבד האצי' שכבר הוברר, ולכן עתה בעקביים הוא התגלות הכת\"ר דתהו למטה יותר כמו ששמע ממורו משל האופן עיגול כו' ולכן הקרוב לקצה האחר עליון באופן אחר, וזהו כתר סובב ומקיף הכל,",[["4068","1","<b>עלי באר ענו לה</b>: נעתק מכת\"י 1213 סג, ב (והוא כנראה הנחת המהרי\"ל). הנחת כ\"ק אדה\"א נדפס לעיל ע' תקנה."],["4069","2","<b>עלי באר ענו לה</b>: חוקת כא, יז."],["4070","3","<b>שהחכמה מאין תמצא</b>: איוב כח, יא."],["4071","4","<b>מל' דאצי' עתיק לבריאה</b>: ראה ע\"ח (שער העקודים) ש\"ו, פ\"ב."],["4072","5","<b>התנאים נשמות דבריאה</b>: ראה אוה\"ת חקת שם שמבאר זה באריכות."]]],[2100990185,"אלו שבסוף מגיעים וקרובים יותר לקצה השני עצמיות הכתר, ולכך באר מים חיים וד\"ל. ונוזלין מן לבנון בתיקון מ\"ד לעורר מ\"ן וזהו ולבי ער ע\"י ענו לה מ\"ד מישראל והחילוק שבין מ\"ד הקודם לאח\"כ שזה הארה בעלמא רק לעורר, וזה עצמיות כנודע.\n<b>חפרוה</b> שרים ביעקב נאמר וישר<sup data-n=\"4073\">6</sup> אל מלאך כו' באברהם נאמר ג'<sup data-n=\"4074\">7</sup> אנשים נצבים עליו, שאף ג' כלים פרטים היו עליו והסבה בצד היותו ממדות שלא עפ\"י התורה אבל יעקב<sup data-n=\"4075\">8</sup> מלבר משה מלגאו שהוא חיצוניות התורה כולל רבוי החיות ושפע ואינו מצטרך אפי' לכלי א' ולכך המלאך בכה שיהי' לו כלי ולא רצה ויוכל לו וד\"ל. כי<sup data-n=\"4076\">9</sup> שרית עם אלקים כו'.\n<b>נדיבי</b> עם המתנדבים<sup data-n=\"4077\">10</sup> בעם להיות אין<sup data-n=\"4078\">11</sup> מלך בלא עם נדיבי חג\"ת שרים או\"א, במחוקק<sup data-n=\"4079\">12</sup> משה יסוד אבא<sup data-n=\"4080\">13</sup>, חקיקה מבפנים ומבחוץ העברת חלודה כח מ\"ה תפס במערה את כל התורה כולה כמשל<sup data-n=\"4081\">14</sup> שבחי האר\"י ס\"פ ואתחנן כו'.\n<b>במשענותם</b> זבולון נה\"י מעמיד משענת לחג\"ת וחב\"ד תמכי אורייתא כתר דתהו חצים אל הים הקדמוני זבולון<sup data-n=\"4082\">15</sup> עמים הר יקראו מקור הבירורין מנה\"י אף שנאמר מי<sup data-n=\"4083\">16</sup> יעלה בהר ה' נקי כפים כו' אבל בזבולון אף עמים הר יקראו.",[["4073","6","<b>וישר אל מלאך</b>: הושע יב, ה."],["4074","7","<b>ג' אנשים נצבים עליו</b>: ויצא יח, ב."],["4075","8","<b>יעקב מלבר משה מלגאו</b>: תקו\"ז תי\"ג (כט, א)."],["4076","9","<b>כי שרית עם אלקים</b>: וישלח לב, כט."],["4077","10","<b>המתנדבים בעם</b>: שופטים ה, ט."],["4078","11","<b>אין מלך בלא עם</b>: בחיי וישב לח, ל. וראה הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."],["4079","12","<b>במחוקק משה</b>: ראה ב\"ב טו, א. ביאוה\"ז בשלח מד, סע\"ד. סה\"מ תקס\"ד ע' קעג, ועוד."],["4080","13","<b>משה יסוד אבא</b>: ראה לקו\"ש ח\"ו ע' 244."],["4081","14","<b>במשל שבחי האריז\"ל ס\"פ ואתחנן</b>: ראה פע\"ח (שער קשעהמ\"ט) שט\"ז, פ\"א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רסד ובהנסמן בהמ\"מ שם."],["4082","15","<b>זבולון עמים הר יקראו</b>: ברכה לג, יט."],["4083","16","<b>מי יעלה בהר ה' נקי כפים</b>: תהלים כד, ג-ד."]]],[2100990186,"<h3>ברוך שאמר והי' העולם</h3>\n<b></b><b>ביאור סדר התפילה מב\"ש עפ\"י כהאריז\"ל</b>\n<b>ברוך</b><sup data-n=\"4084\">1</sup> שאמר והי' העולם<sup data-n=\"4085\">2</sup> רישא דלא אתידע, ברוך הוא גולגלתא דא\"א כו'. הנה במילת ברוך יש ב' פרושים עפ\"י דרך הקבלה כמו שהוא למעלה בפרצופים עליונים, ועפ\"י עבודת ה' שלמטה, והיינו כי ברוך<sup data-n=\"4086\">3</sup> הוא המשכה בכ\"מ, שעפ\"י עבודת ה' הוא בחי' המשכות גילוי אא\"ס ב\"ה שיומשך מההעלם אל הגילוי בנפשו האלקית וע\"ז מתפללי' ברוך אתה שבכל סידור התפילה שהכוונה הוא שיתגלה בחי' גילוי אלקות בנפשו וכמ\"ש ברוך<sup data-n=\"4087\">4</sup> ה' מן העולם ועד העולם מעלמא דאתכסייא לעלמא דאתגלי' כו', ועפ\"י דרך הקבלה הכוונה במילת ברוך הוא בחי' המשכה מעצמות המאציל ב\"ה המרומם לבדו ומתנשא מערך י\"ס הנאצלים בבחי' י\"ס הנאצלים שיתהווה ויאצל ממנו ית' בחי' חכמה דאצי' או בינה דאצילות כו', והנה עפ\"י דרך הקבלה ברוך שאמר כו' הוא המשכה מעצמיות המאציל ב\"ה המרומם לבדו שיאצל ממנו בחי' רדל\"א שהוא בחי' מל' דא\"ק והיא נעשה רישא לאצי' אך לא אתידע כלל כי לית מח' ת\"ב כלל ואינה נתפסת בשום מהות עדיין כלל ולכך אומר שאמר והי' העולם פי' שאמר הוא מל' דא\"ק דלית מח' תפיסא בה לכנותה בשם מהות ודבר מה בלל כ\"א שאמר סתם מי שאמר רק זאת ידוע שהי' העולם האצי' מבחי' האמירה דמל' דא\"ק שאף דלא אתידע מהותה ואיכותה בעצמ' אעפי\"כ נרגש מציאותה מצד הפעולה שאמר והי' העולם דאצילות.",[["4084","1","<b>ברוך שאמר והי' העולם</b>: הנחת ר' משה בן אדה\"ז. נמצא בכת\"י 237 (גוכי\"ק הר\"מ). ביכל זה מכיל 44 דפים, כולם קרועים מצדדיהם. וחסר בתחלתו שני דפים (מברוך שאמר עד ברוך מרחם על הבריות). אודות גוכתי\"ק הר\"מ (237), כותב באגרות קדש דכ\"ק אדמו\"ר מוהרש\"ב נ\"ע (קה\"ת תשמ\"ב) ח\"א ע' כג: את הכ\"ק קבלתי ומאד נהנתי מהם ובפרט מהביאורים בכוונות התפלה ע\"ד הקבלה והחסידות והם יקרי הערך מאד ובלתי ספק שהם כי\"ק הר\"מ זצ\"ל\", (וראה ג\"כ שם ע' כ).\nמאמר זה נמצא ג\"כ בכת\"י 946 (קנח, א-רכ, א). קטע מההתחלה (מד\"ה ברוך שאמר עד אמצע ד\"ה ברוך אומר ועושה) נמצא ג\"כ בכת\"י מעתיק 286 (כ, א-ב). 2444.\nרובו נדפס כאן מכת\"י מעתיק הנ\"ל (946), והוגה מגוכתי\"ק (מלבד קטעים אחדים שנדפסו מגוכתי\"ק והושלמו מכת\"י המעתיק).\nהנחת כ\"ק אדה\"א נדפס בסידור עם דא\"ח לט, ג—מד, א — מגוכתי\"ק 1025 בכותרת: בעזר\"ה ליל שבת פ' מטות מסעי. ובדף עח, א לפני קטע ברוך כו' האל אב הרחמן רשום: בעזר\"ה. (ואולי נאמר ד\"ה ברוך שאמר בשני חלקים).\nבדרושי הצ\"צ על סידור נמצא מאמר הסידור (עד קטע: ברוך עושה בראשית) בתוס' הגהות.\nמאמר זה בהרחב הביאור נדפס בפירוש המילות לאדה\"א פ' צד—קכא.\nוראה ג\"כ אוה\"ת ר\"ה הוספות (כרך ד) ע' א'תתקכו-תתקכח (פיה\"מ מברוך שאמר עד ברוך שמו). סה\"מ אתהלך לאזניא ע' קנ.\nהנחת המהריל נדפס לקמן ע' תקפב.\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז סידור ע' שמב."],["4085","2","<b>ברוך שאמר והי' העולם</b>: נוסח תפלת פסוד\"ז."],["4086","3","<b>ברוך הוא המשכה</b>: ראה גם ביאוה\"ז עקב קיט, ד. סידור שער החנוכה רפ, ג. תו\"א מקץ לז, ג."],["4087","4","<b>ברוך ה' מן העולם ועד העולם. . לעלמא דאתגלי'</b>: תהלים קו, מח. דברי הימים-א טז, לו. לקו\"ת פ' ראה יט, ב. תו\"ח ויצא קסח, ג. תו\"ח שמות [קה\"ת — תשס\"ג] לג, א. קסב, א. וראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב."]]],[2100990187,"<b>ברוך</b> הוא, הוא בחי' גולגלתא דא\"א שלמטה מרדל\"א ולכן אומרים ברוך הוא שנתפס בשם מהות לדבר מה לקרותו בשם הוא אך בלשון נסתר, כי ג' מדריגות נק' בחינת אתה חכמה וחסד דז\"א ומל', מל'<sup data-n=\"4088\">5</sup> נק' אתה שהיא עלמא דאתגלייא לגבי ז\"א שהוא העלם לגבה וחסד דז\"א נק' אתה שהוא בחי' התגלות לגבי בינה דאצילות שנק' עלמא דאתכסייא וחכמ' נק' אתה שלגבי הכ\"ע אפי' החכ' הוא בחי' התגלות וז\"ש אתה<sup data-n=\"4089\">6</sup> כהן וגו' אבל כ\"ע נק' הוא כי ישת<sup data-n=\"4090\">7</sup> חושך סתרו שהכתר<sup data-n=\"4091\">8</sup> הוא הממוצע בין המאציל לנאצלים שפנימיות הכתר הוא מבחי' תחתונה שבמאציל וחיצוניות הכתר הוא שרש וראש לנאצלים והוא המחבר את המאציל עם נאצלים וזהו הכוונה במילת ברוך שהוא בחי' ההמשכה מעצמיות המאציל שיאצל בחי' הכתר דאצי' כי עצמותו פשוט בתכלית הפשיטות ומרומם לבדו עד שאפי' אור<sup data-n=\"4092\">9</sup> צח ומצוחצח דכ\"ע אתחשך קמי' כו' כנודע ולכן ממשיכין שישרה אא\"ס ב\"ה בגולגלתא דא\"א והיינו בחי' האצי' שלו מן עצמיות המאציל ב\"ה וע\"כ העבודה הוא ההמשכה מבחי' הכ\"ע שמתגלה למטה בעולמות דבי\"ע ובכללם הוא נפשו האלקית שיתגלה בנפשו ג\"כ וזהו ברוך הוא שיומשך בחי' הוא הכ\"ע ויתגלה למטה וכן ב\"ש וכו', אך באמת כולא חדא מילתא היא דכאשר יומשך ויתרבה השפע דעצמות אא\"ס ב\"ה בתוס' מרובה בבחי' הכ\"ע, שזהו כפי חכמי הקבלה כו' במילת ברוך הוא אזי ממילא תתפשט ותתגלה השפע דא\"א למטה בבי\"ע וכמשל חביות יין כשנתמלא הכלי על כל גדותיה אזי ממילא יהי' נשפך היין מן החביות למטה על הארץ או על הכלי שמעמידים תחתיה אבל כשהחביות עצמה איננה מליאה ממילא לא יתגלה היין בשפיכה למטה שהחביות מסתרת ומכסה עליה כו', וככה ממש למעלה דכאשר מתוסף השפע דעצמות אא\"ס בהכ\"ע ממילא תתגלה ממנו למטה ג\"כ ובזה יתכנו ב' הפירושים כא' וכנ\"ל ועד\"ז סובב והולך כל המאמ' כו' וד\"ל.\n<b>ברוך</b> אומר ועושה (מו\"ס דא\"א) ברוך גוזר ומקיים (אבא דאצילות). פי' כי אבא דאצילות נק' בשם גוזר מפני שהחכ' דאבא דאצי' היא מלאה דינין והיינו כי אורייתא<sup data-n=\"4093\">10</sup> מחכ' נפקת וכולם<sup data-n=\"4094\">11</sup> בחכ' עשית שכל התהוות הנאצלי' שמחכ' ולמטה הוא מחכ'<sup data-n=\"4095\">12</sup> ראשית האצילות וכל התהוות האצילות היא עפ' חכ' של התורה שנמשכה מאבא דאצילות ולכן היא מלאה דינין אף שהוא שרש הקו הימין דחח\"ן דאצי' אכן שאינה סובלת ההיפוך והמנגד לה דהיינו שמה שיוסבל עפ\"י חיוב השכל והחכמ' לזה היא הנשפעת טוב וחיים וחסד כו' אבל מי שהוא נגד החכמ' וההיפוך לה עד שאינה יכולה לסובלו שאין חיוב השכל והחכ' מחייב להשפיע לו טוב וחסד כ\"א",[["4088","5","<b>מל' נק' אתה שהיא עלמא דאתגלייא</b>: ראה פרדס שער (כג) ערכי הכינויים מערכת דוד."],["4089","6","<b>אתה כהן</b>: תהלים קי, ד."],["4090","7","<b>ישת חושך סתרו</b>: תהלים יח, יב."],["4091","8","<b>שהכתר הוא הממוצע</b>: ע\"ח שער דרושי אבי\"ע (שמ\"ב) פ\"א. וראה לקו\"ת בחוקותי מו, ג. שלח מט, ג."],["4092","9","<b>אור צח ומצוחצח</b>: תקו\"ז ת\"ע קרוב לסופו (קלה, ב)."],["4093","10","<b>אורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. (רע\"מ) משפטים קכא, א."],["4094","11","<b>וכולם בחכ' עשית</b>: תהלים קד, כד."],["4095","12","<b>מחכ' ראשית האצילות</b>: ראה דרך מצותיך קג, א."]]],[2100990188,"אדרבה לענשו בעונשין המפורשות בתורה מצד שהוא ההיפוך והמנגד לה שעבר עבירה פלונית המוזהר בחכמות התו' אשר לא תעשינה כו' משא\"כ למעלה מהחכ' דאצילות הוא מקור הטוב והחסד להיות מאריך<sup data-n=\"4096\">13</sup> אף לרשעים ולהיות נושא<sup data-n=\"4097\">14</sup> עון ועובר על פשע לסבול אף מה שנגד החכ' כו' ולכך נק' החכ' דאצי' בשם גוזר ומקיים שהיא גזירת הדין של התו' לקיים כל דבר של הנהגות העולם בדין ומשפט התו' שלזכאי מחייב הדין של החכ' להשפיע לו טוב וחסד ולחייב גזירת עונש המפורש בתורה הכל לפי החטא כן הוא העונש כפי שנגמר הדין בחיוב השכל והחכ' של התורה (וכמ\"ש<sup data-n=\"4098\">15</sup> במ\"א על מאמרז\"ל שאלו לחכמ' נפש החוטאת במה תתכפר אמרה תמות כו').\n<b>והנה</b> כללות עולם<sup data-n=\"4099\">16</sup> האצילות נק' בתיקונים בשם עשי' שאדם דאצילות נק' אדם דעשי' ועולם הנקודים בשם עולם היצי' ועולם העקודים בשם בריאה כו' ע\"ש והטעם לזה בהיות ידוע שבז\"א דאצילות האורות מצומצמים ומלובשים בתוך הכלים דאצי' שהאורות הם נמשכים מבחי' עצמיות אא\"ס ב\"ה והן ג\"כ בבחי' א\"ס ב\"ה בלי גבול ותכלה כלל, אך אם האורות דאצי' היו פשוטי' כמו שהם מופשטים מגדר התלבשות הכלים כלל היו מתפשטים בבחי' א\"ס ממש בלי גבול ותכלה כלל ולכן לא הי' אפשר להתהוות מהם עולמות בי\"ע הנפרדים ובע\"ג ותכלית ומה גם בתחילת האצי' כשנאצלה בחי' אור החסד דז\"א דאצילות הי' האור מתפשט בלי גבול ותכלה כלל בבחי' א\"ס ממש איך הי' באפשר להיות נאצל בחי' אור הגבורה ההפכי ומנגד לה שכיון שהתחיל להאציל אור החסד הי' נמשך ומתפשט בבחי' א\"ס ממש בלי תכלה כלל ועד שלא יהי' הפסק להתמשכות אור החסד לא הי' אפשר להאציל ולמשוך מהות אור הגבורה ההפכי ומנגד לה וכן למטה בבי\"ע כאשר הי' נמשך אור החסד דאצי' במאמר הראשון דיהי<sup data-n=\"4100\">17</sup> אור ביום ראשון דבראשית הי' נמשך והולך ומתפשט באורך משך הזמן כולו דשית<sup data-n=\"4101\">18</sup> אלפי שני' דקיים עלמא ואיך הי' יתכן להיות באמצע המשך הזמן זה פעולת מדת הגבו' לפעול חורבן בהמ\"ק בעו\"ה וכה\"ג כ\"א הי' רק המשכות טוב וחסד ממהות אור החסד שנמשך בתחילת יום ראשון דבראשית בכל משך הזמן דשיתא אלפי שנין כו' אי לזאת נתצמצמו האורות דז\"א דאצי' בבחי' הכלים דז\"א שהכלים הם מבחי' הגבו' שמגבילי' את האורות שלא יתפשטו בבחי' א\"ס והיינו כיון שנמשך אור החסד דז\"א ונתלבשו בתוך כלי החסד",[["4096","13","<b>מאריך אף לרשעים</b>: תשא לד, ו. סנהדרין קיא, סע\"א. יומא סט, ב. תו\"א קג, ד. קה, ב. תו\"ח בא (קה\"ת — תשס\"ג)."],["4097","14","<b>נושא עון ועובר על פשע</b>: לשון הפסוק מיכה ז, יח."],["4098","15","<b>וכמ\"ש במ\"א על מאמרז\"ל שאלו לחכ' נפש החוטאת</b>: ראה ילקוט תהלים רמז תשב. ועד\"ז בירושלמי מכות פ\"ב ה\"ז וראה לקו\"ת דרושים לשבת שובה סז, ד. לקו\"ש ח\"ד ע' 1358. אגרות קודש לכ\"ק אדמו\"ר זי\"ע ח\"ה ע' ג. ”רשימות\" חוברת קסד ע' 9 ואילך."],["4099","16","<b>עולם האצילות נק'. . אדם דעשי'</b>: ראה ג\"כ תו\"א בראשית ג, א. לקו\"ת צו ח, ד. בהר מג, ד. מסעי צה, א. שה\"ש מט, ג. תו\"ח חיי שרה קכד, א. שערי תשובה קח, ג. אוה\"ת בלק ע' תתקמח."],["4100","17","<b>דיהי אור</b>: בראשית א, ג."],["4101","18","<b>דשית אלפי שני דקיים עלמא</b>: ראה ר\"ה לא, א."]]],[2100990189,"והכלי הוא מבחי' הגבול היא מצמצמת ומגבלת אותו שלא יתפשט בבחי' א\"ס ממש כ\"א יהי' שיעור וגבול להתפשטותו וכיון שמסתיי' תפסק הגבול והשיעור של התפשטותו אז מתחיל להאציל ולהתפשט בחי' אור הגבור' וגם הוא מתלבש בכלי הגבורה המגבלת אותו שיהי' שיעור וגבול להתפשטותו וכיון שנפסק המשכות אור הגבורה אז מתחיל להתמשך אור הת\"ת והנצח כו' ועד\"ז כולן. אך כיון שהכלים הן מבחי הגבול שהם ממדת הגבורה והצמצום לצמצם ולהגביל האורות אזי מגבילי' ומסתירים יותר מדאי עד שלא יומשכו ויתפשטו האורות למטה כלל לזאת האורות הנמשכו' מבחי' החסדי' העליוני' מבחי' אור א\"ס נמתקי' הגבורות דהכלים עד שמתמזגים במזג השוה להיותם מתפשטים בשיעור וגבול הממוזג במזג השוה.\n<b>אכן</b> העושה השיעורי והגבולי' ההם בהם שכמה בשיעור יתפשטו האורות ולא יותר שיגבילו אותם הכלים לעצור אותם מלהפריז על המדה והגבול הנמדד להם הוא בחי' חכמה דאצי' שנק' בשם גוזר ומקיים שהיא גוזרת כמה בשיעור ומדה יתפשטו האורות ולא יותר וכן יקום בלי תוס' על המדה ולא יוגרע ממנה כפי שמדדה וגזרה בחי' החכ' העליונה ושיעורים והגבולים ההם עלי' אין להוסיף וממנה אין לגרוע ולכך נק' עולם האצי' בשם עשי' מצד צמצום של הכלי' המגבילי' את האורות שיתפשטו בשיעורים וגבולי' אשר הגבילה החכ' עליונה שהוא מקור העשי' הזאת וזהו כולם בחכ' עשית שדייקא בחכ' נעשו כל הגבולי' בהנה שהוא גוזר ומקיים להיות מתנהג כל עולם האצילות עפ\"י גזירות וחיוב החכ' דאצי' ולהיות האורות מתפשטי' כפי שגזרה החכ' ולא יותר מה שאין החכ' והשכל דאצי' מחייב להתפשט יותר שאז ממילא נעצרה השפע מלהתפשט יותר כנ\"ל.\n<b>אך</b> בחי' ההמשכה זו של הגבולים שבחכ' הוא ממקורה בחי' מו\"ס דא\"א שלכך נק' בשם חכמ' סתימא' ע\"ש העלמה שגנוזה בהכ\"ע ולא אתפתחא ולא ידיע כלל משא\"כ החכ' הגלוי' דאצי' שנמשכה ממנה היא מתפתחת לל\"ב<sup data-n=\"4102\">19</sup> שבילין ידיעין כמ\"ש באד\"ר ע\"ש והיינו שקו המדה המודד את כל השפע דאצי' בשיעור ומדה גבולי' בכמה בשיעור יתפשטו האורות ולא יותר הוא נמשך מבחי' בוצינא דקרדוניתא הוא בחי' גבו' דעתיק שמתלבש במו\"ס דא\"א דאצי' והיא מקור בעשי' של הגבולי' דאצי' שנק' בשם קו המדה שהחכ' הגלוי' דאצי' מקבלת השפע מבחי' קו המדה דגבורה דעתי' המלובש במו\"ס איך להיות גוזר המדות והגבולי' ואיך לקיי' וכו'.\n<b>וזהו</b> ברוך אומר ועושה זהו מו\"ס דא\"א שמלובש בו גבור' דעתיק שהוא עיקר הקו המדה דאצי' והוא המקור לעשי' דחכ' הגלוי' הגוזר ומקיים כל המדות והגבולי' דאצי' כפי שנמדדו במו\"ס דא\"א מקורה וזהו אומר ועושה שהאמירה דח\"ס היא מקור להעשי' דחכ' אשר כולם בחכ' עשית דהיינו כפי שנמדד באמירה דמו\"ס כך תגזור ותקיים החכ' הגלוי' דאצי' וברוך הוא ההמשכה מעצמיות המאציל",[["4102","19","<b>לל\"ב שבילין ידיעין כמ\"ש באד\"ר</b>: ראה זהר (אד\"ר) נשא קכח, ב. קכט, א. קלו, א."]]],[2100990190,"המרומם לבדו ומתנשא אפי' מערך מו\"ס דא\"א שיתלבש במו\"ס דא\"א ובחכ' גלוי' כו' וכנ\"ל וד\"ל.\n<b>ועוד</b> יש לפרש בע\"א שלכן נק' עולם האצילות בשם עשי' כי עשי'<sup data-n=\"4103\">20</sup> הוא מלשון תיקון כמו ועשתה<sup data-n=\"4104\">21</sup> את צפרני' (כמשי\"ת במ\"א ע\"פ גבורי כוח עושה דברו ע\"ש שכ' מלאכה הנעשית לצורך תיקון נק' בשם עשי' ואלו הן הל\"ט<sup data-n=\"4105\">22</sup> מלאכות דו' ימי המעשה החורש והזורע והאופה כו' שהם הכל בחי' תיקונין שמתקן את המאכל להיות ראוי למאכל אדם ולכן נק' עולם האצי' בשם עשי' כי הוא עולם התיקון שבו נתקנו ונתבררו הרפ\"ח ניצוצין דתהו שנפלו בשבירה וז\"ש כולם בחכמ' עשית כי בחכמה<sup data-n=\"4106\">23</sup> כ\"ח מ\"ה דתיקון דוקא אתברירו כל הניצוצין דב\"ן דאצי' ומתתקנין בבחי' התיקון דמ\"ה וזהו העשי' דאצי' שהיא סוד הבירור דמ\"ה דתיקון שמברר למתקן בבחי' התיקון דאצי', אך בחי' הכח שבמה דאצי' הוא חכמ' הגלוי' דאצי' לברר ולתקן כמ\"ש כולם בחכ' עשית הוא נמשך ממקורו בחי' מו\"ס דא\"א ששם עיקר הבירורים והוא המשפיע כח והארה בחכ' הגלוי' לברר ולתקן. וזהו סוד ברוך אומר ועושה הוא בחי' מו\"ס דא\"א שממנו נמשך בחי' עשי' הוא התיקון דאצי' אשר כולם בחכ' הגלוי' דאצי' עשית ותקנת אך מקור העשי' הזאת הוא בחי' מו\"ס דא\"א שאומר ועושה שכפי שגוזר אומר במו\"ס כך עושה החכ' גלוי להיותה אח\"כ כן גוזר ומקיים כו' כנ\"ל וד\"ל.\n<b>ברוך</b> עושה בראשית (אימא דאצילות). פי' חכמה דאצי' נק' בשם ראשית כמ\"ש ראשית<sup data-n=\"4107\">24</sup> חכמ' כו' ובינה דאצי' הוא העיקר העשי' דאצילות שנק' בשם עושה ממש לפי ב' הפירושים שנת\"ל כפי פי' הא' דאדם דאצילות נק' בשם עשי' מצד הצמצומים דאורות דז\"א בכלים המגבילים הרי הבינה היא מקור המדות דז\"א ממש שהיא אם הבנים ממש שהתהוות המדות היא מבנין אימא כמו עד\"מ בנפש המתבוננת באיזה מושכל שנולדים מזה המדות אהוי\"ר שישנם להמדות במציאותן בעודן מכוסים בבחי' ההתבוננות בהעלם ולכן נק' בשם עושה שהוא בחי' העשי' ממש של המדות דז\"א האורות המצומצמים בתוך הכלי משא\"כ החכמ' הוא המקור לעשי' ואינה בחי' עשי' ממש וכמ\"ש<sup data-n=\"4108\">25</sup> בזוהר כולם בחכמ' עשית בבינה שע\"י התלבשותה בבינה היא פועלת העשי' דמדות דז\"א דאצי'.",[["4103","20","<b>עשי' הוא מלשון תיקון</b>: ראה תו\"ח בשלח (הוצאת קה\"ת — תשס\"ג] קלט, ד: וכידוע בע\"ח דעשי' הוא התיקון כמ\"ש לעשות לתקן וכן ועשתה את צפרניה. וראה סה\"מ תקס\"ב ח\"ב ע' תפ. ובאוה\"ת בראשית כרך ג ע' תקיד בשם הזוהר [ראה זהר תרומה קנה, סע\"ב]. באוה\"ת בראשית כרך ו ע' תתרנב ותרגומו. וראה ב\"ר פי\"א ובפרש\"י שם."],["4104","21","<b>ועשתה את צפרני'</b>: תצא כא, יב. ראה רש\"י בראשית א, ז. מובא בשם ”הת\"א\" בסה\"מ תרס\"ב ע' שנז. תער\"ב ח\"ג ע' א'שפט. ראה לקו\"ש חכ\"ה ע' 343 בהערה 30."],["4105","22","<b>הל\"ט מלאכות. . שמתקן את המאכל</b>: ראה לקו\"ת תזריע כ, ד."],["4106","23","<b>בחכמה כ\"ח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["4107","24","<b>ראשית חכמה</b>: תהלים קיא, א."],["4108","25","<b>וכמ\"ש בזוהר</b>: ראה זוהר תזריע מג, א. לקו\"ת אמור לג, ד. ראה כא, ג. דרושים ליוהכ\"פ סט, א. תו\"ח בראשית ח, ג."]]],[2100990191,"<b>וזהו</b> עושה בראשית. פי' בינה עושה המדות דז\"א שנק' בשם אדם דעשי' ע\"י התלבשות החכמה בהמקור העשי', וזהו עושה בראשית כהתלבשות החכ' בה שנק' ראשית כנ\"ל וכפי הפי' השני שלכן נק' אצילות בשם עשי' לשון תקוני' מצד היותו בחי עולם התיקון שם מ\"ה שמברר כל הניצוצין דב\"ן ומתקנם לכך נק' בינה דתיקון דאצי' בשם עושה ממש בהיות עיקר השבירה דתוהו הי' בז' התחתונות דאימא דוקא כמ\"ש וימלוך<sup data-n=\"4109\">26</sup> בלע ושם עירו דין הבה כו' וימת כו' לכן התיקון הוא ג\"כ בבינה דתיקון דאצילות באותו מקום שהי' השבירה, וזהו עושה הוא בינה דתקון ששם הוא עיקר הבירור והתיקון דניצוצין דתהו אך במה בראשית בחכ' שנק' ראשית כ\"ח מ\"ה המלובש בה כי בחכ'<sup data-n=\"4110\">27</sup> דוקא אתברירו ע\"י התלבשות בבינה וזהו סוד כולם בחכ' בחכ' עשית בבינה וכנ\"ל וד\"ל.\n<b>ברוך</b> מרחם על הארץ (ז\"א דאצי'). פי' ארץ הוא<sup data-n=\"4111\">28</sup> בחי' מל' דאצי' אשר עיקר בנינה מהגבורות כמאמרז\"ל דינא<sup data-n=\"4112\">29</sup> דמלכותא דינא וכתיב מלך<sup data-n=\"4113\">30</sup> במשפט יעמיד ארץ שכל הנהגות העולמות דבי\"ע שמנהגת מדת מל' דאצי' הוא הכל עפ\"י דין ומשפט כנודע גם עיקר בנין המל' הוא מהגבורה אשר א\"א בלא\"ה שתהי' הממלכה נכונה כי אין<sup data-n=\"4114\">31</sup> מלך בלא עם דווקא הזרים<sup data-n=\"4115\">32</sup> ונפרדים דווקא ומצטרך להתהוות עולמות הנפרדים המחודשים מאין ליש והם בע\"ג ותכלית שמזה א\"א זולת ע\"י מדת הגבור' והצמצומים להתעלם ולהסתתר האא\"ס ב\"ה מהם עד שיתראו ליש ודבר בפ\"ע ולכן עיקר בנינה מהגבורו' דוקא ולזאת צריכים להמתיק הגבורות שבמל' והיינו ע\"י המשכות מ\"ד דז\"א שרובו הם חסדי' להמתיק הגבורות שבמל' וזהו המשכת מ\"ד דז\"א להיות מרחם על הארץ ע\"י השפעת בחי' חסדים וזהו מרחם על האדץ וד\"ל.\n<b>ברוך</b> מרחם על הבריות (כתר נוק' דאצי'), דהנה הבריות הם המלאכי' ונשמות דבי\"ע שמל' דאצי' מקורן משפעת להן בחי' חסדי' שקבלה מז\"א דאצילות לרחם עליהם להוסיף אורות להם אשר א\"א להתמשך השפע של החסדים והרחמים אליהן מז\"א דאצילות אשר נשגב מהם הגבה למעלה מאד נעלה זולת ע\"י אמצעות מדת מל' דאצי' מקורן שמקבלת תחילה השפע מז\"א בעלה וזהו מרחם על הארץ ואח\"כ משפעת להן בבי\"ע וז\"ש מרחם על הבריות שהוא נוק' דאצילות המרחם על הבריות וד\"ל.\n<b>ברוך</b> משלם שכר טוב ליראיו (כתר דבריאה). פי' ע\"י שמקבלת הנוק' דאצי' בחי' החסדים והרחמים מז\"א בעלה אזי נעשית היא בחי' עתיק לבריאה כנודע ואז",[["4109","26","<b>וימלוך בלע</b>: וישלח לו, לב."],["4110","27","<b>בחכ' דוקא אתברירו</b>: ראה זהר פקודי רנד, סע\"ב."],["4111","28","<b>ארץ הוא בחי' מלכות דאצילות</b>: מא\"א א, קכו. קה\"י בערכו. ראה לקו\"ת ואתחנן י, ב."],["4112","29","<b>דינא דמלכותא דינא</b>: גיטין י, ב. וש\"נ."],["4113","30","<b>מלך במשפט יעמיד ארץ</b>: משלי כט, ד."],["4114","31","<b>אין מלך בלא עם</b>: ס' החיים פ' גאולה פ\"ה. בחיי וישב לח, ל. עמה\"מ שער שעשועי המלך רפ\"א."],["4115","32","<b>הזרים ונפרדים דווקא</b>: ראה שער היחוד והאמונה פ\"ז."]]],[2100990192,"נמשך ממנה השפע של הרחמים מבחי' י\"ג ת\"ד דא\"א בבריאה לשלם שכר טוב ליראיו, והיינו כי ג\"ע העליון הוא בחינת בינה דבריאה אשר ממנה מקבלים הנשמות שבג\"ע השפעה טובה בהשגתן מזיו השכינה להתענג על הוי' וכנודע שבינה<sup data-n=\"4116\">33</sup> דבריאה נק' בחי' רחובות הנהר עליון היוצא מעדן בחי' חכמ' דבריאה והחכ' מאין תמצא מבחי' הכתר דבריאה שהחכ'<sup data-n=\"4117\">34</sup> נק' בחי' שכל הנעלם שנובעת מבחי' אין הכ\"ע אשר ישת חושך סתרו, וזהו ברוך הוא בחי' ההמשכה מכ\"ע מקור הבני\"ם בג\"ע עליון ותחתון להשפיע שכר טוב ליראיו הם הנשמות שבג\"ע עליון ותחתון להוסיף אורות בבנים שיזכו להשגות חדשות נפלאות ע\"י ההשפעה מן המקור הוא הכ\"ע דבריאה וד\"ל.\n<b>ברוך</b> חי לעד וקיים לנצח (אבא דבריאה). פי' אבא דבריאה נק' בשם חי כי החכמה<sup data-n=\"4118\">35</sup> תחי' שהוא מקור החיים של כל מציאות הנפעלים בבי\"ע כי בינה<sup data-n=\"4119\">36</sup> דבריאה נק' בשם אלקי' חיים שהוא בחי' המשכות החיים ממש שנמשך ממנה להנפעלים דבי\"ע והחכ' הוא מקור החיים דבריאה הוא מקור החיים שהחיים נמשך ממנה כי הנהר הוא יוצא מעדן המקור המעיין של החיים כו' (וכן עפ\"י בחי' התחלקות ד' מדריגות דצח\"מ נק' החכ'<sup data-n=\"4120\">37</sup> בשם חי כנודע) וז\"ש ברוך חי לעד וקיים לנצח, פי' לעד הכוונה על בחי' מקום ונצח בחי' הזמן והיינו שבבחי' המקום דסדר ההשתלשלות מעלה ומטה מתפשט החיות שנמשך מהחכמה במורד למטה מטה עד סוף כל סדרי ההשתלשלות כו' וקיים לנצח בבחי' הזמן לנצח נצחים כו' ואין הפי' של חי הוא שם העצם כמו שאומרים על האדם שהוא חי ח\"ו כ\"א ע\"ש הפעולה שמשפיע החיים לזולתו והוא מקור החיים של כל הנפעלים כו' וד\"ל.\n<b>ברוך</b> פודה ומציל (אמא דבריאה). פי' שלכן נק' אימא<sup data-n=\"4121\">38</sup> דבריאה בשם פודה ומציל בהיות ידוע שאימא היא מקור המדות דחו\"ג דז\"א כמ\"ש אם הבנים שמחה כו'. והנה בעולם הבריאה מבחי' ז\"א דבריאה נמשכת בחי' סנהדרין שדנין בהיכל הזכות אם לזכות אם לחיוב שכאשר יוצא זכאי אזי נמשך לו בחי' טוב וחסד מבחי' חסד דז\"א דבריאה ואם יוצא חייב אזי מוסרים אותו בגהינם לדונו עפ\"י מדת הגבורה דז\"א (וכמ\"ש בזוהר<sup data-n=\"4122\">*38</sup> שהגיהנם נמשך לו מהיכל הזכות שמוסרים לשם החייבי' כו' ע\"ש). והנה כאשר נמשכה השפע בהיכל הזכות לחיוב אזי נענש בעונש הדין המר ביסורי הגהינם כו' אכן בבחי' בינה דבריאה שנק' היכל ק\"ק דבריאה",[["4116","33","<b>שבינה. . רחובות הנהר</b>: וישלח לו, ז. ראה זהר (אד\"ר) נשא קמב, א."],["4117","34","<b>שהחכ'. . שכל הנעלם</b>: ראה מאמרי אדה\"א בראשית ע' ח. וש\"נ. וראה תו\"ח לך פב, ד."],["4118","35","<b>החכמה תחי'</b>: ראה קהלת ז, יב."],["4119","36","<b>בינה דבריאה נק' בשם אלקי' חיים</b>: ראה זהר יתרו סח, ב. ובהגהות הרח\"ו שם: ע\"ח שער (כו) הצלם רפ\"ג. לקו\"ת להאריז\"ל ירמי' י, י. סידור האריז\"ל ומשנת חסידים [תפלת הבריאה פ\"ב מ\"א] בברכת יוצר."],["4120","37","<b>החכ' בשם חי</b>: ראה תו\"א בראשית ד, ד."],["4121","38","<b>אימא. . אם הבינה שמחה</b>: ראה זהר ויחי ריט א. יתרו פד, א. פה, ב. לקו\"ת דרושים לשמ\"ע פח, ד."],["4122","*38","<b>בזוהר שהגיהנם</b>: ראה זהר פקודי רמח, א ואילך."]]],[2100990193,"מקור המדות דבריאה שם יש הצלה ופדי' להציל אף החייב שלא למסור אותו בדין דהיכל הזכות כ\"א להיות נושא עון ועובר על פשע ולסלוח לו והיינו כי אין<sup data-n=\"4123\">39</sup> הדין נמתק אלא בשרשו הוא בינה דבריאה שדינין<sup data-n=\"4124\">40</sup> מתערין מנה לכך נמתקין הגבורות בשרשן דווקא להיות בינה דבריאה פודה ומציל אותו שלא למסור אותו בדין דהיכל הזכות (שאז לא יהי' לו עוד תקנה כ\"א לסלוח לו ולעבור על פשע מפני שבבינה יוכל עדיין להתהפך ממה\"ד למה\"ר טרם שהגיע השפע בבחי' התחלקות הקוין דחו\"ג דז\"א דבריאה) וגם זאת ידוע שפנימיות בינה הוא מקור הרחמים והשמחה כמ\"ש אם הבנים שמחה רק דינין מתערין מינה מחיצוניות בינה לכן הוא פודה ומציל דווקא שהדינין נמתקין בשרשן בפנימיות בינה להצילו מן הדין) וזהו ברוך פודה ומציל וד\"ל.\n<b>ברוך</b> שמו (ז\"א דבריאה). פי' שהוא בחי' ש' הוי' דבריאה שנק' שמו בלשון נסתר נגד מדת מל' דבריאה שנק' אתה בחי' עלמא דאתגלייא, וז\"ש ברוך אתה<sup data-n=\"4125\">41</sup> (מל' דבריאה) שנק' אתה עלמא דאתגלייא וכמ\"ש ואתה<sup data-n=\"4126\">42</sup> מחי' וגו', וכלליות הכוונה של הברכות אלו מרדל\"א עד מל' דבריאה הוא בהיות מצטרך להתעורר בתפילה בבחי' העלאות מ\"ן בפסוד\"ז שאח\"כ בבחי' רצוא מלמטה למעלה כנודע לכן מצטרך להמשיך תחילה מיד מלמעלה מעלה מריש כ\"ד הוא בחי' רדל\"א עד בחי' מל' דבריאה לתת בו כח להתעורר בהעלאת מ\"ן כמ\"ש בפע\"ח שאף לצורך העלאות מ\"ן מצטרך תחילה המשכות מ\"ד לעורר בהעלאות מ\"ן כו'. וזהו כללות הכוונה דב\"ש וכו' וד\"ל.\n<b>ברוך</b> אתה ה' האל אב הרחמן המהולל בפה עמו. א\"ל (שערו' דא\"א י\"ג ת\"ד דיצי') אב הרחמן (אבא דיצי') המהולל בפה עמו (אימא דיצי'). והענין דהנה ידוע שעולמות בי\"ע<sup data-n=\"4127\">43</sup> נק' עולמות הנפרדים שנתהוו בבחי' התהוות מאין ליש ממש שלא כדרך ההשתלשלות אשר אין להם ערך ויחוס אל הבורא ית' הקדמון נצחי והנה נבראים בע\"ג ותכלית ונפרדים והווים ונפרדים כו' אשר לזאת א\"א להם להשיגו בחי' השגה במקורם האין שנתהוו ונמשכו ממנו להתפעל מהשגתם בו בבחי' שירה וזימרה והשתוקקות נפלאה לכלול במקורם עד שמתצמצם השפע תחילה בבחי' צמצום גדול עצום של השערות עליונות כי אינו דומה בחי' התהוותן ממקורם וקיומם תמיד מבחי' השפע חיות המגיע אליהם ממקורם תמיד כמ\"ש ואתה מחי' את כולם לבחי' הנשמ' המחי' את הגוף כי הגוף לא נתהווה ממש מן הנשמה המלובשת",[["4123","39","<b>אין הדין נמתק אלא בשרשו</b>: ראה פע\"ח (שער השופר) שכ\"ו, פ\"א. תניא עם מ\"מ, הגהות והע\"ק לפל\"א."],["4124","40","<b>שדינין מתערין מנה</b>: ראה זהר ויקרא י, סע\"א. יא, רע\"א."],["4125","41","<b>ברוך אתה. . שנק' אתה עלמא דאתגלייא</b>: ראה ג\"כ תו\"א ויחי נג, ב."],["4126","42","<b>ואתה מחי'</b>: נחמי' ח, ו."],["4127","43","<b>בי\"ע נק' עולמות הנפרדים</b>: ראה תו\"א וישב כז, ג. סט, ג. משפטים מא, א. לקו\"ת בשלח א, ב. צו יז, א. וראה תו\"ח וישב רג, ג. רי, ג. מאמרי אדה\"ז הנחות הר\"פ ע' קפו ואילך. ביאוה\"ז לכ\"ק הצ\"צ ח\"א ע' שצו ואילך. תורת מנחם כרך ד ח\"א ע' 3. 11. ובכ\"מ."]]],[2100990194,"בו כ\"א מטיפת האב ואם והקב\"ה מטיל בו נשמה הרי הי' גוף נוצר מתחילה זולת התלבשות הנשמה בו רק הי' בחי' דומם בלי חיות וכאשר הנשמה מתלבשת בו היא מחי' אותו תמיד שיהי' חי וקיים כו' ולכן אם הי' באופן זה בחי' התהוות המלאכי' ונשמות בבי\"ע שהי' נפרדים באמת רק שמקבלים שפע החיים מלמעלה כמו שהגוף מקבל חיות מהנשמה הי' באמת אפשר להם להשיג בבחי' החיות שנמשך להן ממקורן החיים מאחר שהמה נפרדי' באמת אכן באמת אינו כן כי הלא<sup data-n=\"4128\">44</sup> ממך הכל שאף הכלי' שלהן נתהוו מאין ליש כי אין לך דבר שחוץ ממנו ח\"ו ולזאת איך אפשר להנפעלים עצמן מן המקור האין ליש להשיג במקור הפעולה שלהן אשר משם עיקר התהוותם ממש, וגם לא ידמה לחיות הנשמה שבגוף שנרגש פעולתה בגוף מצד התלבשותה ממש אשר לא כן למעלה שאין בחי' כח הפועל ית' מלובש בהנפעל ממש דא\"כ יהי' בחי' שינוי והתפעלות ח\"ו וכתיב אני<sup data-n=\"4129\">45</sup> הוי' לא שניתי וכמ\"ש במ\"א.\n<b>ואחרי</b> כל הדברים האלה יובן למשכיל היטיב איך שא\"א להנפעל ומחודש מאין ליש ממש להשיג במקורו שנתהוה משם ממש בבחי' השגה ממש זולת ע\"י שהשפע עליונה מתצמצמת בבחי' צמצום השערות לכל חד וחד לפום שיעורא דילי' כי כל מלאך או נשמה פרטי נבדל מחבירו במהותו ואיכותו כפי שינוי מקורו ממקור חבירו ולכך משונים המה בהשגותיהם ולכך כחו\"ח מקבל השפע של ההשגה משערה פרטי' שנתצמצם בה שפע החלק פרטי שלו (וזהו כפום שיעורא דילי' ממש כמ\"ש במ\"א) ואז לאחר שנתצמצמה השפע פירוש כהתחלקות פרטיות של השערות פרטי' לכל נברא פרטי לפום שיעורא דילי' יוכל להשיג בבחי' השגה במקורו האין שנמשך משם ויוכל להלל בבחי' שירה וזימרה בהשתוקקות נפלא' במקורו ית', וזהו מהולל לשון מתפעל שמתפעל בבחי' תהילה שנשפע בהנפעלים שיוכלו להללו, והיינו ע\"י אל אב הרחמן הם ל\"א קוצי דשערי' כו' שנשפע ע\"י השפע להנפעלים שיוכלו להלל ע\"י השגתם בו ית' ממש כנ\"ל וד\"ל.\n<b>ולהבין</b> כ\"ז באר היטיב צריך להקדי' ולבאר ענין השערות כו' הנה מורו (ה\"ה דמעזריטש) ע\"ה פי' ענין השערות שלמעלה שהוא עד\"מ בנפש האדם החכם גדול במושכלות נפלאות שמצטרך להשפיע השפע של המושכל לתלמידו הקטן אשר קטן שכלו מהכיל את השכל העמוק עמוק מי ימצאנו לתופסו כרוח בינתו הקצר ממש, אשר מוכרח הרב להלביש השכל באיזה משל ומליצה אשר ע\"י המשל יוכל התלמיד להבין הנמשל המושכל המלובש בהמשל דהנה צרופי אותיות המשל המה מהות זר ונפרד ממש לא ממהות הנמשל כלל רק הוא כלי ולבוש אליו המלבישו והוא מלובש בתוכו בכדי שע\"י יהי' אפשר להתלמיד לקבל הנמשל ולהבינו מבין צירופי אותיו' המשל ואח\"כ כשתופס התלמיד את הנמשל אזי אין צריך להמשל כלום ולא יצלח לו כלל כ\"א זורקו לחוץ שכלו כי העיקר הוא המושכל הנמשל רק המשל הי' לבוש אליו והי' תועלת וסגולה שע\"י יתפוס הנמשל שמבינו",[["4128","44","<b>הלא ממך הכל</b>: לשון הכתוב דברי הימים-א כט, יד."],["4129","45","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."]]],[2100990195,"מבין צירופי אותיות המשל דוקא הגם שהוא מהות זר ממש אשר בלעדו לא הי' יכול לתפוס המושכל כנ\"ל.\n<b>וככה</b> ממש בחי' השערות עליונות דכמו השערות<sup data-n=\"4130\">46</sup> שלמטה שבראש האדם שהם נגדלי' ממותרי מוחין שיונקים ממותרי מוחין שנשפע בחללי השערות אבל עצמות השערות המה בחי' מהות זר מן המוח עד שיוכל ליגזז אותם ולא יכאב לו כלל אכן כשימרוט ראשו אזי יכאוב לו מאד מצד שעיקרי השערות נאחזות במוח שיונקים השפע ממותרי המוח ויורד דרך חללו דווקא וה\"ז כמו השכל של הרב המלובש בהמשל שבתוך צירופי אותיות המשל מתצמצם ומלובש הנמשל שהוא תועלת להיות יוכל התלמיד לקבל ולהוציא הנמשל מבין צירופי אותיות המשל אבל לאחר קבלת הנמשל אינו מצטרך להמשל כלל כי הוא מהות זר ממש אשר אין לו שייכות אליו כלל וכמ\"כ השערות הם עצמם מהות זר והראי' שיוכל לגוזזן רק בתוך החללן נשפע מותרי מוח ואחוזין במוח כו' שמצד שהמה מהו' לבושי' זרים יוכל להתצמצם השפע בתוך חללן להגיע אל כלי המקבל וככה ממש למעלה שכל ההשפעות העליונות הוא הכל דרך השערות כי השערות הם מהות המח וגדלים ממותרי מוחין דוקא והיינו מה שהוא מותרות ואין מצטרך לעצמו הוא מתפשט לזולתו כי עצמות המאציל ית' אין לו צורך לעצמו כלל שהוא בחי' א\"ס ואין לך דבר שחוץ ממנו ח\"ו ולכן ההשפעה שנשפע ממנו להנפעלים נק' בשם מותרי מוחין שהוא בחי' מותרות הנמשך לזולתו ואין מצטרך לעצמו והיינו ע\"י צמצום השערות שהוא בחי' הלבושים נפרדים המכסים ומסתירים על השפע שבתוך חללן בכדי שיוכל המקבל לקבל השפע שהמה רק בחי' צינורות שע\"י תעבור השפע אל המקבל וכיון שהגיע להמקבל אינו מצטרך לעצמות מהות לבושי השערות כלל וכמו התלמיד שאינו מצטרך להמשל רק עד שיבין מתוכו הנמשל שאז הוא פעולה ותועלת גדולה שפועל בהסתר וצמצום הנמשל בו שיוכל כלי התלמיד להבינו מתוכו דוקא אבל אח\"כ א\"צ לו כלל ועד\"ז המה כל בחי' השערות שלמעלה (הגם שאין שם בחי' מהות זר כמו המשל וכו') שהמה לבושים עבי' המכסים על השפע פנימי שבתוך חללן עד שהם זרים מערך השפע פנימי שבתוכו והמה סגולה ותועלת לצמצם השפע שתגיע לכלי המקבל ויוכל להשיג מהם דוקא השפע ההיא כו' כנ\"ל.\n<b>וזהו</b> אל אב הרחמן המהולל בפה עמו כו' שהתועלת להנפעלים מלאכי' דבי\"ע שיוכלו לקבל שפע ההשגה במקומם ית' ממש בכדי שיהללו אח\"כ הוא ע\"י השערות דוקא שנמשכו מבחי' אל ל\"א קוצי דשערי' כו' שמתצמצמה השפע בהן בהתחלקות ריבוי השערות פרטיי' לכחו\"ח לפום שיעורא דילי' שיוכל כאו\"א משערה פרטי' המיוחדת לו להשיג ממנה ההשגה פרטי' המיוחדת לו שנבדל ושונה בה מחבירו וד\"ל.",[["4130","46","<b>השערות. . ממותרי מוחין</b>: ראה תו\"א מקץ מט, ב. לקו\"ת שלח מה, ד. ראה לד, א. דרך מצותיך קיג, ב. ובכ\"מ."]]],[2100990196,"<b>אך</b> בבחי' אל יש ב' פירושים שלפעמים נק' בשם חסד דאבא נמשך לחסד דז\"א כמ\"ש חסד<sup data-n=\"4131\">47</sup> אל כל היום אך אינו דומה לבחי' מדת החסד דז\"א ממש כ\"א הוא נהירו דחכמתא שיש בו הארת אבא מצד שנמשך החסד ממקורו הוא אבא מקור הקו ימין חח\"ן לזאת יש בו הארת אבא ולא כמהות מדת החסד סתם דז\"א שהוא מהות מדה לבד וכמ\"ש<sup data-n=\"4132\">48</sup> בזוהר ע\"פ השמים מספרים כבוד אל ע\"ש. אך באמת עיקרו הוא למעלה מאבא דאצילות דהיינו בחי' אל די\"ג ת\"ד דא\"א שהוא בחי' חסד דא\"א שלמעלה מהחכ' דאבא<sup data-n=\"4133\">49</sup> אחיד ותליא בי' שממנו נמשך בחי' המהות החכמ' כי אבא אחיד במזל<sup data-n=\"4134\">50</sup> הח' מזל ונוצר כו' ואימא במזל הי\"ג וכו' נמצא שמבחי' השערות דת\"ד דא\"א נתהוו החו\"ב ושרש כל הי\"ג ת\"ד הוא בחי' אל תיקון הראשון כו' (שהוא כולל ל\"א קוצין כו' כנודע והוא בחי' עצמיות החסד דא\"א שלמעלה מאד נעלה מבחי' החכמה עד שהויות החכ' ממנו הוא ע\"י צמצום השערות דווקא והוא מקור לכל השערות שבכל ההשתלשלות כו' וד\"ל).\n<b>וזהו</b> אל אב הרחמן, פי' שתחילה נמשך השפע מבחי' אל די\"ג ת\"ד דא\"א דיצי' מבחי' השערות דא\"א להתהוות בחי' החכ' דיצי' כי אבא אחיד במזל הח' דא\"א ותליא שהתהוותו הוא מבחי' חסד דא\"א כנ\"ל ואח\"כ כשמתהווה בחי' החכ' דיצי' אז נמשך מבחי' החכ' בחי' שפע הרחמים והחסדים למלאכי' ונשמות דיצי' כי חכ'<sup data-n=\"4135\">51</sup> הוא שרש קו ימין ולכך נק' בשם אבא מצד היותה מקור הרחמים. וזהו אב הרחמן (אבא דיצי') הוא מקור הרחמים וע\"י התעוררות הרחמנות דוקא נמשך שפע חסדים אליהם להיותם משיגים במקורם ית' בבחי' השגה ממש בכדי שיהללוהו וישבחוהו ויפארו כו', וענין הרחמנות הוא כמו עד\"מ מי שהי' עשיר גדול רך וענוג מאד ונתדלדל מאד להיות חסר לחם ומדוכא ביסורין כו' שיכמרו רחמי האדם עליו יותר ביודעו ומכירו מנגד שירד מאיגרא רמה כו' מן העני שהי' מנעוריו מורגל בלחם צר ומים לחץ כי הירידה הגדולה הזאת שירד מאגרא כו' מן הקצה אל הקצה מתעורר בלב האדם רחמנות יותר גדולה. ככה ממש למעלה שממשיכים בחי' שפע חסדים מבחי' אבא דיצי' להנשמות ומלאכים דיצי' ע\"י התעוררות מדת הרחמים עליהם מאב הרחמן והיינו בהיות שרש הנשמות הוא מבחי' ז\"א דאצי' וגם עלו במח' קדומה כו' ועתה ירדו כ\"כ בסתר המדריגה למטה להיות נפרדים ממש וא\"כ יעוררו רח\"ר שלא יהי' הנברא המחודש בחושך ילך בבלי דעת והכרה במקורו ית' כלל מאחר שהי' תחילה צרורה בצרור החיים בז\"א דאצי' בתכלית היחוד (וכ\"ז ירידה יותר אין קץ מבחי' ירידת העשיר הרך והענוג להיות עני מחזר על הפתחים חסר לחם). וזהו אב הרחמן שע\"י מדת הרחמנות שמעוררים עליהם מאבא דיצי' נמשך",[["4131","47","<b>חסד אל כל היום</b>: תהלים נב, ג."],["4132","48","<b>וכמ\"ש בזוהר ע\"פ השמים מספרים</b>: ראה זהר לך צד, א. צו ל, ב. לא, א. אחרי סה, א."],["4133","49","<b>דאבא אחיד ותליא</b>: זוהר במדבר קיח, ב. ע\"ח (שער או\"א) שי\"ד, פ\"א."],["4134","50","<b>במזל הח' מזל ונוצר</b>: ראה אגרות קודש מכ\"ק אדמו\"ר זי\"ע ח\"ב ע' קיט ואילך. תשא לד, ז. ראה מאמרי אדה\"א שמות ח\"א ע' קעב."],["4135","51","<b>חכ' הוא שרש קו ימין</b>: ראה זח\"ב קעה, ב. פרדס שער א (שער עשר ולא תשע) פ\"ב. שער טו (שער מהות והנהגה) פ\"ה. ובכ\"מ."]]],[2100990197,"אליהם שפע החסדים דרך צמצום השערות לכל חד לפום שיעורא דילי' שישיגו בבחי' השגה במקורו ית' ויהללוהו ויפארו כו', וזהו המהולל בפה עמו (אימא דיצי') פי' שכאשר נתפס השפע העליונה בבחי' בינה דיצי' בכלי השגתם ורוח בינתם של הנשמות דיצי' ממש אז הוא מהולל בפה עמו מהולל ממש מצד שמשיגי' ממש בבחי' בינה והשגה ממש אז יהללו בבחי' רננה ושירה מחמת ההשגה אבל בעוד שהשפע נעלמה בבחי' חכ' דיצי' שנק' שכל הנעלם שהוא למעלה מגדר השגה ממש אז אין נק' מהולל מחמת העדר השגתם עדיין שאינו נתפס בהן בבחי' השגה ממש כמ\"ש אם הבנים שמחה שבינה היא אם הבנים מקור המדות כו' ולכן בחי' התהוות הרננה ושמחה בתהלה שלהם הוא לאחר שנתפס השגה ברוח בינתם דוקא ממש וזהו המהולל בפה עמו (אימא דיצי') כנ\"ל וד\"ל.\n<b>משובח</b> ומפואר בלשון חסידיו ועבדיו (ז\"א דיצי'). הנה חסידיו הם הנשמות שלמעלה ועבדיו הם המלאכים עליונים שנקראים עבדי ה' ושניהם הם למטה מבחי' פה עמו שהם הנשמות הגבוהי' מאד נעלה כמו נשמת האבות<sup data-n=\"4136\">52</sup> שהן המרכבה ונשמת מרע\"ה<sup data-n=\"4137\">53</sup> שזכה לבינה שאלו נקראי' בשם פה עמו בינה דיצי' שמהולל בפיהם ע\"י המשכות השפע עליהם מאב הרחמן אבא דיצי' ומאל דת\"ד דא\"א דיצי' לאבא דיצי' כו' וע\"י השגתם בהשפע זו הם מהללים כו' אבל חסידיו הם הנשמות שלמטה שנמשכים מבחי' מל' דיצי' אימא תתאה דכמו שאימא עילאה בינה דיצי' אולידת בנין הן הנשמות הגבוהי' הנ\"ל כן אימא תתאה מל' דיצי' אולידת בנין והם נקראי' בשם חסידיו ועבדיו המה המלאכי' דיצי', שנקראו בשם עבדים שהם למטה מבחי' הנשמות שנק' חסידיו והיינו שהמלאכים נדמו כעבדים לפני המלך והנשמות כשרים לפני המלך (וכדאי' בגמ' במאמר<sup data-n=\"4138\">54</sup> ריב\"ז לאשתו על רחב\"ד לא שהוא גדול ממני אלא שהוא דומה כעבד לפני המלך ואני כשר לפני המלך כו' וכמשנ\"ת במ\"א<sup data-n=\"4139\">55</sup> בארוכה ע\"ז ההפרש בין שר ועבד שבהעבד ימצא בחי' הביטול יותר אבל השר הוא גבוה ממנו במדריגה הרבה והא בהא תליא כו' ע\"ש) והיינו שהעבד הוא למטה במדריגה מבחי' השר ולכך ימצא בו בחי' מציאות הביטול יותר אבל השר שהוא הגבה למעלה במדריגה ממנו לכך לא נמצא בו בחי' מציאות הביטול כ\"כ אף כשעומד לפני המלך נחשב לשר בבחי' יש ודבר מה כו'.\n<b>וככה</b> עד\"מ למעלה הנשמות נמשכי' מבחי' המח' העליונה שעלו במח' לכך אף לאחר ירידתן למטה הם כשרים לפני המלך שהמה הגבה מאז נעלה מערך המלאכי' שנק' בשם עבדים מצד שפלות מדריגתן שלמטה הרבה מהנשמות כו' אכן",[["4136","52","<b>האבות שהן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. זהר (רעיא מהימנא) פנחס רנז, ב. תניא פל\"ד."],["4137","53","<b>מרע\"ה שזכה לבינה</b>: ראה לקו\"ת ואתחנן ג, ד. ובכ\"מ."],["4138","54","<b>במאמר ריב\"ז לאשתו</b>: ראה ברכות לד, סע\"ב. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשטו ואילך. תו\"ח וישב רב, ב."],["4139","55","<b>במ\"א בארוכה ע\"ז ההפרש בין שר ועבד</b>: לקו\"ת ברכה צו, ד. וראה לקו\"ת ראה כט, ד. דרושים לר\"ה נה, ד. וראה מאמרי אדמו\"ר הצ\"צ — הנחות תרט\"ו ע' פו."]]],[2100990198,"מעלה יתירה נודעת לנו בהם בבחי' מציאות הביטול שנמצא בהם יותר מצד זה עצמו שהמה כעבד לפני המלך שבטל בתכלית הביטול בלי תפיסות מקום לעצמו רק בטל לשליחות המלך ולפקודתו בכל אשר ישלחנו ואף כשעושה שליחות המלך אין נרגש בו עצמו בבחי' תפיסות יש ודבר בפ\"ע כאלו הוא מושל ושליט כי אם הוא עושה שליחות המלך והוא עצמו בטל בתכלית הביטול בלי תפיסת מקום לעצמו כלל וככה המלאכי' עליונים נקראים בחי' עבדים שהם שלוחי השפע עליונה שהמה הצינורות שע\" תעבור השפע למטה בפעולה מעשית ולכן יוכל המלאך לומר בשם הוי' כמו שאמר המלאך לאברהם בי<sup data-n=\"4140\">56</sup> נשבעתי נאום ה' וכן בהגר כתיב ותקרא<sup data-n=\"4141\">57</sup> למלאך הדובר כו' בשם הוי' אל ראי כו' מצד שהכלי שלהן בטלה בתכלית הביטול לבחי' שילוח השפע שבתוכה מאור א\"ס ב\"ה ממש ואינו תופס מקום לעצמו כלל לכך יוכל לומר בי נשבעתי נאום הוי' שזה שלוח השפע שבתוכו מהוי' ממש אומר נאום הוי' והכלי של המלאך בטלה בתכלית הביטול כו' וזהו כעבד לפני המלך אבל הנשמות הם כשר לפני המלך שאף שעומד לפני המלך הוא בחי' יש ודבר בפ\"ע הכי נכבד הוא ויהי לשר כו' ולזאת א\"א לומר להנשמ' נאום הוי' כמו המלאך כו', והסיבה לזה הוא מצד היותה למעלה במדריגה מהמלאך לכך לא נמצא בה בחי' מציאו' ביטול כ\"כ כ\"א כשר לפני המלך שהוא למעלה ממדריגת העבד וזהו בחי' חסידיו שהם נמשכים אליו בבחי' אהבה וחסד שהוא בחי' יש ודבר יש מי שאוהב, אבל המלאכים הם עבדי' בטלים בתכלית הביטול בחי' שלוחי השפע עליונה וזהו משובח ומפואר לשון מתפעל שמתפעל בבחי' שבחה ותפארת יש משבחי' ומפארים בחי' חסידיו ועבדיו והיינו ע\"י השפעתו בהן הארה מבחי' מדת התפארת דז\"א דיצי' שיפארו אותו, וזהו ומפואר (בל\"א ער ווערט בשיינט) כנ\"ל וד\"ל.\n<b>ובשירי</b> דוד עבדך. סוף פסוק דקאי אדלעיל אל אב הרחמן המהולל כו' עד ובשירי דוד כו' ובזה מסיים הענין ומתחיל בע\"א נהללך ונשבחך כו' ולא כדעת העולם דקאי לרע מיני' על נהללך כו', והיינו דוד<sup data-n=\"4142\">58</sup> עבדך הוא בחי' מל' דיצי' דכתיב אלקים<sup data-n=\"4143\">59</sup> אל דמי לך שמל' דיצי' היא מעלה מ\"ן בבחי' שיר וזמרה מלמטה למעלה, אך הכח והיכולת שבה להתעורר בהעלאות מ\"ן הוא ע\"י המשכות מ\"ד מלמעלה למטה לעוררה בהעלאות מ\"ן והיינו בחי' המשכות מ\"ד מאל דת\"ד דא\"א דיצי' לאבא ומאבא לאימא כו' כ\"כ במורד למטה עד בחי' מל' דיצי' לעוררה בהעלאות מ\"ן לשורר בבחי' שירה וזימרה כמ\"ש אלקים אל דמי לך. וזהו ובשירי דוד עבדך שכ\"כ נשפל במורד למטה השפע שנמשכה מאל אב הרחמן כו' ע\"י הברכה דברוך אתה כו' עד שמגע' בשירי דוד עבדך במל' דיצי' לעורר השיר שלה בחי' העלאות מ\"ן דילה.",[["4140","56","<b>בי נשבעתי נאום ה'</b>: וירא כב, טז."],["4141","57","<b>ותקרא למלאך הדובר</b>: ראה לך לך טז, יג — ותקרא שם ה' הדבר אליה אתה אל ראי."],["4142","58","<b>דוד. . מל' דיצי'</b>: ראה ג\"כ פירוש המלות סט, ג ואילך."],["4143","59","<b>אלקים אל דמי לך</b>: תהלים פג, ב."]]],[2100990199,"<b>אך</b> צריך לבאר איך יתכן השיר בבחי' מל' דיצי' שהוא בחי' ספי' אלקות ממש ואיך שייך בה בחי' הפירוד ח\"ו לומר שהיא משוררת בבחי' העלאות מ\"ן ממטה למעלה לדבקה בו ית' מאחר שהיא בחי' אלקות ומיוחדת עם אא\"ס ממש בתכלית היחוד, אך הענין הוא דהנה באמת האורות דמל' דיצי' הם מיוחדו' בבחי' כלליות אא\"ס ב\"ה בתכלית היחוד ואין נופל לשון השיר עליהן אבל בחי' הכלים שבמל' דיצי' נשפלים למטה להתלבש במלאכים ונשמות דיצי' שנפרדו מן האורות להיותן בבחי' עלמא דפרודא בבחי' פירוד בפ\"ע עליהן יתכן בחי' השיר והזימרה שמשוררים בבחי' העלאות מ\"ן מלמטה למעלה אל האורות דמל' להתייחד עמהן ולכך נק' בשם שירי דוד כי דוד מלך ישראל הי' נברא נפרד והי' מרכבה למל' דיצי' שבחי' הכלים דמל' דיצי' שנעשו נפרדים מהאורות בהתלבשותן בהנבראי' הנשמות ומלאכים נק' בשם דוד המלך אבל עצמיות האורות שבמל' שהן בחי' אלקות ממש לא יתכן לכנותם בשם דוד המלך אשר הי' בחי' נשמה ונברא כו' וזהו ובשירי דוד עבדיך שכ\"כ נמשך במורד למטה השפע דאל דת\"ד עד הכלי' דמל' דיצי' לעוררה בבחי' העלאות מ\"ן בשירי דוד עבדיך כנ\"ל וד\"ל.\n<b>נהללך</b> ונגדלך ונשבחך ונפארך ונמליכך. הנה אנחנו הנה בעשי' ולכך התהלה שלנו מתחלת מבחי' א\"א דעשי' שהוא מקור התהוות עולם העשי' שא\"א לנו להשיג יותר כאשר אנחנו הנה בעשי' שתכלית העילוי של השגתנו הוא בהאין המקור המהווה היש דעשי' וזהו נהללך (א\"א דעשי') בשבחות (ה\"ח דאימא) ובזמירות (ה\"ג דאימא) שהוא בחי' התעוררות המדות אהוי\"ר מבחי' הבינה והשגה במקור דעשי' בחי' א\"א ובזה נהללך ונגדלך (אבא דעשי') פי' כי חסד דז\"א נק' בשם גדולה כמ\"ש לך<sup data-n=\"4144\">60</sup> הוי' הגדולה וכו' ע\"ש ההתפשטות שלו בבחי' גדולה הן בבחי' עולם ומקום להתהוות ז' רקיעים והארץ שמהארץ<sup data-n=\"4145\">61</sup> לרקיע מהלך ת\"ק שנה וכן מרקיע לרקיע כו' עובי כל רקיע כו' והן בבחי' נפש להתהוות ריבוא רבבות מלאכים אשר אין מספר לגדודיו אלף אלפים ישמשוני' אך בחי' החסד דז\"א דעשי' מתפשטת בבחי' גדולה גשמיות להתהוות ז' רקיעים גשמיים בבחי' מקום ת\"ק שנה כו' וכן המלאכי' דעשי' המה גשמיי' כמ\"ש<sup data-n=\"4146\">62</sup> הרמב\"ן ז\"ל ע\"פ עושה מלאכיו רוחות משרתיו אש לוהט שהמלאכי' דעשי' נתהווה הגופות שלהם מב' יסודות דרוח ואש דעשי' הגשמיות כו' אבל למעלה מעלה בחי' התפשטות הגדולה היא ברוחניות כנודע.\n<b>והנה</b> ידוע ששרש התהוות החסד דז\"א הוא מבחי' אבא שרש הקו ימין דחח\"ן שהוא מקור החסד שמסתעף ממנו וזהו ונגדלך הוא אבא דעשי', פי' שאנו ממשיכי' בחי' מדת החסד דז\"א המתפשט בבחי' גדולה בעש\"נ דעשי' ממקורו בחי'",[["4144","60","<b>לך ה' הגדולה</b>: דברי הימים-א כט, י."],["4145","61","<b>שמהארץ לרקיע מהלך ת\"ק שנה</b>: חגיגה יג, א."],["4146","62","<b>כמ\"ש הרמב\"ן ע\"פ עושה מלאכיו רוחות</b>: תהלים קד, ד. ראה תניא פ\"מ. וראה גם תו\"א בראשית ד, א. לקו\"ת ברכה צח, א. ובסידור ערה, ד בשם ”ספר הגמול\" להרמב\"ן. וראה לקו\"ש ח\"ט ע' 403."]]],[2100990200,"אבא דעשי' שיהי' נמשך בחי' הגדולה וזהו ונגדלך וד\"ל וכן ונשבחך ונפארך הוא המשכות הת\"ת דז\"א דעשי' למטה שיפארוהו וישבחוהו כו' כנ\"ל עד ונמליכך הוא מל' דעשי' תכלית וסוף כל דרגין ממשיכי' אנחנו כו' כנ\"ל וד\"ל.\n<b>ונזכיר</b> שמך (מל' דאצי') מלכינו אלקינו יחיד (יסוד ז\"א דאצי'). פי' ע\"כ הי' בחי' המשכות השפע בערך וסדר ההשתלשלות שמי\"ג ת\"ד דיצי' עד מל' דיצי' נמשך בהדרגת ההשתלשלות ע\"י פ\"ה עמו וחסידיו ועבדיו כו' כנ\"ל ומא\"א דעשי' עד מל' דעשי' נמשך בהדרגה על ידינו שנגדלך ונהללך אנחנו שבעשי' המה כו' ועתה מצטרך להמשיך מלמעלה מסדר ההשתלשלות והיינו מ\"ש נזכיר שמך כי הזכירה הוא מרחוק דווקא מה שאין נמצא כאן כמו שמזכירין שם האדם שאיננו פה כ\"א הי' פה לא הי' מצטרך להזכיר כו' וגם ע\"י הזכירה הזאת ממשיכים השפע משם ממש כמו ע\"י קריאת השם באדם ממש כן הזכרת השם שלמעלה שבמה שמזכירין השם דכבוד מל' דאצי' ממשיכים אותו למטה מפני שהוא למעלה מערך ההשתלשלות שא\"א להמשיכו זולת ע\"י הזכירה כו' וד\"ל.\n<b>מלכינו</b> אלקינו יחיד (יסוד ז\"א דאצי'), דהנה יוסף הצדיק עליון הי' בן יחיד לאמו, והטעם שיסוד ז\"א נק' בשם יחיד הוא מפני שלמעלה מבחי' יסוד ז\"א הם נו\"ה תרין בעין כו' דכאשר השפע נמשכת מחו\"ג דז\"א בהן הן מבשלות הזרע כו' ולזאת לא ימצא שם בחי' יחיד דכאשר יש בחי' נצח הגומר ומנצח התפשטות והרקת השפע למטה יש כנגדו בחי' הוד המעצור השפע כו' ולזאת א\"א לקרותו בשם יחיד מאחר שיש דבר היפוכו לנגדו הגם שמתכללים ומתמזגים כא' במזג השוה כנודע אעפי\"כ בשם יחיד א\"א לקרותם וכן בחו\"ג דז\"א כו' שמתחלקים בבחי' קוין ימין ושמאל כו' אכן בחי' יסוד דז\"א נק' יחיד שהוא למטה מכולם ובו מתכנשין כל האורות כולם כא' להיות גומר ההשפעה למטה אל המקבל שאין נגדו כלל רק הוא יחיד המשפיע השפע דכנישו דכל נהורין אל המקבל כו' וזהו מלכינו אלקינו יחיד יסוד ז\"א דאצי' שממשיכים השפע ממנו שלא כדרך דהשתלשלות כו' כנ\"ל וד\"ל.\n<b>מלך</b> משובח ומפואר עדי עד שמו הגדול, פי' שלכך שממשיכים עוד השפע מלמעלה מסדר ההשתלשלות כמ\"ש ונזכיר שמך כנ\"ל מפני שמצטרך לקיים בחי' הברכה וההמשכה שהמשיכו תחלה בסדר ההשתלשלות מריש כל דרגין הוא בחי' אל אב הרחמן עד סוף כל דרגין הוא בחי' מל' דעשי' שיהי' לה קיום נצחי ותתפשט בבחי' א\"ס ממש בעש\"נ פי' ולזאת ממשיכי' עוד שנית מלמעלה מסדר ההשתלשלות ע\"י הזכרת שמו ית' להיות מכריח השפע זו שבסדר ההשתלשלות שתתגלה בבחי' גילוי למטה מטה ויהי' לה קיום נצחי בבחי' הזמן וכן בעולם תתפשט בבחי' א\"ס ממש, וזהו מלך משובח ומפואר עדי עד הוא בחי' התפשטות בבחי' א\"ס ממש להיות לה קיום נצחי כו' ולא יהי' עוד בחי' עליות וירידות כמו שהי' מקודם בנין בהמ\"ק ואח\"כ חורבן בהמ\"ק כו' כ\"א יתקיים לעדי עד ולנצח נצחים שמו הגדול בבחי' גלוי ממש למטה וכנ\"ל וד\"ל."],[2100990201,"<b>ברוך</b> אתה ה' מלך מהולל בתשבחות. פי' זהו בחי' ההמשכה כללית מהוי' שהוא עצמיות ז\"א דאצי' על כלל ההמשכות שהמשיכו קודם לקיים אותם בקיום ממש ושיתגלו מהעלם לגילוי בבחי' תהילה בארץ, וזהו ברוך המשכה ממקום גבוה מאד נעלה מכולם מהוי' עצמות ז\"א דאצי' שיהי' בחי' מלך מהולל בבחי' גילוי ממש בתשבחות אלו שנאמרו מקודם כו' וד\"ל."],[2100990202,"<h3>נוסח שני: ברוך שאמר והי' העולם (בקיצור)</h3>\n<b>ברוך שאמר בקיצור</b>\n<b>ברוך</b><sup data-n=\"4147\">1</sup> שאמר והי' העולם<sup data-n=\"4148\">2</sup> רדל\"א דלא ידע בר איהו, ברוך הוא הוא גלגלתא דאריך פי' כי בחי' הוא הוא ענין העלם שאינו ידוע מי הוא, משא\"כ אתה רומז לבחי' גילוי. ולכך נקרא חכמה אתה<sup data-n=\"4149\">3</sup> אבינו, וכן חסד אתה<sup data-n=\"4150\">4</sup> כהן כנ\"ל<sup data-n=\"4151\">5</sup> ומל'<sup data-n=\"4152\">6</sup> אותיות מא' ועד תי\"ו, לפי שהוא בחי' גילוי כי חכמה<sup data-n=\"4153\">7</sup> נק' ראשית הגילוי. עד\"מ בנפש המשכלת כח החכמה נרגש אצלו, משא\"כ מה שלמעלה מן החכמה אינו מורגש כלל הגם שידוע בבירור שיש מציאות בחי' שלמעלה מן החכמה הוא נעלם מהותו ממנו כו' וכך למעלה<sup data-n=\"4154\">8</sup> מן החכ' נק' אתה לפי שהוא בגילוי מהותו ממש, אבל ההסתר<sup data-n=\"4155\">9</sup> נקרא הוא שנעלם מהותו רק מציאותו לבד שידוע בבירור שיש בו כח למעלה מהחכמה כנ\"ל<sup data-n=\"4156\">10</sup> ולכך הוא שורש לנאצלים כנ\"ל וד\"ל.\n<b>אבל</b> רדל\"א הוא פנימיות בחי' התחתונה שבמאציל שגם מציאותו אינו ידוע, לא שבפני המקבלים אינו ניכר שפעו<sup data-n=\"4157\">11</sup>, אלא גם בפני עצמו איננו מהות. וזהו והי' העולם פי' שאמר מאותיות שבמל' דא\"ק להתלבש להיות ע\"ס בעתיק שהם בנין",[["4147","1","<b>ברוך שאמר בקיצור</b>: הנחת המהרי\"ל. נעתק מכת\"י 1804 לח, א. נמצא ג\"כ בכת\"י 35 עב, ב. 115 קסז, א. 284 צו, א. 954 נד, א. 2068 א, א.\nובכת\"י 735 קנד, ב נמצא קטע התחלה מהמאמר, ומסיים המעתיק: ע\"כ כתבתי ולא רציתי לכתוב עוד מזה מחמת לפי שאין לו הבנה.\nהנחת כ\"ק אדה\"א נדפס בסידור עם דא\"ח (מגוכתי\"ק 1025 בכותרת: ליל שבת פ' מטות מסעי [תקס\"ו]) לט, ג — מד, א.\nהנחת ר' משה בן אדה\"ז נדפס לעיל ע' תקסז (וראה שם בהמ\"מ).\nמאמר זה נדפס ג\"כ במאמרי אדה\"ז סידור ע' תכט."],["4148","2","<b>ברוך שאמר והי' העולם</b>: נוסח תפלת פסוד\"ז."],["4149","3","<b>אתה אבינו</b>: לשון הפסוק ישעי' סג, טז."],["4150","4","<b>אתה כהן</b>: לשון הכתוב תהלים קי, ד."],["4151","5","<b>כנ\"ל</b>: בכת\"י ב' ליתא."],["4152","6","<b>ומל'</b>: בכת\"י ב' נוסף: אתה מחי'."],["4153","7","<b>חכמה נק' ראשית הגילוי</b>: נסמן לעיל ע' תקסח."],["4154","8","<b>למעלה מן</b>: בכת\"י ב' ליתא."],["4155","9","<b>ההסתר</b>: בכת\"י ב': הכתר."],["4156","10","<b>כנ\"ל</b>: בכת\"י ב': כו'."],["4157","11","<b>שפעו</b>: בכת\"י ב': מהותו."]]],[2100990203,"דאצי' הנמשך מז' תחתוניות ובינה דעתיק ועי\"ז והי' העולם דאצי' ושאמר ממילא משמע שאינו יודע מי הוא. ואח\"כ ברוך הוא בחי' כתר דאריך.\n<b>ברוך</b> אומר ועושה, חכמה שבכתר. ברוך גוזר ומקיים אבא דאצי', פי' אבא נקרא גוזר, לפי שאורייתא<sup data-n=\"4158\">12</sup> מחכמה נפקת, דהיינו להיות הסוכה פחות מך' אמה דווקא שהוא ע\"י השכל שמצמצם שיהי' כך דווקא, ונמשך מקו המדה המודד ומצמצם ע\"י הגבורות שיהי' האורות והכלים מתמזגים כי האור בלתי מוגבל ומצדו לא הי' הפסק, כמו יום א' חסד לא הי' נמשך ביום ב' גבורה ויהי' מבדיל וכן לא הי' חורבן בית ראשון והוא ע\"י הכלי המגביל שאמנם הכלי צריך להיות במזיגה ושיהי' הרחבת הכלי לקבל ריבוי האור כו' וז\"ש גוזר ומקיים והוא נמשך ממוחא סתמאה מקור המברר דהיינו אומר ועושה. פי' עושה מענין תקון כמו ל\"ט מלאכות הזורע וכו' ולעשות ולתקן דהיינו לברר הבירורים ולהבדיל.\n<b>ברוך</b> עושה בראשית בינה דאצי' פי' בינה<sup data-n=\"4159\">13</sup> אם הבנים להוליד את המדות ע\"י כח החכמה שבה. וזהו עושה בראשית חכמה כו' כמ\"ש בזוהר<sup data-n=\"4160\">14</sup> כולם בחכמה עשית בבינה, וגם עושה מלשון תיקון דהיינו לתקן הבירורים שנפלו מז\"ת דאימא שהם בלע יובב שצריך לתקן ולהיות נעשה מז\"ת כלי לתקון והיינו בבינה. ולכך עושה ומתקן בראשית דחכמה המברר, והיכן הוא בבינה, ששם היתה השבירה וכו'.\n<b>ותוכן</b> ענין הברכה מענין המבריך<sup data-n=\"4161\">15</sup> את הגפן שיהי' גילוי המשכת אלקות ע\"פ חסידות להיות גילוי בנפש, ועפ\"י הקבלה שיהי' גילוי למעלה מהאצי'. וע\"ז קאמר ברוך שאמר שיהי' שורש להתהוות הכתר<sup data-n=\"4162\">16</sup> ושניהם עולין בקנה אחד שכשיהי' המשכה מלמעלה יומשך ממילא בנפש. כמו למשל כשממלאין החביות הרבה נוטף המשקה אל הארץ וכו'. ברוך מרחם על הארץ ז\"א דאצי' שהוא המרחם על המלכות שבנינה מהגבורות כבוד<sup data-n=\"4163\">17</sup> מלכותך יאמרו וגבורתך ידברו כדי שיהי' התהוות נפרדים בע\"ג. אמנם כתיב הן<sup data-n=\"4164\">18</sup> שמים לא יזכו בעיניו שהשירה של מלאכים לא ישרה בעיניו כי באמת קמי' כולא כלא חשיבא, ולזאת הוא חסדים דז\"א להמתי' גבורות דנוקבא, כי ז\"א הוא רובו חסדים כו'.\n<b>ברוך</b> מרחם על הבריות מל' דאצי' כי רחמים דז\"א א\"א להשיג בנבראים לזאת הוא מתצמצם ע\"י המלכות שנעשה עתיק לבריאה מקור י\"ג מכילין דרחמי' כו'.",[["4158","12","<b>שאורייתא מחכמה נפקת</b>: זהר בשלח סב, א. יתרו פה, א. (רע\"מ) משפטים קכא, א."],["4159","13","<b>בינה אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א."],["4160","14","<b>בזוהר כולם בחכמה עשית בבינה</b>: תהלים קד, כד. וראה זהר תזריע מג, א."],["4161","15","<b>המבריך את הגפן</b>: ראה כלאים רפ\"ז."],["4162","16","<b>הכתר</b>: בכת\"י ב': רדל\"א."],["4163","17","<b>כבוד מלכותך יאמרו</b>: תהלים קמה, יא."],["4164","18","<b>הן שמים לא יזכו</b>: איוב טו, טו — ”הן שמים לא זכו\"."]]],[2100990204,"<b>ברוך</b> משלם שכר טוב ליראיו כתר דבריאה, שכר טוב גן ועדן הנמשך מכתר דבריאה כו'. וצריך ברכה להמשיך הכתר כו'.\n<b>ברוך</b> חי לעד כו' אבא דבריאה נק' חי והחכמה<sup data-n=\"4165\">19</sup> תחי', וכן מקור החיים. והענין הוא, שהוא מקור כל החיות שנמשכים ממנה לא שהוא עצמו חי כי א\"א לומר שם שהוא חי כי הוא מקור החיים וחי ולא בחיים כו' וכמו שבינה<sup data-n=\"4166\">20</sup> נקרא אלקים חיים, והיינו כי למעלה מן החכמה אין מקום וזמן שיתכן לומר שהוא מתפשט לעד ולנצח, אבל מחכמה דבריאה ואילך שיש מקום וזמן והוא מתפשט למטה היינו לעד לעדי עד וכן לנצח וקאי על מקום וזמן כו'.\n<b>ברוך</b> פודה ומציל אימא דבריאה. כי הנה מו\"ק דבריאה מתחיל הגיהנם כי יש שם היכלות כמ\"ש בזוהר<sup data-n=\"4167\">21</sup> פ' פקודי כי יש שם היכל הזכות ששם יושבין סנהדרין גדולה ושופטים העדה ומי שנגמר דינו ויצא חייב נותנים ומוסרים אותו לדומה לגיהנם. והנה כשכבר בא השפע למדות דבריאה כאשר יצא חייך אין להשיב אבל בינה דבריאה תוכל לשמרו מבלי יתפשט ויגיע השפע למדות ולכך הוא פודה וכו'<sup data-n=\"4168\">22</sup>.\n<b>ברוך</b> שמו הוא ז\"א דבריאה. ברוך אתה בבחי' גילוי הוא מל' דבריאה, משא\"כ שמו הוא נעלם כו'. ותוכן הענין לפי שע\"י פסוקי דזמרה צריך להיות עליות בכל נפשך ואלמלא הקב\"ה עוזרו כו', כי מ\"ן א\"א להיות בלי מ\"ד ע\"כ תחילה צריך להמשיך הארת י\"ג מדות וכו' כדי שיהי' אח\"כ בכל נפשך תהילה לדוד ארוממך וכו' וד\"ל.",[["4165","19","<b>והחכמה תחי'</b>: ראה קהלת ז, יב."],["4166","20","<b>שבינה נק' אלקים חיים</b>: ראה זהר יתרו סח, ב. ובהנסמן לעיל ע' תרט."],["4167","21","<b>בזוהר פ' פקודי</b>: ראה זוהר פקודי רמח, א ואילך."],["4168","22","<b>וכו'</b>: בנו\"א נוסף: כי אין הגבורות נמתקין אלא בשרשן."]]],[2100990205,"<h3>נוסח שני: ברוך שאמר והי' העולם</h3>\n<b>ביאור מאדומ\"ר שי'</b>\n<b>ברוך</b><sup data-n=\"4169\">1</sup> שאמר והיה העולם ברוך הוא<sup data-n=\"4170\">2</sup>, איתא בכוונות ברוך שאמר רדל\"א ברוך הוא גולגלתא דאריך כו'. הנה לשון הוא שייך על דבר הנסתר ונעלם ממנו שאינו מושג ונראה כמארז\"ל אתה<sup data-n=\"4171\">3</sup> הוא עד שלא נברא העולם, שבחי' אתה<sup data-n=\"4172\">4</sup> הוא בחי' גילוי לשון נוכח ובחי' הוא לשון העלם הכל דבר א' בלי תוספת ומגרעות קודם שנברא ואחר שיתא אלפי שני' והיינו לפי שכל התהוות העולמות וקיומם מאין ליש ממש הוא בחי' זיו והארה בעלמא. וביאור הענין באר הטיב צ\"ל תחילה מ\"ש בע\"ח ע\"ס<sup data-n=\"4173\">5</sup> בלי מה בלי מהות וכמ\"ש בזוהר<sup data-n=\"4174\">6</sup> לאו דאית לך ידיעה כו', וא\"כ איך יתכן בהם המספר עשר ולא ט' כו'.\n<b>גם</b> להבין בחי' היחוד וההתכללות מ\"ש לך<sup data-n=\"4175\">7</sup> הוי' הגדולה והגבורה כו' שהם מתאחדים עמו ית' בבחי' לך ממש ואשר ע\"כ נק' גדולה כו' בתוס' ה' להורות שהן בבחי' ירידה גדולה לפניו ית' להיות נק' בשם גדולה, ואעפי\"כ הם מתאחדים עמו ית' ביחוד גמור ואיך אפשר הריבוי וההתחלקות בחי' עשר להתאחד ולהתכלל עמו ית', והנה דרך כלל התירוץ מבואר בספרים שהריבוי וההתחלקות הוא בבחי' הכלים ובחי' היחוד וההתכללות הוא בבחי' האורות דלאו מכל מדות כלל.\n<b>ולהבין</b> כ\"ז באר היטיב בתוס' ביאור יובן ע\"פ מ\"ש בע\"ח<sup data-n=\"4176\">8</sup> בענין עקודים ונקודים, שעקודים הוא בחי' עשר אורות עקוד בכלי אחד כו', ונקודים הוא עשר אורות בעשר כלים מחולקים כו'. והנה ענין אור וכלי יובן ע\"פ משל בנפש האדם ומבשרי<sup data-n=\"4177\">9</sup> אחזה שיש בנפש ג' בחי' שכל הגילוי שהוא טעם והסברה וההשכלה, ולמעלה מן השכל שמשם נובע השכל בטוב טעם ודעת שהוא ההארה והמשכה מעצם הנפש ובחי' יחידה שבנפש שהוא עצם הנפש שכלול מעשר כוחות וגנוזות בה בהעלם, דהנה השכל שהוא גילוי שכל להשכיל כל דבר בטוב טעם ודעת שורה ומתלבש במוח גשמי שהוא כלי ומכון לבחי' השכל, והיינו לפי שהמוח הוא חומר לצורה זו כמו שהעין הוא חומר לצורה לכח הראי' רוחני, והיינו לפי שהעין היא עצם ספירה לכך נעשה כלי לבחי' כח הראי' הרוחני, ויש בזה ב' בחי' הא' שנשתנה כח הראי' רוחני שבנפש בהתלבשות בחומר העין להיות רואה דבר גשמי כו', והב'",[["4169","1","<b>ברוך שאמר והיה העולם</b>: נעתק מכת\"י 2068 א, ד. נוסח אחר מד\"ה ברוך שאמר בקיצור שנדפס לעיל ע' תקפב."],["4170","2","<b>ברוך שאמר והיה העולם ברוך הוא</b>: נוסח תפלת פסוד\"ז."],["4171","3","<b>אתה הוא עד שלא נברא העולם</b>: פדר\"א פ\"ג."],["4172","4","<b>אתה. . גילוי. . נוכח</b>: ראה תו\"א בראשית ב, א. ויחי מה, ג. בשלח סב, ב. ועוד."],["4173","5","<b>ע\"ס בלי מה</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."],["4174","6","<b>בזוהר לאו דאית לך ידיעה</b>: ת\"ז בהקדמה (יז, א)."],["4175","7","<b>לך ה' הגדולה</b>: דברי הימים-א כט, יא."],["4176","8","<b>בע\"ח בענין עקודים ונקודים</b>: ראה ע\"ח שער (יא) המלכים פ\"א. שער (ו) העקודים פ\"א. שער (ז) מטי ולא מטי פ\"א.\nוראה תו\"א נח י, ג. לקו\"ת קרח נג, ג. תו\"ח נח סה, ד. ועוד."],["4177","9","<b>ומבשרי אחזה</b>: לשון הכתוב איוב יט, כו."]]],[2100990206,"שבחי' כח הראי' שבנפש אינה בבחי' גבול ומדה ובהתלבשות תוך העין גשמי נגבל בגבול ושיעור ומדה שעד ס' מילין שולט כח הראי' שבעין ולא יותר, וכך הוא בענין השכל שע\"י התלבשות תוך המוח גשמי משתנה מהותו מכמו שהי' וגם נגבל בגבול ושיעור לעומק חכמתו עד פה תבוא כו', וכמ\"כ התלבשות המדות בלב הוא ג\"כ משתנה בכל בחי' הנ\"ל, וכמ\"ש בזוהר<sup data-n=\"4178\">10</sup> תלת שליטין אינון מוחא ליבא כו' לג' בחי' נר\"ן שכל במוח ומדות בלב כו', ולכן משתנה השכל לפי מזיגת הכלי מוח גשמי לפי מה שהוא לח או יבש שמי שמזיגת מוחו לח הוא בעל הבנה כו'.\n<b>וכמו\"כ</b> יובן ג\"כ למעלה התלבשות אורות בכלים הוא ג\"כ בב' בחי' הנ\"ל שמשתנה האור מכמו שהי' קודם התלבשותו בכלים ונעשה ג\"כ בבחי' גבול וקצבה ומדה, ואפי' באורות וכלים דאצי' איהו וחיוהי חד מ\"מ הרי הן בבחי' גבול וקצבה ומספר עשר ולא ט' כנ\"ל, ובחי' משכיל הוא מקור השכל להיותו נובע לו ההשכלה ושכל הגלוי בטוב טעם ודעת שהוא כח רוחני והיולי ואינו נק' עדיין בשם שכל אלא שהוא כח רוחני שמשם נובע השכל להשכיל ולהבין ואינו מלובש בכלי מוח גשמי ולכן הוא בלי גבול שם שבכוחו להשכיל כל מיני ההשכלות בכל החכמות משא\"כ שכל הגלוי יש גבול בחכמה זו או באחרת, שכשמעמיק דעתו בחכמת התכונה אין שכלו בגילוי בחכמת התישבורת אבל בכח החכמה כוללם כולם יחד, אך הנה גם בבחי' משכיל הנ\"ל יש שינוים כי עת להשכיל השכלות חדשות ולפרקים ועיתים מזומנים אף אם יעמיק דעתו ותבונתו לא יוליד מבינתו שום השכלה, וכן יש אנשים חכמים מחוכמים בהשכלות בחכמה א' כמו בחכמה התישבורת ולא בחכמה התכונה וכדומה, וא\"כ מוכרח שאין בכח חכמתו בחי' משכיל להשכיל לחכמה זו, וגם שאנו רואים בחוש שבעת שכלי מוח הגשמי זך ונקי מאידים אזי עת להשכיל משא\"כ בעת אחרת, א\"כ מוכרח לומר שגם בחי' משכיל הוא בבחי' אור וכלי, אלא שאינו בבחי' התלבשות ממש כמו השכל הגלוי ונק' בשם אור כמו האור שמאיר בריחוק מקום שאינו בבחי' התלבשות ממש, וע\"י ההארה ההיא נולד ומתהווה ההשכלה להיות בגילוי השכל בטוב טעם ודעת, ובחי' משכיל הנ\"ל הוא בחי' רצון שבנפש וכמארז\"ל<sup data-n=\"4179\">11</sup> ע\"פ והשוחד יעוור כו' אי בעי טעין הכי כו', שע\"י השוחד שהוא ענין הטיית הרצון ממציא לו שכל חדש בטוב טעם לזכות, ועצם בחי' משכיל הוא מבחי' עשר כוחות שבנפש שהן בחי' עשר כתרים כתר שבחסד כו', ולכן אין בו שום שינוי שאם עצם חומר המוח זך ונקי מאידים גשמי' אזי מאיר ונמשך מבחי' עצם הנפש להשכיל השכלות, ובעת אחר תעדר ההמשכה ונשאר בחי' משכיל במקורו עצם הנפש ואינו בא לידי גילוי והוא בחי' התלבשות העלם בלתי גילוי וכמשל תלמיד המקבל שכל הרב שבעת קבלתו איידי<sup data-n=\"4180\">12</sup> דטריד לא פליט, שבחי' ההשפעה וההסבר שיש בכח שכל התלמיד הוא בבחי' העלם והסתר תוך<sup data-n=\"4181\">13</sup>",[["4178","10","<b>בזוהר תלת שליטין אינון</b>: זח\"ב קנג, א."],["4179","11","<b>וכמארז\"ל ע\"פ והשוחד יעוור כו' אי בעי טעין הכי</b>: ראה כתובות קה, ב."],["4180","12","<b>איידי דטריד לא פליט</b>: ראה חולין קח, ב. תו\"ח נח סג, ג הערה 44."],["4181","13","<b>תוך אותו</b>: בהכת\"י יש תיבה אחת שאינה ברורה, בין התיבות ”תוך אותם\"."]]],[2100990207,"אותו פעם התלבשות העלם כמארז\"ל די<sup data-n=\"4182\">14</sup> לחכימה ברמיזא ששכל גדול ועמוק שא\"א להביניהו לזולתו בדיבור מרמזו ברמיזא ביד לפי אופן וסדר השכל, שהלבשת השכל ביד הוא בחי' העלם שאינו בא לידי גילוי כלל שהרי גילוי כח היד הוא כח התנועה ולא שכל ויותר מבחי' הגלגולים גלגול נפש האדם בבהמה או בדומם שהנפש עם כל כוחותיה מגולגלת בהם והרי אין בבהמה או בדומם כח הדיבור וכח השכל שהכוחות ההם הם בהעלם תוך הבהמה והדומם העלם בלתי גילוי, ועפ\"י הנ\"ל יובן ענין בחי' משכיל הנ\"ל שאין בו שום שינוי כלל אם יהי' ממנו בחי' התפשטות להשכיל שכל גילוי בטוב טעם או שתיעדר ההשכלה ונשאר בחי' משכיל קשור בעצם הנפש עצמה, העלם בלתי גילוי שאינו מאיר בבחי' הכלים.\n<b>והיוצא</b> לנו מזה שיש בנפש ג' בחי', הא' הוא בחי' השכל הגלוי שהוא ענין התלבשות אורות בכלים, והב' הוא בחי' משכיל מקור השכל כח היולי, וכמ\"כ יש מקור ושורש לכל המדות חסד כו', שהן ג\"כ בבחי' אור המאיר בבחי' הכלים והאור הוא שורש הגילוי וממנו נסתעף והוא בבחי' המשכה מעצם הנפש עשר אורות בעשר כלים, והבחי' הג' הוא עצם הנפש עצמה שאינו מאיר בבחי' כלי כלל והעשר כוחות שבנפש כלולים ומיוחדים בה בתכלית היחוד ועקוד בכלי א' הוא בחי' יחידה שבנפש. והנה בחי' משכיל נק' הוא נודע מציאותו ולא מהותו, שע\"י שרואה גילוי השכל בגילוי טוב טעם ודעת יודע שיש בחי' משכיל מקור השכל ומשם נובע כמו שיודע מציאות נפשו וחיותו שע\"י שרואה שהוא חי יודע שיש מציאות הנפש הגם שלא ראה את מהות הנפש מעולם אך ע\"י פעולותיו נודע לו בבירור מציאות הנפש, וכך בחי' המשכיל ע\"י פעולותיו שבא לידי גילוי בשכל בטוב טעם נודע מציאותו, משא\"כ עצם שהן עשר כוחות הגנוזות בה גם מציאותן לא נודע מאחר שאינן באים לידי גילוי כלל.\n<b>ועפ\"י</b> הנ\"ל יובן ג\"כ למשכיל למעלה ג' בחי' אלו, שבחי' חכים ולא בחכמה ידיעא מבין כו' הוא בחי' התלבשות אורות בכלים שמשתנים בב' בחי' הנ\"ל להיות משתנה טעמו מכמו שהי' קודם התלבשותו וגם שנעשה בגבול ושיעור ומדה, ושרשן ומקורן של כל הע\"ס הוא בחי' ארי\"ך בחי' כתר של כל הספירות, כתר שבחכמה, כתר שבחסד כו', שהוא בבחי' אור המאיר תוך הכלים, וההארה ההיא היא השורש ומקור לכל הע\"ס שבחי' ארי\"ך נק' הוא, שנודע מציאותו ולא מהותו ע\"י פעולותיו והתפשטות להאיר תוך כלי הע\"ס, ושורש בחי' הכתר הוא מבחי' הע\"ס הגנוזות במאציל בהעלם. נמצא מובן ממילא למשכיל שבבחי' אורות לאו מכל מדות כלל, כי האורות הן בחי' הכתרים בחי' ע\"ס דאריך המאירי' בריחוק מקום תוך הספירות ושרשן הן בחי' ע\"ס הגנוזות שאין בהם שום שינוי קודם שנברא כו', והם כלולים ומיוחדים בתכלית היחוד במאצילן ובחי' ההתחלקות והפירוד להיות נק' בשם ע\"ס הוא בכלים היינו ההארה המאירה תוך הכלים שמהמאור נתהווה בחי' התלבשות",[["4182","14","<b>די לחכימא לרמיזא</b>: ראה רשב\"ם בראשית כג, טז. מדרש משלי כב, טז. זח\"א כו, ב."]]],[2100990208,"אורות בכלים ממש ששם הוא בחי' התחלקות ממש אבל בעצם האור אין בו שום שינוי כי בהעדר התפשטות ההארה ההיא הנה נשאר בבחי' עצם האור בבחי' ע\"ס הגנוזות במאצילן בהעלם שאינו בא לידי גילוי כלל ועקוד בכלי אחד, ובחי' נקודים עשר אורות בעשר כלים הוא בחי' הארת בחי' הכתר המאיר בע\"ס כנ\"ל.\n<b>וזהו</b> אתה הוא, אתה הוא בחי' הגילוי בחי' התלבשות אורות בכלים ממש שהוא בחי' ע\"ס דאצי', אתה אבינו, הוא בחי' חכמה דאצי' אבא שורש כל האצי', אתה<sup data-n=\"4183\">15</sup> כהן לעולם, הוא בחי' חסד דזעיר שהוא שורש גילוי בחי' ז\"א דאצי', ואתה מחי' את כולם הוא בחי' מל' דאצי', וכל בחי' אתה בחי' גילוי, הוא בחי' הוא נודע מציאותו ולא מהותו שהוא בחי' כת\"ר וארי\"ך, שהוא בחי' האור המאיר בכל ע\"ס שאין בהם שום שינוי והתחלקות והם כלולים ומיוחדים בתכלית היחוד כי הן הן עצמן בחי' ע\"ס הגנוזות במאצילן שאין בהם שום שינוי קודם שנברא כו', כמ\"ש אני<sup data-n=\"4184\">16</sup> הוי' לא שניתי היינו בבחי' האורות כמ\"ש בע\"ח<sup data-n=\"4185\">17</sup> כשעלה ברצונו דמשמע שינוי רצון היינו בכלים כנ\"ל.\n<b>וטעם</b> קריאת השם בלשון כלים וגם להבין מ\"ש בע\"ח<sup data-n=\"4186\">18</sup> למ\"ד כלים דז\"א דאצי' מתלבשים בבי\"ע פנימיות הכלים בבריאה אמצעים ביצירה וחיצוניות בעשי', יובן ע\"פ משל כלי גשמי שפעולת הכלי היא בב' בחי' כמו כלי השואב מים מן הנהר או עשיית בריכה להיות מים נקוים שם שפנימיות הכלי פעולתה להגביל בתוכו המים שיהיו במדה ובמשורה ולא כמו שהם בנהר בלי שיעור, שזהו פעולת פנימיות הכלי כי המים נקוים ועומדים בפנימיות הכלי, והב' הוא בחי' ההמשכה שיוכל המים להמשיך אליו ולהוליכו אנא ואנא או כמו המשכת צינור מן הבריכה להוליך המים למקום שירצה שזהו פעולת חיצוניות הכלי, כי המים שבנהר א\"א להמשיך כ\"א ע\"י לקיחה דבר אחר שהלקיחה והאחיזה היא בחיצוניות הכלי, ולכן כל בחי' המשכה והשתלשלות נק' בשם כלי שהוא בחי' חיצוניות הכלי כי פנימיות הכלי הוא רק להכיל ולקבל בתוכו ולא להמשיך.\n<b>ויובן</b> יותר ע\"פ משל האותיות כי הנה כל השפעה והמשכה נק' בשם אותיות כי הנה האותיות יש בהן ג\"כ ב' בחי' הנ\"ל בחי' פנימיות וחיצוניות שהן עצם שחרות האות ולבנונית הגויל שבתוכו שהוא ג\"כ לפי ציור האות, שפעולת פנימיות האות הוא להכיל ולקבל בתוכו השכל הגנוז בהאותיות כמו דבר תוספת שבאותיות ההם מלובש וגנוז השכל ומכוון התוספת, וחיצוניות האותיות הוא כדי להיות בחי' המשכה בכדי שע\"י האותיות אלו יוכל אחר הלומד ומעמיק דעתו להבין השכל על בוריו שהוא בחי' המשכה והשפעה ע\"י בחי' האותיות דווקא, וכמו השפעת שכל הרב",[["4183","15","<b>אתה כהן לעולם. . חסד. . ז\"א דאצילות</b>: תהלים קי, ד. וראה ג\"כ פירוש המלות (לאדה\"א) ס, א — ואיתא בזוהר."],["4184","16","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["4185","17","<b>בע\"ח כשעלה ברצונו</b>: ראה ע\"ח ש\"א ענף ב."],["4186","18","<b>בע\"ח למ\"ד כלים דז\"א</b>: ראה ע\"ח שער (מד) השמות. ראה קו\"א לתניא (להבין מ\"ש בפרע\"ח) קנו, רע\"ב. אמרי בינה שער הק\"ש לד, ב."]]],[2100990209,"שהוא ע\"י אותיות דבור, ולכן כל השפעה והמשכה והשתלשלות נק' בשם אותיות וכלים, וזהו ענין בין מלאכים לנשמות ששניהם הם מבחי' אותיות, אלא לפי שהמלאכים הן מבחי' חיצוניות שהוא בחי' המשכה לכן המלאכים הם שלוחי השפעה שכל השפעה והמשכה והשתלשלות הוא מבחי' חיצוניות, אבל הנשמות הם מפנימיות האותיות ולכן הם בחי' כלי קיבול להכיל בתוכן אור א\"ס ולא בבחי' ההשפעה והמשכה רק בחי' כלי קיבול. ועפ\"י הנ\"ל יובן ג\"כ ענין מ\"ש בע\"ח למ\"ד כלים דאצי' מתלבשים בבי\"ע שלהיות נמשך מבחי' חכמה דאצי' חכים ולא בחכמה ידיעא כו', בחי' החכמה ושכל טפה זו מה תהא חכם או טפש כו', הנה המשכה והשתלשלות זו היא מבחי' כלים כו', שמבחי' כלים חכמה דאצי' נתהווה בבריאה חכמת שלמה וביצירה חכמה דיצירה ובעשי' חכמה דעשי' עד שמגלגלים שהם מל' דמל' דעשי' נתהווה שכל אנושי חכם או טפש כו'.\n<b>והעולה</b> מכל הנ\"ל שיש ג' בחי' אורות שבחי' ע\"ס דאצי' בחי' התלבשות בכלים ממש הן בבחי' גבול ובחי' כתר<sup data-n=\"4187\">19</sup> הממוצע בין מאציל לנאצלים הוא אור המאיר בריחוק מקום תוך כלי הספירה שהוא בחי' עשר כתרים שהן שורש ומקור האור המלובש ונגלה ושרשן ומקורן הן בחי' ע\"ס הגנוזות במאציל שהן בבחי' עצמיות דלא ידע לי' בר איהו, משא\"כ בחי' אריך נק' הוא העלם שבא לידי גילוי ע\"י ההארה שמאיר בע\"ס דאצי' כנ\"ל, אבל בחי' עתיק אינו בא לידי גילוי כלל כו', הנה גם בחי' עתיק הגם שע\"ס הן גנוזות ונעלמות מ\"מ שהן בבחי' עשר ולא ט' ולא י\"א הרי הן בבחי' ידיעא ונק' אתיידע אלא שלגבי ע\"ס דאצי' הוא בחי' גילוי ממש נק' לא אתיידע אבל לגבי בחי' ארי\"ך הרי חסד דעתיק מתלבש בגולגלתא וגבורה במו\"ס הרי הוא בבחי' אתיידע, ויש בחי' גבוה מזו ע\"ס הכללות שהוא בחי' ג\"ר דעתיק שהוא בחי' מל' דא\"ס ששם אין שום התחלקות כלל להיות בחי' עשר כו'.\n<b>וזהו</b> ב\"ש באמירה א' הוא בחי' ג\"ר דעתיק, והי' העולם הוא בחי' ז\"ת דעתיק שהן בחי' העלם שאינו בא לידי גילוי כלל, דלא ידע לי' בר איהו, ברוך הוא גולגלתא דאריך כתר שבכתר שנק' הוא שנודע מציאותו ע\"י פעולותיו להיות בבחי' אור המאיר בע\"ס דאצי', ברוך אומר ועושה חו\"ב דאצי' אומר ועושה אבא אמר לאימא בחי' גילוי האצי' וה\"ז דוגמת ומשל ג' בחי' שבנפש כנ\"ל.",[["4187","19","<b>כתר הממוצע</b>: ע\"ח שער דרושי אבי\"ע (שמ\"ב) פ\"א. וראה לקו\"ת בחוקותי מו, ג. שלח מט, ג."]]],[2100990210,"<h3>החלצו מאתכם</h3>\n<b></b><b>בעזר\"ה שבת פ' מטות מסעי</b>\nשבת פ' מטות מסעי\n<b>החלצו</b><sup data-n=\"4188\">1</sup> מאתכם אנשים לצבא ויהיו על מדין לתת נקמת הוי' במדין. אלף למטה לכל מטות ישראל<sup data-n=\"4189\">2</sup> כו'. הנה מה שיש לדקדק בזה ולהבין הם שני דברים הא' מהו לתת נקמת הוי' במדין מה ענין מלחמה<sup data-n=\"4190\">3</sup> זו להיו' נקמת שם הוי' דוקא, והב' מהו לכל מטות מכל מטות מיבעי' לי' מאחר שאמר החלצו מאתכם דאם הי' מתחיל בלשון זה יחלצו מאתם הי' נכון לסיים בלשון זה לכל מטות אבל אחר שאמר החלצו מאתכם הל\"ל מכל מטות ולא לכל מטות כידוע למדקדקי'.\n<b>אך</b> הנה קודם מ\"ת כבר היה קצת ענין הכנעת קליפת מדין בכלל במה שהלך יתרו כהן מדין לקראת משה והכניע א\"ע ואמר עתה<sup data-n=\"4191\">4</sup> ידעתי כו' וכמ\"ש וישמע<sup data-n=\"4192\">5</sup> יתרו כהן מדין וכו' ואיתא בזוהר<sup data-n=\"4193\">6</sup> שהי' בחי' מלך וכהן דסט\"א ונק' כהן און כו' ע\"ש אך לבסוף ציוה ה' לגמור לגמרי הכנעת קליפת מדין במלחמה ממש כדי לתת נקמת הוי' במדין כו'.\n<b>ולהבין</b> זה הנה יש להקדים מה שאמרו ז\"ל דבשעת<sup data-n=\"4194\">7</sup> מ\"ת נתקבצו כל האומות וכו' עד שפתחו כולם ואמרו ה' עוז לעמו יתן ה' יברך את עמו בשלום כי הנה התורה היא בחי' שלום וכמ\"ש ורב<sup data-n=\"4195\">8</sup> שלום בנייך א\"ת בנייך אלא בונייך אלו ת\"ח כו' וגם אמרו ז\"ל כל<sup data-n=\"4196\">9</sup> העוסק בתורה לשמה משים שלום בפמליא של מעלה ובפמליא של מטה שנא' או<sup data-n=\"4197\">10</sup> יחזק במעוזי יעשה שלום לי שלום יעשה לי כו'.",[["4188","1","<b>החלצו מאתכם</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכי\"ק 1025 (עט, ב).\nנדפס בשינויים ותוס' הגהות בלקו\"ת מטות פה, ב.\nמאמר זה באריכות מכ\"ק אדמו\"ר האמצעי נדפס במאמרי אדה\"א במדבר ח\"ה ע' א'תשלט. הנחות תקע\"ז ע' רכד ואילך. וראה בהנסמן שם. הגהות על מאמר זה מכ\"ק אדמו\"ר הצ\"צ באוה\"ת מטות [הוצאת תש\"ס] ע' 48. וראה ד\"ה וידבר גו' החלצו בסה\"מ תרנ\"ט ע' נג — שמיוסד על מאמר זה.\nנוסח אחר (הנחת המהרי\"ל) נדפס לקמן ע' תרי. ומתחיל: לתת נקמת הוי' במדין.\nוראה היום יום כ\"ח תמוז: ”לכל אחד מהרביים היו מאמרים קבועים ביחוד בשביל זה (לטהר אויר העולם) אשר פעם בשתים או בשלש שנים היו חוזרים עליהם ברבים, אחד ממאמרי רבינו הזקן — החלצו שבלקו\"ת בלי ההגהות."],["4189","2","<b>החלצו מאתכם אנשים לצבא אלף למטה. . מטות ישראל</b>: מטות לא, ג, ד."],["4190","3","<b>מלחמה. . . נקמת שם הוי' דוקא</b>: בסה\"מ תרנ\"ט שם הערת כ\"ק אדמו\"ר בשולי העמוד שם מציין: ראה רמב\"ן מטות לא, כג. בחיי. ועוד. ועפ\"ז דמלחמת מדין לא הייתה בכדי לרשת את ארצם, סרה ג\"כ השגת הראב\"ד על הרמב\"ם סוף הל' שמיטה ויובל ודלא כהכס\"מ. ואכ\"מ. ע\"כ."],["4191","4","<b>עתה ידעתי</b>: יתרו יח, יא."],["4192","5","<b>וישמע יתרו כהן מדין</b>: שם יח, א."],["4193","6","<b>בזוהר שהי' בחי' מלך</b>: ראה זהר יתרו סז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' ש. וע' שם סח, א."],["4194","7","<b>דבשעת מ\"ת נתקבצו כל האומות. . . ה' עוז לעמו יתן</b>: ראה ספרי דברים לג, ב ועוד. תהלים כט, יא."],["4195","8","<b>ורב שלום בנייך א\"ת בנייך</b>: ישעי' נד, יג. ברכות סד, א."],["4196","9","<b>כל העוסק בתורה לשמה</b>: ראה סנהדרין צט, ב."],["4197","10","<b>או יחזק במעוזי</b>: ישעי' כז, ה."]]],[2100990211,"<b>ולהבין</b> ב' שלומות הללו ולמה תלויי' בעוסק בתורה לשמה דוקא הנה תחלה צריך להבין מה שחורבן בהמ\"ק היה בשביל<sup data-n=\"4198\">11</sup> ג' עבירו' חמורו' ע\"ז ג\"ע וש\"ד וחורבן<sup data-n=\"4199\">12</sup> בית שני הי' רק בשביל עון שנאת חנם בלבד כידוע בדברי רז\"ל ולמה<sup data-n=\"4200\">13</sup> גלות בבל הי' רק ע' שנה וגלות בית שני הזה ארוך כ\"כ יותר מי\"ז<sup data-n=\"4201\">14</sup> מאו' שנה כו', אך הענין הוא כי הנה בתחלת בואם לארץ נצטוו להכרית ז' אומות בלבד והן הכנעני וכו' כמ\"ש שבעה<sup data-n=\"4202\">15</sup> גוים רבים ועצומי' כו' ונא' בהם לא<sup data-n=\"4203\">16</sup> תחיה כל נשמה והטעם הוא לפי ששרש יניקו' ז'<sup data-n=\"4204\">17</sup> אומו' הללו נמשך מבחי' פסולת ז' מדות הרעו' דקליפה דאת זלע\"ז עשה האלקי' וכמו שיש בקדושה ז' מדו' דקדושה כמ\"ש לך<sup data-n=\"4205\">18</sup> ה' הגדולה והגבורה כו' כך יש בסט\"א דקליפה ז' מדו' רעות והיינו שאנו אומרי' וכרות<sup data-n=\"4206\">19</sup> עמו הברית לתת את ארץ הכנעני כו' דהיינו לכבוש ז' המדו' רעו' ולאתהפכא<sup data-n=\"4207\">20</sup> &lt;רפו&gt;\nחשוכא לנהורא כו' מן הקצה לקצה שלא ישאר אפי' שמץ מיני' ולא לאכפייא בלבד כו' וע\"כ נצטוו להכרית ז' אומו' הללו לגמרי ונא' להם לא תחיה כל נשמה כי אסור להניח להם אפי' שמץ יניק' ושרש למטה אך כשבאו לארץ לא זכו בכיבוש הארץ לכבוש ז' מדו' הרעו' לגמרי לכך נא' להם ואשר<sup data-n=\"4208\">21</sup> תותירו מהם לשכים בעיניכם ולצנינים בצדיכם כלומר שנשארו שמץ מן הרע ויוכלו לפעמים להתגבר וליקח תוספת יניק' מהקדוש' עד שיהיו לשכים ולצנינים כו' וצררו אתכם כו' ועדיין היו כפופים תחת הקדוש' אך כשחטאו ישראל נתגברו ז' אומו' בבחי' שרשם בז' מדו' דקליפ' למעלה מפני תגבורת הקליפה למטה בז' מדו' הרעות כמו התאוה והכעס שהן בחי' חו\"ג והתפארות הוא הת\"ת וכיוצא וכידוע ולכך הי' חורבן בית ראשון ע' שנה בלבד הגם שהי' בעבור עבירו' חמורו' כע\"ז וג\"ע כו' כי בע' שנה בגלות נתבררו ז' מדו' הרעות כולם כי כל מדה כלולה מי' כידוע וד\"ל.",[["4198","11","<b>בשביל ג' עבירות. . . שנאת חנם</b>: יומא ט, ב. בית ראשון מפני מה חרב כו' ע\"א וג\"ע וש\"ד. ובפתיחתא דאיכ\"ר פיסקא ב: שויתר הקב\"ה על ע\"ז ועל ג\"ע ועל שפ\"ד כו' על מה אבדה הארץ. ועד\"ז הוא בירושלמי חגיגה פ\"א, ה\"ז. אמנם בכ\"מ מובא הלשון: גזל ועריות וש\"ד. ראה סה\"מ תקס\"ה ע' קכח. תקס\"ז ע' שיד. תקס\"ט ע' רל. ס' מאמרי אדה\"א: בראשית ע' שמה. דברים ח\"א ע' קטו. ובעוד מקומות. ראה אגרת הקדש סו\"ס לא. שער האמונה בהקדמה ו, ב ואילך. תורת חיים נח סד, ב."],["4199","12","<b>וחורבן בית שני. . . שנאת חנם</b>: ראה הערת כ\"ק אדמו\"ר בסה\"מ תרנ\"ט ע' סז בד\"ה וכידוע."],["4200","13","<b>ולמה גלות בבל</b>: ראה מגילה יא, ב ואילך."],["4201","14","<b>מי\"ז מאות שנה</b>: ראה מאמרי אדה\"א הנחות תקע\"ז ע' רכד, ושם ע' קי. מאמרי אדה\"ז הקצרים ע' קיז. תקס\"ה ח\"א ע' קו. תו\"א וישב כז, ד. לקו\"ת מטות פב, ד. מאמרי אדה\"א במדבר ח\"ה ע' א'תשמא [עד ח\"י מאות שנה] וע' א'תתיד [ביותר מכ\"ד וכ\"ה פעמים. . . ע' שנה] נביאים וכתובים ע' צג."],["4202","15","<b>שבעה גוים רבים ועצומים</b>: דברים ז, א."],["4203","16","<b>לא תחיה כל נשמה</b>: פ' שופטים כ, טז."],["4204","17","<b>ז' אומות. . . ז' מדות הרעו' דקליפה</b>: ראה גם סה\"מ תקס\"ב ח\"א ע' קסח. תקס\"ה ח\"א ע' תיד. ס' מאמרי אדה\"א דברים ח\"א ע' ג' ואילך. לקוטי שיחות חכ\"א ע' 229 והערה 39 שם. סידור עם דא\"ח דף קפט, ב."],["4205","18","<b>לך ה' הגדולה</b>: דברי הימים א כט, יא."],["4206","19","<b>וכרות עמו הברית</b>: נחמי' ט, ח."],["4207","20","<b>ולאתהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["4208","21","<b>ואשר תותירו מהם</b>: מסעי לג, נה."]]],[2100990212,"<b>אבל</b> בזמן בית שני לא הי' החטא כלל בז' מדות הרעות דקליפה אלא בקליפת מדין שאינה נחשבת בכלל ז' קליפו' הכנעני והחתי כו' וענין זאת הקליפה אינה ענין מדה רעה מצד עצם כמו התאוה והכעס כו' אלא בחי' הרע שבה הוא ענין שנאת<sup data-n=\"4209\">22</sup> חנם בלבד שהוא רק בחי' הפירוד היפך האחדות דהנה בקדושה העליונה הוא דוקא בבחי' האחדו' כמ\"ש ה'<sup data-n=\"4210\">23</sup> אחד ושמו אחד וכמאמר הידוע דאיהו<sup data-n=\"4211\">24</sup> וחיוהי חד וגרמוהי חד כו' כי הוא<sup data-n=\"4212\">25</sup> המדע והוא הידוע וכו' וכל הספי' והמדו' כלולי' בעצמו' המאציל בתכלית היחוד כידוע וקליפה זו דמדין באת זלע\"ז הוא להיפך בחי' האחדות והיחוד שבקדושה אלא רק להפריד בין הדביקי' להיו' בבחי' פירוד והבדלה זה בפ\"ע וזה בפ\"ע כו' וע\"כ הי' עון בית שני בשנאת חנם גדול מעון בית ראשון עד שנתארך הגלות כ\"כ יותר מכ\"ד פעמי' ע' שנה כו'.\n<b>ויש</b> להבין למה יגדל עון בחי' הפירוד כ\"כ יותר מע\"ז וג\"ע וכו' אך תחלה יש להבין ענין בחי' האחדו' דקדושה דהנה ידוע דכללות כל ההשתלשלו' דד'<sup data-n=\"4213\">26</sup> העולמו' אבי\"ע הוא רק בשם הוי' או' יו\"ד אצי' ה\"א בריא' כו' ודרך פרט בחי' שם הוי' יש בכל עולם ועולם וענין ד' אותיו' הללו ידוע שהיו\"ד<sup data-n=\"4214\">27</sup> הוא בחי' הצמצום כי אינו אלא בחי' נקודא אחת שמורה על בחי' הצמצום והטעם הוא כי אור א\"ס בעצמו הוא אור פשוט בתכלית כו' ועד שיבא לבחי' גילוי אור צריך שיהי' כמה צמצומי' בתחלה להסתיר ולהעלים עצמות האור בצמצום והעלם אחר העלם כו' ונק' צמצומי' והעלמות הללו בשם חושך כמ\"ש ישת<sup data-n=\"4215\">28</sup> חושך סתרו וכתיב מגלה<sup data-n=\"4216\">29</sup> עמוקו' מני חושך כו' ואחר כל ההעלם הזה כשנתגלה אינו מתגלה רק כמו בחי' נקודה בעלמא והוא היו\"ד וכמ\"ש ויצא<sup data-n=\"4217\">30</sup> כברק חצו עד\"מ הברק שמבריק הארה בעלמא מתוך ההעלם כו' ואחר בחי' היו\"ד הזה נמשך האור ובא בבחי' ה\"א שהוא ענין המורה על בחי' ההתפשטות לאורך ורוחב דהיינו להיו' מתגלה ממש בעולמות עד שנק' בשם ממלא כ\"ע וסובב כ\"ע וכיוצא וד\"ל.\n<b>והנה</b> בחי' היו\"ד שהוא הצמצום עם הה\"א שהוא בחי' ההתפשטו' גילוי אור הרי המה ב' הפכים ממש וצריך שיהיה בחי' ממוצע שיחבר ב' הפכים הללו בשם הוי' להיו' יו\"ד בתחלה ואח\"כ ה\"א ושניהם כאחד יאירו בתחלה בחי' הצמצום &lt;רפז&gt;\nואח\"כ מן הצמצום יבא לבחי' ההתפשטות כו' ולכאורה יפלא האיך יהי' בכח הממוצע לחבר הצמצום וההתפשטו' יחד כו' אך הענין הוא דכתיב גם<sup data-n=\"4218\">31</sup> חושך לא יחשיך ממך כו'",[["4209","22","<b>שנאת חנם. . . היפך האחדות</b>: ראה זהר ויקרא טז, ב."],["4210","23","<b>ה' אחד ושמו אחד</b>: זכרי' יד, ט."],["4211","24","<b>דאיהו וחיוהי חד</b>: ראה תיקוני זהר בהקדמה ג, ד."],["4212","25","<b>הוא המדע והוא הידוע</b>: רמב\"ם הל' יסודי התורה פ\"ב, ה\"י."],["4213","26","<b>דד' העולמות אבי\"ע</b>: ראה תקוני זהר תיקון ו' (כג, א). תיקון ל\"ח (מא, א). ע\"ח ש\"ג פ\"א. שמ\"ב פי\"ג. שמ\"ז פ\"ג. ועוד."],["4214","27","<b>שהיו\"ד. . . צמצום</b>: ראה אגרת התשובה פ\"ד."],["4215","28","<b>ישת חושך סתרו</b>: תהלים יח, יב."],["4216","29","<b>מגלה עמוקות מני חושך</b>: איוב יב, כב."],["4217","30","<b>ויצא כברק חצו</b>: זכרי' ט, יד."],["4218","31","<b>גם חושך לא יחשיך ממך</b>: תהלים קלט, יב."]]],[2100990213,"כחשכה כאורה כו' פי' גם בחי' החושך שהוא בחי' ההעלם והצמצום הראשון כמ\"ש ישת חושך סתרו וכנ\"ל לא יחשיך ממך כו' משום דקמיה ממש כחשיכה כאורה ממש בהשווא' אחת.\n<b>וביאור</b> טעם הדברים ידוע דמה שנא' ישת חושך סתרו כו' היינו דוקא כשבא לכלל בחי' השפעה מלמעלה למטה שא\"א אם לא שיצמצם א\"ע בתחלה כו' ואז נק' חושך לגבי העולמו' ואח\"כ יאיר להם בצמצום וכמארז\"ל כברייתו<sup data-n=\"4219\">32</sup> של עולם ברישא חשוכא והדר נהורא שזהו כברייתו של עולם דוקא אבל קודם שנברא ונאצל העולם ולא בא עדיין לכלל השפעה מעצמו' המאציל אזי בחי' ההעלם עם בחי' הגילוי אור שוין ממש לפניו וזהו כחשיכה כאורה חושך הוא ההעלם אשר בתחלה ואור הוא בחי' הגילוי שאח\"כ שוין שניהם כא' בלתי נמצא שום יתרון מעלה מזע\"ז ולא ענין קדימה זע\"ז משום דאין ענין הגילוי וההעלם שייך כלל קודם ההשפעה ולפני עצמו' המאציל גם ההעלם נחשב גילוי כו' וכמ\"ש במ\"א וזהו גם חושך לא יחשיך ממך וד\"ל.\n<b>ומזה</b> יובן ג\"כ מה שיוכל להיות חיבור וקשר בין ב' הפכי' דיו\"ד וה\"א הנ\"ל הוא מטעם שיאיר האור בהם מבחי' עצמות המאציל דקמיה כחשיכה כאורה מטעם הנ\"ל ואזי יעשה בהם בחי' אחדות והתכללות ולא יהיו ב' הפכים כלל והוא בחי' כח הממוצע המחבר י\"ה בשם הוי' לפי שכאשר בא האור מעצמו' אור א\"ס דההעלם גילוי והגילוי העלם אזי עי\"ז יוכל להיו' בחי' ממוצע ביו\"ד ה\"א בין ההעלם לגילוי עד שיהי' בתחלה הצמצום<sup data-n=\"4220\">33</sup> דיו\"ד ואח\"כ מן הצמצום יבא לבחי' התפשטו' דה\"א ושניהם כא' יאירו יחד למטה ואינם ב' הפכים כלל וד\"ל.\n<b>וזהו</b> כל<sup data-n=\"4221\">34</sup> העוסק בתורה לשמה משים שלום בפמליא של מעלה כו' כי הנה בחי' הגורם להיות השפעה זו מעצמו' המאציל מן ההעלם לגילוי לחבר ב' הפכי' דיו\"ד ה\"א כנ\"ל הוא ע\"י התורה לפי שהתורה<sup data-n=\"4222\">35</sup> נק' שלום וכמ\"ש ה'<sup data-n=\"4223\">36</sup> עוז לעמו כו' שנא' או<sup data-n=\"4224\">37</sup> יחזק במעוזי יעשה שלום לי כו' והטעם הוא משום דאוריי'<sup data-n=\"4225\">38</sup> מחכמה עילא' נפקת וכתיב ה'<sup data-n=\"4226\">39</sup> בחכמה ואין<sup data-n=\"4227\">40</sup> התלבשות אור א\"ס אלא בחכמה וזהו ענין העוסק בתורה לשמה היינו לשם התורה עצמה דהיינו להמשיך אור א\"ס בחכמה כי כל<sup data-n=\"4228\">41</sup> הקורא ושונה הקדב\"ה יושב וקורא ושונה כנגדו כמ\"ש הקול<sup data-n=\"4229\">42</sup> קול יעקב ופי'",[["4219","32","<b>כברייתו של עולם</b>: שבת עז, ב."],["4220","33","<b>הצמצום דיו\"ד. . . יבא לבחי' התפשטות דה\"א</b>: ראה הערת כ\"ק אדמו\"ר בספר המאמרים תרנ\"ט ע' עה."],["4221","34","<b>כל העוסק בתורה לשמה</b>: ראה סנהדרין צט, ב."],["4222","35","<b>שהתורה נק' שלום</b>: ראה במדב\"ר פי\"א ז, ובמדרש לקח טוב ר\"פ קדושים."],["4223","36","<b>ה' עוז לעמו</b>: תהלים כט, יא."],["4224","37","<b>או יחזק במעוזי יעשה שלום</b>: ישעי' כז, ה."],["4225","38","<b>דאוריי' מחכמה עילא' נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. זח\"ג פא, א. קפב, א. רסא, א."],["4226","39","<b>ה' בחכמה</b>: משלי ג, יט."],["4227","40","<b>ואין התלבשות אור א\"ס אלא בחכמה</b>: ראה תניא פל\"ה בהג\"ה."],["4228","41","<b>כל הקורא ושונה</b>: תדא\"ר רפי\"ח. יל\"ש איכה רמז תתרלד."],["4229","42","<b>הקול קול יעקב</b>: תולדות כז, כב."]]],[2100990214,"קול<sup data-n=\"4230\">43</sup> הוא ענין ההמשכה כנודע וא\"כ כשהקדב\"ה יושב וקורא כנגדו נמשך מעצמו' המאציל בחכמה וזהו לשמה לשם<sup data-n=\"4231\">44</sup> התורה ובזה הרי נעשה שלום והתחברות בפמליא של מעלה שהן בחי' חו\"ב<sup data-n=\"4232\">45</sup> תרין ריעין כו' והם אותיו' י\"ה להיות בבחי' היחוד וההתכללו' שיאירו כא' בחי' הצמצום עם בחי' ההתפשטו' ולהיות נק' תרין ריעין דלא מתפרשין והיינו או יחזק במעוזי יעשה שלום לי לי ממש לאותיו' י\"ה שבשם הוי' והיינו שפתחו כולם ואמרו ה'<sup data-n=\"4233\">46</sup> יברך את עמו בשלום ע\"י התורה שהיא בחי' הממוצע לגרום שלום בפמליא של מעלה מטעם הנ\"ל וד\"ל.\n<b>וענין</b> השלום בפמליא של מטה הוא באותיו' ו\"ה שבשם הוי' כו'. כי הנה כתיב לך ה' &lt;רפח&gt;\nהגדולה והגבורה והתפארת כו' ולנגד זה יש ז' מדות דקליפ' דאת<sup data-n=\"4234\">47</sup> זלע\"ז עשה האלקי' וזהו וכרות עמו הברית לתת ארץ הכנעני והחתי כו' שהן ז' עממין ושרש יניקות השפע לז' עממין באה מבחי' קו השמאל כמ\"ש בזוהר<sup data-n=\"4235\">48</sup> דאית ימינא ואית שמאלא לעילא בסטרא דקדוש' וכתיב ימינך<sup data-n=\"4236\">49</sup> ה' נאדרי בכח כו' ששמאלא אתכליל בימינא עד\"מ היד השמאל שנכלל כחה בכח היד הימין ואז ממילא ימינך<sup data-n=\"4237\">50</sup> ה' תרעץ אויב כו'.\n<b>וביאור</b> הדברים דהנה ענין כל התורה הוא רק בשביל התכללות המדו' דהיינו שיהא שמאלא אתכליל בימינא כמ\"ש בזוהר<sup data-n=\"4238\">51</sup> בריש פ' קרח ע\"ש. והענין הוא שיהא עי\"ז בחי' המתקות הגבורו' בחסדי' כי שרש הגבורו' והדין נמשך משמאלא ושרש החסדי' מימינא וכאשר נכלל שמאל בימין נמתקו הגבורו' בחסדי' כו'.\n<b>ודוגמא</b> לדבר מה שמצינו בענין כי את<sup data-n=\"4239\">52</sup> אשר יאהב ה' יוכיח לפי שיש ב' מיני יסורי' א' שהן באין לעונש ממש והב' יסורין שאינן באין על האדם בשביל לעשו' בו נקמה על החטא שעבר כו' אלא היסורין<sup data-n=\"4240\">53</sup> הן למרק ולזכך נפשו ויבא לו טובה וחסד מיסורין הללו ונק' יסורין של אהבה וז\"ש כי את אשר יאהב ה' יוכיח כידוע ועד\"מ האב המכה ומייסר לבנו בשביל שילך בדרך הישר שהכאה זו בשביל האהבה דוקא היא מפני שרוצה בתקנתו כו' ונמצא הכאה זו אינה עונש אלא חסד וטוב וה\"ז דמיון לענין המתקו' הגבורו' בחסדים למעלה דהיינו שהדין הוא נכלל בחסד ממש וכך כתיב ימינך ה' נאדרי בכח שהימין שהוא שרש החסדי' גוברי' על",[["4230","43","<b>קול הוא ענין המשכה</b>: ראה לקו\"ת ראה כג, ב ובכ\"מ."],["4231","44","<b>לשם התורה</b>: ראה תניא פ\"ה."],["4232","45","<b>חו\"ב תרין ריעין</b>: ראה זח\"ג ד, א."],["4233","46","<b>ה' יברך את עמו בשלום</b>: תהלים כט, יא."],["4234","47","<b>זלע\"ז עשה האלקים</b>: קהלת ז, יד."],["4235","48","<b>בזוהר דאית ימינא ואית שמאלא</b>: זח\"א נג, א. זח\"ב קצב, ב."],["4236","49","<b>ימינך ה' נאדרי בכח</b>: שמות טו, ו."],["4237","50","<b>ימינך ה' תרעץ אויב</b>: שם."],["4238","51","<b>בזוהר בריש פ' קרח</b>: קעח, א. וראה לעיל ע' תקמב."],["4239","52","<b>את אשר יאהב ה' יוכיח</b>: משלי ג, יב."],["4240","53","<b>היסורין הן למרק ולזכך נפשו</b>: ראה לקו\"ת קרח נג, ד. לקו\"ש חכ\"ב ע' 71 מציין גם לכוזרי מאמר שני פמ\"ד."]]],[2100990215,"בחי' קו השמאל עד שנמתקין ונכללי' בחסדי' וזהו פי' נאדרי בכח ואזי ממילא מה שיש אחיזה לחיצוני' מקו השמאל נהפך להם לדין ועונש ממש ולא לחסד וטוב כלל אחר שהטוב והחסד שבקו השמאל נכלל כבר בחסד לא נשאר להם רק הדין הקשה וזהו ימינך ה' תרעץ אויב ימינך דוקא שכלול גם מקו השמאל הכל נהפך להם לדיני' קשים מטעם ההתכללו' דשמאלא בימינא בקדוש' אחר דאת זלע\"ז עשה כו' ולאם<sup data-n=\"4241\">54</sup> מלאם יאמץ כו' וד\"ל.\n<b>וזהו</b> ענין השלום בפמליא של מטה בו\"ה כי הרי ימינא ושמאלא הם ב' הפכי' וכדי שיהא המתקו' הגבורו' בחסדי' ליכלל שמאלא בימינא צריך שיבא האור והשפע ממקום הגבוה משניהם כענין עושה<sup data-n=\"4242\">55</sup> השלום במרומיו מיכאל וגבריאל כו' והיינו מ\"ש לך ה' הגדולה והגבורה פי' שחו\"ג ימין ושמאל שניהם באים בבחי' ביטול כלפי שם הוי' שלמעלה מן הגדולה והגבורה כו' משום דאור א\"ס עצמו למעלה מבחי' התחלקו' הוא כמאמר הידוע דאיהו וחיוהי וגרמוהי חד כו' ולכך נעשה בחי' יחוד גמור במדו' חו\"ג ואתכליל שמאלא בימינא והוא ענין השלום בו\"ה שהוא בחי' ההתכללו' של המדו' ויש התכללות בכלל ז' המדו' והוא ענין המתקו' הגבורו' בחסדי' ויש התכללו' בפרט וי\"ו בה\"א שהוא יחוד קדב\"ה ושכינתי' מ\"ה וב\"ן כידוע עד\"מ קול ודיבור למטה וד\"ל, וזהו או יחזק במעוזי ע\"י התורה ג\"כ שלום יעשה לי גם בפמליא של מטה בו\"ה דשם הוי' כי הנה בתורה נא' מימינו<sup data-n=\"4243\">56</sup> אש דת למו אש שחורה<sup data-n=\"4244\">57</sup> ע\"ג אש לבנה כו' משמאלא נכלל בימינא כמ\"ש מימינו אש כו' וזהו כענין מאמרם ז\"ל אנכי<sup data-n=\"4245\">58</sup> ולא יהי' לך מפי הגבורה שמענום מפי הגבורה דוקא אבל נכלל הגבורה בחסד בב' דברו' הללו אנכי ולא יהי' לך כי אנכי<sup data-n=\"4246\">59</sup> שרש &lt;רפט&gt;\nרמ\"ח מ\"ע ולא יהי' לך שרש ל\"ת וכל התורה כולה גם במ\"ע הרי היא רק בחי' דינים וצמצומי' כמו כך וכך יוכשר למצוה ואם לאו פסול ואין זה רצון העליון כלל כו' וכן בטומא' וטהרה וגם בדיני ממונו' הכל ענין דקדוקי' על הדבר שבכך וכך דוקא יוכשר להיו' גילוי רצון העליון לזכות או לחיוב לטמא או לטהר כו' באופן זה דוקא ולא בהיפך אמנם עיקר הדקדוק הוא בשביל שבזה יוכל להיו' גילוי רצון העליון ואם לאו לא יוכל להיו' גילוי הרצון כו' א\"כ הרי בחי' הדין והצמצום נכלל בחסד ושמאלא אתכליל בימינא כי עיקר הכונה בצמצום בשביל הגילוי אור שיוכל להיו' אח\"ז וזהו מימינו אש כו' שניתנה דקדוקי התורה בימין מחמת האהבה כמ\"ש וימינו<sup data-n=\"4247\">60</sup> תחבקיני וזהו אנכי ולא יהי' לך מפי הגבורה כו' כי אנכי הוא כללו' גילוי אור א\"ס וא\"א כ\"א שלא יהי' לך אלקי' אחרי' והיינו בהיותו סור מרע בפרט משס\"ה ל\"ת שכל זה בשביל",[["4241","54","<b>ולאם מלאם יאמץ</b>: תולדות כה, כג."],["4242","55","<b>עושה השלום במרומיו מיכאל וגבריאל</b>: איוב כה, ב. במדבר רבה פי\"ב, ח."],["4243","56","<b>מימינו אש דת למו</b>: ברכה לג, ב."],["4244","57","<b>אש שחורה ע\"ג אש לבנה</b>: ראה ירושלמי שקלים פ\"ו סה\"א. תנחומא ר\"פ בראשית. זח\"ג קלב, א. רש\"י ברכה לג, ב. שה\"ש ה, טז (ד\"ה שחורות)."],["4245","58","<b>אנכי ולא יהי' לך מפי הגבורה שמענום</b>: יתרו כ, ב-ג. מכות כד, א. ראה זח\"ב צא, א."],["4246","59","<b>אנכי שרש רמ\"ח מ\"ע</b>: ראה זח\"ב צא, א. רעו, א. של\"ה שטו, ב. תניא פ\"כ. וראה ס' מאמרי אדה\"א במדבר ח\"ד ע' א'תפו, מ\"ש שם בשם הרמב\"ן, ובהמ\"מ שם."],["4247","60","<b>וימינו תחבקיני</b>: שה\"ש ב, ו. ח, ג."]]],[2100990216,"שיהא גילוי אנכי כו' וה\"ז מיתוק הגבורו' בחסדי' כמו דוגמת ענין הנ\"ל בפי' כי את אשר יאהב ה' יוכיח כו' וד\"ל וע\"כ כל התורה כולה עיקר ענין בחי' התכללו' המדו' שמאלא בימינא כו' וזהו שהעוסק בתורה לשמה משים שלום גם בפמליא של מטה כמו בפמליא של מעלה כמ\"ש או יחזק במעוזי כו' אך שלום הראשון מאת ה' עצמו בא כמ\"ש ה' יברך את עמו בשלו\"ם והוא ע\"י התורה שנק' שלום כנ\"ל ואח\"כ נא' שלום<sup data-n=\"4248\">61</sup> יעשה לי מלמטה למעלה מצד התורה עצמה אבל בשלום הראשון כתיב יעשה שלום לי מלמעלה למטה כו' וד\"ל.\n<b>והנה</b> ע\"ד הנ\"ל בב' השלומות למעלה בפמליא ש\"מ ובפש\"מ כך יש בנפש האדם ענין ב' שלומות הללו כי הנה הנפש<sup data-n=\"4249\">62</sup> יש בה אותיו' שם הוי' כמ\"ש אני<sup data-n=\"4250\">63</sup> הוי' אלקיכם שמשרה שם הוי' על כנ\"י וכמ\"ש הנקראי' בשם הוי' וראו<sup data-n=\"4251\">64</sup> כל עמי הארץ כי שם הוי' נקרא עליך כו' והנה י\"ה שבנפש הם בחי' חו\"ב שבנפש כידוע והיינו מה שיש בנפש האלקי' להשכיל בחכמה בבחי' ראי' להיו' רואה את הנולד יש מאין כו' ואיך דכולא<sup data-n=\"4252\">65</sup> קמי' כלא כו' וכיוצא ואח\"כ יתבונן במוח הבינה להשיג זה בהשגה והבנה כו', וידוע שעי\"ז יבא להתפעלות האהבה בפסוק ואהבת<sup data-n=\"4253\">66</sup> את ה' כו' והנה האהבה שבלב ברשפי אש הנולד מן ההתבוננו' שבמוח הוא מצד התלבשו' הבינה בלב דוקא כמאמר בינה<sup data-n=\"4254\">67</sup> ליבא הלב מבין כו' ודוקא אחר שהלב מבין מתפעל ברשפי אש התשוקה כידוע לי\"ח בתפלה, וע\"כ אמרו בזוהר<sup data-n=\"4255\">68</sup> הנסתרות לה' אלקינו אינון מוחא ולבא שהן יו\"ד ה\"א כי יו\"ד דחכמה במוחא וה\"א דבינה בלב כנ\"ל וד\"ל, והנה האהבה ברשפי אש בלב היא מבחי' הגבורו' כי הרי היא בבחי' צמאון אש התשוקה מיסוד האש שבלב כידוע ובחי' התפעלות המוח מצד החכמה היא שם בבחי' יסוד המים שבמוח שהוא בבחי' הקרירו' והרי הם ב' הפכי' המוח מבחי' החסדי' והלב מבחי' הגבורו' כו' וע\"כ זאת היא הסיבה הידוע למבקשי ה' בתפלה שכאשר יעמיק במוח בהתבוננו' אזי לא ירגיש האהבה ברשפי אש הצמאון בלב וכשהלב מתגבר בצמאון אזי תקטן רוח בינתו שבמוח לפי שהם שני הפכים ולא ישכנו כאחד אלא כשזה מתגבר זה &lt;רצ&gt;\nנופל כו' וד\"ל, וע\"כ צריך שיבא בחי' ממוצע שיעשה ביניהם שלום והתחברו' כו' וענין ההתחברו' הוא שיהא המוח<sup data-n=\"4256\">69</sup> שליט על הלב כי שמאלא צריך להיו' נכלל בימינא כנ\"ל.\n<b>וענין</b> שליטת המוח על הלב היינו שתהא אופן התפעלות הלב עפ\"י אופן התפעלות המוח דוקא ולא באופן אחר כי הנה טבע התפעלות הלב הוא בבחי' ההרגשה",[["4248","61","<b>שלום יעשה לי</b>: ישעי' כז, ה."],["4249","62","<b>הנפש. . . שם הוי'</b>: בלקו\"ת שם מציין (וכמ\"ש במ\"א בפסוק ולא אבה ה' אלקיך לשמוע אל בלעם כו' [לקו\"ת תצא לח, ג]."],["4250","63","<b>אני הוי' אלקיכם</b>: שלח טו, מא."],["4251","64","<b>וראו כל עמי הארץ</b>: דברים כח, יוד."],["4252","65","<b>דכולא קמי' כלא</b>: ראה זהר בהקדמה יא, ב."],["4253","66","<b>ואהבת את ה'</b>: ואתחנן ו, ה."],["4254","67","<b>בינה ליבא הלב מבין</b>: ת\"ז בהקדמה (פתח אליהו)."],["4255","68","<b>בזוהר הנסתרות לה' אלקינו אינון מוחא ולבא</b>: נצבים כט, כח. ע\"פ תיקוני זהר בהקדמה ד\"ה פתח אליהו. דרך חיים שער התפלה ע' קז."],["4256","69","<b>המוח שליט על הלב</b>: ראה זח\"ג רכד, א."]]],[2100990217,"דוקא להרגיש את התפעלותו בבחי' אהבה מורגשת והוא בתערובו' טו\"ר דהיינו להרגיש א\"ע בזה בבחי' יש ודבר שיש מי שאוהב כו' ונק' בחי' זו בחי' חסד<sup data-n=\"4257\">70</sup> שהוא לגרמיה כו' כמ\"ש במ\"א וכדוגמת חסד אוה\"ע כו' אבל התפעלות המוח הוא בא בבחי' ביטול עצמותו מכל וכל כענין כלה<sup data-n=\"4258\">71</sup> שאירי לבבי מי<sup data-n=\"4259\">72</sup> לי בשמים כו' והיינו בכל נפשך אע\"פ שלא יזכה לנפשו כלום מענין המעלות והמדרגו' ואין זה אלא מצד בחי' החכמה שבמוח שהיא בחי' הביטול וההתכללות כנודע וכאשר המוח הוא שליט על הלב אזי ביכולתו לכבוש טבע הלב ולהפכו כפי טבע המוח והיינו ענין ביטול והתכללו' גבורו' בחסדי' לאכללא שמאלא בימינא, וזהו ענין השלום במוחא ולבא שהן י\"ה שנק' למעלה פמליא ש\"מ וכמו שלמעלה הוא ע\"י התורה מטעם הנ\"ל כך בנפש הוא ע\"י עסק התורה דוקא כמ\"ש ודברת<sup data-n=\"4260\">73</sup> בם בשבתך כו' שבזה נעשה בחי' ביטול והתכללו' בנפש להיו' כי עי\"ז אליך<sup data-n=\"4261\">74</sup> ה' נפשי אשא מחשבה במחשבה דיבור בדיבור כו' וממילא עי\"ז נעשה השלום ג\"כ בחו\"ב שבנפש להיות המוח שליט על הלב כנ\"ל וד\"ל.\n<b>וענין</b> השלום בפמליא ש\"מ בנפש בו\"ה היינו בבחי' התהפכות המדות לפי שהמדו' שבנפש הבהמיו' מעה\"ד טו\"ר נמשך ולפעמי' לפי העת והזמן ישתנה טבע המדו' פעם לטוב ופעם לרע כנרא' בחוש שלפי שעה יהיו מדו' האדם טובים ובעת אחרת יהיו רעים לפי שעה\"ד טו\"ר כלול מכ\"ח עתים י\"ד לטוב עת<sup data-n=\"4262\">75</sup> לבנות עת לשחוק כו' ועת לסתור עת לבכות כו' לרע ולכך העיתים למטה משתנים כי פעמי' מתגברי' עתים הטובי' דעה\"ד ולפעמי' עתים הרעי' וע\"כ אמר ואל<sup data-n=\"4263\">76</sup> יבא בכל עת כו' כמ\"ש בזוהר וד\"ל, וצריך להפוך הרע לטו' גם מעתי' הרעי' לטובי' והוא ע\"י שינוי הטבע לברר הטוב מן הרע כו' ולאהפכא חשוכא לנהורא כו' וליכלל הכל בטוב וזהו ע\"י חכמה כי<sup data-n=\"4264\">77</sup> בחכמה אתברירו דוקא וע\"כ התבררו' זו הוא ע\"י עסק התורה ג\"כ וזהו ענין השלום בפמליא ש\"מ בו\"ה שבנפש כי הנה ידוע דעיקר התורה הוא ענין ההתבררו' בטו\"ר דלכך נק' תורה להורות ולהבדיל<sup data-n=\"4265\">78</sup> בין הטמא לטהור כו' וד\"ל.\n<b>ומה</b> שאמר שהשלום הוא לחבר ו\"ה ולפ\"ז הרי אין כאן התחברות אלא ענין התבררו' בלבד הענין הוא לפי שע\"י בירור זה בעה\"ד נתחבר ה' בוי\"ו שהוא יחוד דקדב\"ה ושכינתי' הנק' יחודא תתא' כי היחוד דחו\"ב נק' יחודא עילא' והן אותיו' י\"ה בכלל כנ\"ל והטעם הוא לפי שעי\"ז הבירור יוכל להיו' ענין קישור וחיבור הרוחניות בגשמיו' כי לכאורה יפלא מהיכן ימצא ענין חיבור רוחניו' האלקי במעשה",[["4257","70","<b>חסד. . . לגרמיה כו' כמ\"ש במ\"א</b>: ע\"פ תיקוני זהר תיקון ו (כב, סע\"א). וראה תניא ספ\"א."],["4258","71","<b>כלה שארי לבבי</b>: תהלים עג, כה."],["4259","72","<b>מי לי שמים</b>: שם כו."],["4260","73","<b>ודברת בם בשבתך</b>: ואתחנן ו, ז."],["4261","74","<b>אליך ה' נפשי אשא</b>: תהלים כה, א."],["4262","75","<b>עת לבנות. . . עת לבכות</b>: קהלת ג, ג-ד."],["4263","76","<b>ואל יבא בכל עת כו' כמ\"ש בזהר</b>: אחרי טז, ב. זח\"ב קנה, ב. זח\"ג נח, סע\"א ואילך."],["4264","77","<b>כי בחכמה אתברירו</b>: ראה זח\"ב רנד, ב. תניא באגה\"ק סכ\"ח."],["4265","78","<b>ולהבדיל בין הטמא לטהור</b>: ע\"פ שמיני יא, טז."]]],[2100990218,"המצות כמו בפ'<sup data-n=\"4266\">79</sup> קדש דתפילין שורה בחי' חכמה חכים כו' והוקשה<sup data-n=\"4267\">80</sup> כל התורה לתפילין כו' והרי הרוחניו' והגשם הם ב' הפכים אך הענין הוא דע\"י השלום הממוצע הוא בחי' המחבר רוחניו' בגשמיו' ואין זה השלום אלא ע\"י התורה שנק' שלום לפי שמבררת כל המצות איך ומה &lt;רצא&gt;\nובאיזה אופן יוכשר כו' כנ\"ל עד שעי\"ז האופן יוכל להיו' קישור וחיבור גילוי רצון העליון כו' והיינו שהתורה עושה השלום בו\"ה וי\"ו הוא בחי' מדו' עליונו' והוא הנק' הקדב\"ה וה\"א הוא בחי' מעשה<sup data-n=\"4268\">81</sup> המצוה שנק' מצות המלך כידוע בפי' כי נר מצוה כו' וד\"ל.\n<b>וזהו</b> והי'<sup data-n=\"4269\">82</sup> מעשה הצדקה שלום פי' צדקה הגשמית הוא רק העושה שלום בין העשיר והעני לחברם כי העני מתקנא ויש לו שנאה ועד\"ז כללו' כל המצות<sup data-n=\"4270\">83</sup> שנק' צדקה למעלה כידוע נק' שלום לפי שמחמתם נעשה שלום וחיבור בין המשפיע למקבל שהוא המל' הנק' דל כו' והוא ענין חיבור ו\"ה וזהו והי' מעשה הצדקה שלום שהוא ה\"א אחרונ' שמתחברת בוי\"ו והיא נק' צדק\"ה<sup data-n=\"4271\">84</sup> צדק ה' כידוע והיינו השלום בפמליא ש\"מ וד\"ל.\n<b>וזהו</b> החלצו מאתכם אנשים לצבא ויהיו על מדין כו'. דהנה מבואר למעלה בענין קליפת מדין שהוא להיפך בחי' השלום והיחוד בקדושה האלקי' בפמש\"מ ופש\"מ וע\"י מדין נעשה בחי' הפירוד בין י\"ה ובין ו\"ה וע\"כ ציוה ה' להכניע מדין במלחמה כדי לתת נקמת שם הוי' דהיינו שיהי' שלם בבחי' היחוד ממש ובתחלה הי' קצת הכנעת קליפה זו ע\"י משה כי יתרו כהן מדין הכניע א\"ע לפני משה ולולי זה לא ניתנה התורה כי בהכנעת הקליפ' דמדין ממילא יוכל להיו' היחוד ע\"י תורה ומצות כנ\"ל, אך סיבת הכנעת יתרו היה מפני משה דוקא כי משה שרש התורה היה לנגד קליפ' דיתרו כי הרי נק' תורת משה כמ\"ש תורה<sup data-n=\"4272\">85</sup> ציוה לנו משה והתורה הוא בחי' הביטול וההתכללו' היפך בחי' הפירוד כנ\"ל וע\"כ נצטווה משה צרור<sup data-n=\"4273\">86</sup> את המדינים ואחר<sup data-n=\"4274\">87</sup> תאסף אל עמך כי במשה הי' תלוי נצחון מלחמה דמדין מטעם זה וד\"ל. אך עדיין יש להבין מ\"ש החלצו מאתכם כו' ויהיו על מדין מהו על ומהו לכל מטות כו'.\n<b>אך</b> הענין הוא דהנה שרש מספר בני ישראל הם ס\"ר נשמו' לפי ששרשם מבחי' ו\"ק דקדוש' הגדולה והגבור' וכל או\"א כלול מק' אלף כו' כי חסד שבחסד כלול מי'",[["4266","79","<b>בפ' קדש דתפילין</b>: פ' בא יח, ב."],["4267","80","<b>והוקשה כל התורה לתפילין</b>: ראה קידושין לה, א."],["4268","81","<b>מעשה מצות. . . מצות המלך. . . כי נר מצוה</b>: ראה אסתר ג, ו. וראה שערי תשובה עג, ג. קלא, א. תורת שמואל תרל\"ב ח\"ב ע' תכז. משלי ו, כג."],["4269","82","<b>והי' מעשה הצדקה שלום</b>: ישעי' לב, י ז."],["4270","83","<b>כל המצות שנק' צדקה למעלה</b>: ראה לקו\"ת שה\"ש טז, ג. כב, א. וראה מאמרי אדה\"א מטות ע' א'תת שמבאר ענין זה בארוכה."],["4271","84","<b>צדקה צדק ה'</b>: ראה זהר אחרי עב, א. מאמרי אדה\"א שמות ח\"א ע' קכה, וש\"נ."],["4272","85","<b>תורה ציוה לנו משה</b>: ברכה לג, ד."],["4273","86","<b>צרור את המדינים</b>: פינחס כה, יז."],["4274","87","<b>ואחר תאסף אל עמך</b>: מטות לא, ב."]]],[2100990219,"כו' עד שכללותם ס\"ר והשבטים נק' בשם מטות עד\"מ המטה שנוטין בו כלפי מעלה או כלפי מטה כך שרש נשמו' ישראל נק' מטה כמ\"ש מטה<sup data-n=\"4275\">88</sup> כלפי חסד שיש בזה ב' פירושי' א' ענין ההמשכה מלמעלה למטה והב' מטה כלפי מעלה דהיינו מלמטה למעלה ושניהם אמת משום דכתיב ששם<sup data-n=\"4276\">89</sup> עלו שבטים שבטי יה כו' שיש ב' מיני שבטי' א' בעלמא דנוק' והיינו מלמטה<sup data-n=\"4277\">90</sup> למעלה והב' בעלמא דדכורא שנק' שבטי יה והיינו מלמעלה<sup data-n=\"4278\">91</sup> למטה ובכלל הם רק י\"ב ו\"ק מלמעלה למטה וששה מלמטה למעלה כו', ומה שאמר לכל מטות ישראל כולל הכל בין ו' השבטי' שמלמעלה למטה ובין ו' השבטי' שמלמטה למעלה כי כללות הכל צריכי' לצבוא על מדין לפי שעיקר המנגד לקליפ' מדין היינו דוקא בחי' היחוד וההתכללו' כנ\"ל וא\"א להיו' שלימות היחוד בלתי שיתחברו דוקא כולם כא' ויש בזה ב' עניני שלום א' בפש\"מ וא' מלמטה למעלה ע\"י שם הוי' בנפש כנ\"ל וע\"כ לא אמר מכל מטות דהוה משמע רק מלמעלה למטה אלא אמר לכל מטות דמשמע שכולם מצד עצמם יגרמו בחי' היחוד גם מלמטה למעלה.\n<b>וזהו</b> החלצו מאתכם מאתכם דוקא ע\"י &lt;רצב&gt;\nחיבור שם הוי' בנפש ויהי' בזה לנגד קליפת מדין שהוא בחי' הפירוד וזהו על מדין למעלה מבחי' מדין להכניעם כי כדי לתת נקמת שם הוי' במדין צריך שיהי' בחי' ההתכללו' במדות שבנפש ואז אין מקום שם לקליפת מדין כי אין פירוד כלל במקום היחוד וממילא יכנעו תחתם ולפי שצריך הכנה לזה בתחלה לעשות זאת ההתכללות רק בשביל להסיר הפירוד וע\"כ אמר לשון על כלומר בשבילו פי' כולם יתנו לב על מדין להכניעו כי כל א' יכלול נפשו בכללו' היחוד וכולם כאיש א' יהיו נכללים וזהו עיקר המלחמה להכניע את מדין והיינו ויהיו על מדין וד\"ל.\n<b>ובכל</b> זה יתורץ גם מה שאמר ברישא החלצו דמשמע כולם ואח\"כ אמר לכל מטו', דברישא מיירי מלמטה למעלה ובסיפא מיירי בכללות השבטי' בין מלמעלה בין מלמטה דשייך לומר לשון לכל וד\"ל וגם בכל זה יתורץ ענין טעם עון שנאת חנם שגדול מע\"ז כו' לפי שבבחי' הפירוד אין השם דהוי' שלם וגורם הסתלקו' השכינה בכלל שזה קשה גם מכל גרעון אור שע\"י כל העבירו' כו' ולכך אריכו' הגלות הזה ביותר לפי שצריך לשהות עד שיהי' בחי' ההתכללות בכל פרטי הניצוצו' שבכללו' נ\"י וזה צריך זמן רב מאד משא\"כ בבית ראשון כנ\"ל וד\"ל.",[["4275","88","<b>מטה כלפי חסד</b>: ראה פרדס שכ\"ג בערך \"מטה כלפי חסד\"."],["4276","89","<b>ששם עלו שבטים</b>: תהלים קכב, ד."],["4277","90","<b>מלמטה למעלה</b>: בלקו\"ת מטות פו, ד — נטיתי לבי לעשות חוקיך."],["4278","91","<b>מלמעלה למטה</b>: בלקו\"ת שם: כמו הט שמיך ותרד (תהלים קמד)."]]],[2100990220,"<h3>להבין שרש הדברים</h3>\n<b>בעזר\"ה</b>\n<b>להבין</b><sup data-n=\"4279\">1</sup> שרש הדברים הנ\"ל. הנה להבין שרש ענין קליפת מדין שאינה נחשבת בכלל ז' עממין כנ\"ל תחלה יש להבין שרש ז' עממין דהנה ידוע בענין ז' מלכין קדמאין שמתו כמ\"ש וימלוך<sup data-n=\"4280\">2</sup> וימת כו' עד שנפלו בעולם הבריאה שנשאר מהם סיגי' ופסולת שלא נתבררו גם אחר בחי' התיקון והבירור ונק' שיורי המלכים שלא נתבררו עדיין כמ\"ש בע\"ח<sup data-n=\"4281\">3</sup> כי הגם שהובררו כל הז' מלכים בבחי' התיקון אבל עדיין נשאר מהם קצת סיגי' ופסולת שלא הובררו כי ידוע סדר ענין הברורי' דמה שנברר מהם תחלה לפני האצי' נברר ונכלל באצי' ומה שלא יוכל להתברר באצי' ירד לבריא' ונכלל שם ונעשה בחי' בריא' וכן מבריא' ליצי' ומיצי' לעשי' עד שנשאר בעשי' פסולת וסיגים ממש שאין להם בירור כלל.\n<b>וביאור</b> הדברים יובן בדוגמא ממה שאמרו ז\"ל האבות<sup data-n=\"4282\">4</sup> הן המרכבה שהיו בבחי' ביטול במציאו' כמרכבה לגבי רוכב לבחי' חג\"ת דז\"א כו' כידוע ואעפ\"כ אמרו לא<sup data-n=\"4283\">5</sup> כאברהם שיצא ממנו ישמעאל ולא כיצחק שיצא ממנו עשו כו' הרי שיצא מאברהם ויצחק בחי' פסולת וסיגי' ישמעאל פסולת וסיגי' דחסד דקדוש' ועשו פסולת וסיגי' דגבורה דקדושה אך הענין הוא שזה היה מצד התלבשו' נשמות שלהם בגופים חומריי' שנלקחו מנוגה דעשי' ששם נשאר מז' מלכים משיורי &lt;רצג&gt;\nהפסולת שלא נתברר עדיין כנ\"ל וע\"כ גם אברהם<sup data-n=\"4284\">6</sup> שהיה איש החסד דקדוש' יצא ממנו מותרי פסולת החסד והוא ישמעאל<sup data-n=\"4285\">7</sup> חסד דקליפ' כו' וד\"ל.\n<b>אך</b> יש להבין איך יתכן שימצא מציאת סיגים ופסולת כ\"כ למטה כמו שר של ישמעאל מאורו' עליונים דז' מלכים דתוהו שגבוה גם מבחי' התיקון דאצי' כמ\"ש לפני<sup data-n=\"4286\">8</sup> מלוך מלך לבנ\"י כידוע אבל הענין הזה מובן מתוך מה שמצינו בדוגמא מהטוב דקדושה סדר ההשתלשלו' מעילה לעילה וכו' עד שנתגשם האור בהגשמה כו' כך בבחי' הסיגי' והפסולת יש בחי' ריבוי ההשתלשלות מעילה לעילה עד שנעשה סיגים ופסולת גמור וע\"ד דוגמא הנה אנו רואי' בסטרא דקדוש' שבאצי' שם הוא בבחי' הביטול בתכלית ובעולם הבריאה כבר יש שם בחי' יש ודבר מה ואינו בבחי' ביטול גמור עד שימצא שם גם ענין שכר לזוכה ועונש לחוטא כמו דאפקוה<sup data-n=\"4287\">9</sup> למט\"ט כו' דנתחייב עונש על מיעוט הביטול וכמ\"ש דשמים<sup data-n=\"4288\">10</sup> לא זכו בעיניו ואף במלאכיו",[["4279","1","<b>להבין שרש הדברים</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (פ, א).\nנוסח אחר (הנחת המהרי\"ל) נדפס בלקו\"ת מטות פז, א."],["4280","2","<b>וימלוך וימת</b>: וישלח לו, לב."],["4281","3","<b>כמ\"ש בע\"ח</b>: ראה ע\"ח (שער טנת\"א) ש\"ה, פ\"א."],["4282","4","<b>האבות הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו."],["4283","5","<b>לא כאברהם שיצא ממנו ישמעאל</b>: פסחים קיט, ב. ספרי דברים פ' שיב."],["4284","6","<b>אברהם. . . איש החסד</b>: ראה פרדס שער (כג) ערכי הכינויים מערכת אהבה."],["4285","7","<b>ישמעאל חסד דקליפה</b>: ראה לקו\"ש כרך כ ע' 102 הערה 26-27. ראה תו\"ח בראשית פח, ב. שמות מג, א. מאמרי אדה\"א דברים ח\"ב ע' תקלח."],["4286","8","<b>לפני מלוך מלך לבנ\"י</b>: וישלח שם."],["4287","9","<b>דאפקוה למט\"ט</b>: חגיגה טו, א. וראה גם מאמרי אדה\"ז-ענינים ע' סט, וש\"נ."],["4288","10","<b>דשמים לא זכו בעיניו</b>: איוב טו, טו."]]],[2100990221,"ישים תהלה כו' הגם שהם משתחווי' בבחי' ביטול במציאות כמ\"ש וצבא<sup data-n=\"4289\">11</sup> השמים לך משתחווי' אך לפרקים אין בהם בחי' הביטול כו' ובעולם היצי' נתמעט בחי' הביטול יותר עד שבעולם השפל הזה הם בבחי' הפירוד ממש כו' וכך יובן בסט\"א הגם ששרשו משיורי פסולת וסיגי' דאורו' עליוני' דתוהו כשנפלו וירדו נשתלשלו מעילה לעילה עד שנעשה סיגי' גמורים כו' כמו שמצינו בגמ' גבי שטן דלפעמי' אמרו שטן<sup data-n=\"4290\">12</sup> לש\"ש נתכוין כו' ולפעמים אמרו נתן<sup data-n=\"4291\">13</sup> עיניו במקדש ראשון כו' שנתן עיניו לרע ממש ולא כיון לש\"ש אך הענין הוא דשניהם אמת דבהיותו עדיין בבחי' סיגי' ופסולת בבחי' האצי' שם עדיין אין בו רע גמור אלא כוונתו רק לש\"ש אך בירידתו בהשתלשלות למטה בעולם הבריאה והיצי' וכיוצא נעשה שם בחי' סיגי' יותר קשה ונק' בשם מקטרג ממש וכענין שקטרג על איוב החנם<sup data-n=\"4292\">14</sup> ירא איוב כו' וכן נתן עיניו במקדש לרע ממש וכיוצא בזה מובן איך שנתהווה מציא' שר ישמעאל מפסולת וסיגי' דחסד דאברהם שהי' בו מצד התלבשו' נשמתו בנפש דנוגה כנ\"ל וד\"ל.\n<b>והנה</b> ע\"ד הנ\"ל יובן גם בשאר פרטי חלקי הרע שנמצא מסיגי' ופסולת דז' מלכי' ונק' בכלל ז' מדו' רעות למעלה והם שרש לז' עממין כו' ולכך לא היה גלות בית ראשון אלא ע' שנה בלבד לפי שהסיגי' והפסולת משיורי ז' המלכי' שלא נתבררו כנ\"ל יש להן שיעור וגבול מאחר שהם מוגבלים כבר מבחי' הכלים דתיקון בכל מה שהי' יכול להתברר מהם כנ\"ל א\"כ מה שנשאר מהם שלא נתברר ג\"כ יש לו שיעור ומדה עכ\"פ ובגלות הוא ענין הברורי' כמ\"ש בגלות מצרים<sup data-n=\"4293\">15</sup> בכור הברזל כו' וכנגד ז' מדו' דתוהו הי' די בע' שנה כי כל מדה כלול מי' כמבואר למעלה וד\"ל אבל גלות בית שני לא הי' בעבור ז' המדו' רעו' שהן ז' עממי' הכנעני כו' אלא בעבור שנאת חנם שהוא בחי' הפירוד לזה אין קץ ושיעור כלל לכך נתארך הגלות הזה כ\"כ כו'.\n<b>וביאור</b> הדברי' הנה בחי' הפירוד דשנאת חנם שרשו למעלה הוא ענין קליפת מדין והענין הזה הוא כמ\"ש בספרא<sup data-n=\"4294\">16</sup> דצניעותא עד לא הוה מתקלא כו' לא הוו משגחין אפין באפין כו' פי' זהו בחי' התוהו שכל א' וא' מנקודות דתוהו &lt;רצד&gt;\nדבר בפ\"ע והם עומדי' זה תחת זה וכאו\"א מחזיר פניו מחבירו כי הוא דבר מיוחד בפ\"ע ואינו רוצה להיות לו חיבור וקישור כלל עם זולתו כו' והוא בחי' אב\"א היפך בחי' פב\"פ והיינו דלא משגחין אפין באפין כו' ונקרא עולם<sup data-n=\"4295\">17</sup> הפירוד הזה בשם רה\"ר כו'",[["4289","11","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו."],["4290","12","<b>שטן לש\"ש נתכוין</b>: בבא בתרא טז, א."],["4291","13","<b>נתן עיניו במקדש</b>: סוכה נב, סע\"א. וראה ביאוה\"ז לאדה\"א צו, ג. ובביאוה\"ז להצ\"צ ע' תפז."],["4292","14","<b>החנם ירא איוב</b>: איוב א, ט."],["4293","15","<b>מצרים בכור הברזל</b>: ואתחנן ד, כ. מלכים-א ח, נא. ירמי' יא, ד. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרמ. תו\"א יתרו עד, סע\"א ואילך. מאמרי אדה\"א במדבר ח\"ב ע' תשע."],["4294","16","<b>בספרא דצניעותא</b>: בזהר פ' תרומה קעו, ב."],["4295","17","<b>עולם הפירוד. . . רה\"ר</b>: ראה לקוטי הש\"ס להאריז\"ל ריש מס' שבת ד\"ה ארבע רשויות. ראה ג\"כ לקו\"ת במדבר טז, א. סה\"מ תקס\"ו ח\"א ע' רכו. תו\"ח נח עט, א. שערי תשובה נג, ב."]]],[2100990222,"כידוע כי אין שם בחי' היחוד וההתכללות אלא כאו\"א בבחי' פירוד בפ\"ע דוקא כמשל רה\"ר כו' וע\"כ המסתעף בחי' רע מזה אין לו זמן מוגבל להתתקן כלל אלא לאחר שיהי' בהם בחי' ההתכללות והיחוד וזה צריך להיו' זמן ארוך מאד והוא ענין אריכות הגלות הזה וד\"ל.\n<b>ולהבין</b> ביאור הדברים הנה מבשרי אחזה כו' שהמדות באדם כשהם בלתי הנהגת השכל כל א' וא' אין לה קשר וחיבור כלל עם זולתה כמו כאשר יכעוס ויקצוף אין לו רחמי' וחסד בשעה זו כלל על מי שכועס עליו ובהיפוך כשמתחסד אין לו דין וצמצום כלל ונמצא מדו' חו\"ג מפורדין המה זה מזה בתכלית הפירוד כו' וע\"כ יוכל להיו' מסתעף ממותרי הדין דין קשה ביותר וממותרי החסד חסד גס וכיוצא ולדוגמא כזו יש להבין בבחי' ז' מדו' דתוהו דלכך יצא מהם פסולת וסיגי' כענין אברהם שיצא ממנו ישמעאל וכנ\"ל ואמנם בחי' עיקר התיקון בהם הוא רק לעשות בהם בחי' ההתכללות והיחוד דוקא מהיפך זה עם היפך שבחבירו כמו חסד שבחסד עם גבורה שבגבורה הרי הם תכלית הפירוד ביותר והוא בחי' התוהו אחר שזהו חסד שבחסד וזהו גבורה שבגבורה כו' אך מ\"מ יוכל להיו' מתכללי' חסד וגבורה בהפכים שיש בהם ויוכל להיו' חיבור וקשר גמור כמו גבורה שבחסד שהיא היפך החסד עם חסד שבגבורה שהוא היפך הגבורה ע\"י שני אלה יוכלו להתחבר ממש והדמיון בגשמיות ידוע ממעשה מרקחת שהחריפו' שבצנון עם המתיקו' של הדבש באמת הם ב' הפכי' אבל המתיקו' שיש גם בצנון כידוע עם החריפו' שבדבש אע\"פ שגם הם הפכי' אבל מפני שהוא היפוך הראשון כו' אז מתכללי' מתיקו' במתיקו' וחריפו' בחריפו' כו' וכל זה משל ג\"כ להבין שסיבת ההתכללו' מהפכי' הוא ע\"י שהחו\"ג מתחלקי' לריבוא אופני' ודוקא מהיפך שלהם כמו גבורה שבחסד כו'.\n<b>וכדוגמת</b> כל אלה יובן למשכיל למעלה שרש סיבת בחי' התיקון בתוהו הוא רק לעשו' בהם בחי' היחוד וההתכללו' כנ\"ל במשל אך איך יתכללו יחד ב' הפכי' לזה הוא עיקר ענין התיקון ע\"י שם מ\"ה כידוע והיינו בב' דברים דוקא הא' בריבוי הכלים והב' בריבוי האורו' כידוע שמפני מיעוט הכלי נסתלק האור כו' והנה ענין ריבוי הכלים מובן ומבואר מתוך משל הנ\"ל שהוא להיו' החסד כלול גם מגבורה והגבורה מחסד ועד\"ז יוכל להיו' ריבוי הכלים מכלים כו' מפני שעי\"ז יוכלו להתחבר ולהתכלל גם ב' הפכי' כנ\"ל וד\"ל וענין ריבוי האורות הוא לאחר ריבוי הכלים דלאחר שנתרבה הכלי יוכל להחזיק בתוכו ריבוי אור ביותר כמשל ריבוי אותיו' הדיבור שמחזיק בתוכו אור שכל וכן במדו' שעפ\"י השכל הרי השכל מתפשט לפי ערך הרחבת הכלים שלהם דוקא כנרא' בחוש בתינוק שמדותיו קטני' אין השכל מאיר ומתפשט בהם כ\"כ כו' והנה עיקר שלימות בחי' התיקון הנה הוא בא דוקא אחר כניסת האורות בריבוי מפני ריבוי הכלים כנ\"ל כי מצד האורו' יוכלו כל ההפכי' להתכלל ולהתחבר לפי &lt;רצה&gt;\nששרש האורו' נמשך מבחי' הקו והחוט שהוא בחי' אור א\"ס המחבר הכל כו' אך שאין ביכולת האורו' לחבר רק כשהארתן מרובה דהיינו ע\"י ריבוי הכלים כו' ואז ביכולתן גם להחליף הארתן"],[2100990223,"שיאיר אור<sup data-n=\"4296\">18</sup> החסד בכלי הגבור' ואור הגבור' בכלי החסד כידוע וזהו עיקר בחי' התיקון השלם בתכלית כמבואר למעיין בע\"ח וד\"ל.\n<b>ואחר</b> כל זה מובן בטעם אריכת הגלות כי אין שיעור לזמן עד שיהי' בחי' ההתכללות בכל בחי' אורו' דתוהו לתקן בחי' הפירוד דתוהו ואין כאן דבר מוגבל כלל לתקן כמו בשיורי ז' המלכי' כו' שה\"ז ממש כמו שהי' לפני התיקון דלא הוו משגחין אפין באפין כלל שהתיקון לא נשלם אז בז' מלכי' ואע\"פ שאח\"כ נתבררו ז' המלכי' ולא נשארו רק שיורי פסולת כנ\"ל מ\"מ בקליפת הפירוד דשנאת חנם חזרו לכמו שהיו קודם התיקון שלא היו משגחין אפין באפין כלל וד\"ל והיינו שרש ענין קליפת מדין שגדלה מקליפו' ז' עממין כולם מטעם הנ\"ל וד\"ל.\n<b>והנה</b> שרש קליפת מדין למטה הי' ע\"ד הדוגמא למעלה בבחי' התוהו כמו שהי' עדיין בלתי תיקון דלא הוו משגחין אפין באפין כנ\"ל וע\"כ בא יתרו כהן מדין להכניע א\"ע קודם מ\"ת כמ\"ש בזוהר לפי ששרש התורה הוא היפך המנגד לבחי' הפירוד דמדין כי התורה הוא בבחי' התיקון וכמ\"ש ה' יברך את עמו בשלום עד שהעוסק בתורה לשמה משים שלום בפש\"מ כו' כמבואר למעלה.\n<b>והנה</b> יש להבין בשרש ענין התיקון שהוא ענין השלום בי\"ה ובו\"ה כנ\"ל. בהיות ידוע ביאור ענין ד' אותיו' דהוי' היו\"ד הוא נקודה והנקודה מורה ב' ענינים א' צמצום ההעלם שנתעלם הכל ולא נשאר רק כמו נקודה א' בלבד והב' ענין גילוי הנקודה עכ\"פ והנמשל מובן למעלה בבחי' החכמה שנא' בה והחכמה<sup data-n=\"4297\">19</sup> מאין תמצא שמציאת התהוות החכמה מן הכתר שנק' אין היא באה בבחי' נקודה א' בלבד והטעם הוא כי י\"ס שבכתר עצמו נק' חושך כלומר בבחי' ההעלם וכמ\"ש מגלה<sup data-n=\"4298\">20</sup> עמוקות מני חושך שכל ע\"ס שבגילוי כמו שהם בבחי' ההעלם עדיין נק' עמוקו' ומתגלי' עמוקו' הללו מני חושך וגם כל פרטי ההתחלקו' חסד שבחסד כו' הכל היו בהעלם תחלה וע\"כ לא נק' בחי' גילוי החכמה מאין דכתר רק בבחי' נקודה והוא בחי' נקודי\"ם לפי שהעיקר נשאר בבחי' ההעלם ולא נגלה משם רק כמו נקודא א' וזהו כמשל הברק המבריק בגילוי מן ההעלם כמ\"ש ויצא<sup data-n=\"4299\">21</sup> כברק חצו כי ההעלם נק' חושך וכמ\"ש ישת<sup data-n=\"4300\">22</sup> חושך סתרו וכידוע בפי' ענין טורי<sup data-n=\"4301\">23</sup> חשוכא כו' ולכך אמר בזוהר<sup data-n=\"4302\">24</sup> דהחכמה כמו שהוא מלובש בבינה נק' נקודה בהיכלא וההיכל הוא בחי' בינה שיש לה התפשטו' השגה לאורך ורוחב כהיכל ולכך",[["4296","18","<b>אור החסד בכלי הגבורה. . . בע\"ח</b>: מובא בשם ע\"ח שער מטול\"מ — ראה שעה\"י קלא, א הערה 5. מאמרי אדה\"ז תקס\"ה ח\"א ע' ח. לעיל (ח\"א) ע' יב."],["4297","19","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["4298","20","<b>מגלה עמוקות מני חושך</b>: איוב יב, כב."],["4299","21","<b>ויצא כברק חצו</b>: זכרי' ט, יד."],["4300","22","<b>ישת חושך סתרו</b>: תהלים יח, יב."],["4301","23","<b>טורי חשוכא</b>: ראה זהר פינחס רמט, רע\"ב."],["4302","24","<b>בזוהר. . . נקודה בהיכלא</b>: ראה זח\"א ו, א. תיקוני זהר ת\"ה (יט, א). תכ\"ח (עב, א). ראה אגה\"ק סי' ה' (קז, א). ובקו\"א (קסא, א)."]]],[2100990224,"אימא<sup data-n=\"4303\">25</sup> מקננא בכורסייא ששם ז' היכלו' דבריא' כלולי' בה כידוע וגם לכך נק' הבינה<sup data-n=\"4304\">26</sup> אלקים חיים ומלך עולם כו' כידוע וזה פי' נקודא בהיכלא שהחכמה שהוא כמו עד\"מ הברק מלובש הוא בהתפשטו' דבינה עד\"מ כשאדם לומד ונופל לו שכל חדש ועדיין אינו אלא כמו נקודא א' עד\"מ הברק ואח\"כ בא לידי הבנה והשגה לאורך וכידוע וד\"ל והנה המחבר והמזווג חכמה להיו' כמו בחי' נקודה בהיכלא הוא ע\"י בחי' הדעת ונק' דעת עליון כי הנה בחי' דעת זה עולה עד &lt;רצו&gt;\nבחי' קרומא דאוירא דחפיא על חכמה סתימא' דא\"א כו' וביאור ענין קרומא זה מבואר במ\"א והוא למטה מבחי' האויר שלפני הקרום והענין הוא שהארת אור א\"ס כאשר מתצמצם בתחלה בעצמותו נק' אויר פשוט כו' והוא נחשב מבחי' עצמו' אור הא\"ס עדיין שהוא למעלה הרבה גם מבחי' הכתר דא\"א כמבואר בע\"ח וע\"כ ביכולתו לחבר ולקשר אור החכמה בבינה ויובן זה עד\"מ כשאדם משכיל איזה שכל שידוע דהארה זו נמשכת מלמעלה מן השכל שנק' משכיל והוא בחי' ח\"ס כידוע ולפעמי' אין נופל לו שכל מלמעלה מן השכל א\"כ בהכרח לומר שיש דבר שלמעלה מבחי' ח\"ס שהוא המקשרו ומחברו לבא לידי גילוי בשכל לפעמי' כך ולפעמי' כך כו' והיינו מפני שמאיר דרך בחי' קרומא דחפיא על ח\"ס כו' וכך יובן בבחי' הדעת לפי שעולה עד למעלה מבחי' קרומא דחפיא כו' ע\"כ יש ביכולתו לקשר ולחבר גם אור החכמה בבינה למטה וד\"ל.\n<b>וזהו</b> ענין עוסק בתורה לשמה לשם התורה דהיינו שיהי' נמצא מציא' חכמה שבתורה מבחי' עצמו' אור א\"ס כנ\"ל והיינו מה שאמר בזוהר<sup data-n=\"4305\">27</sup> דוד קשיר אוריית' דלעילא בקדב\"ה פי' אוריי' דלעילא הוא בחי' חכמה עילאה ששרשה בבחי' ח\"ס דא\"א כו' כי יש<sup data-n=\"4306\">28</sup> חכמה בראש וחכמה בסוף ונק' אוריי' דלתתא כו' ודוד קשיר אוריי' דלעילא שהוא בחי' ח\"ע בקדב\"ה שהוא עצמו' אור א\"ס שמאיר בקרומא דאוירא כו' כנ\"ל להיות השראת אור א\"ס בתורה והיינו לשמה לשם התורה וד\"ל וזהו שרש ענין תחלת התיקון לחבר אותיו' י\"ה דשם הוי' שהוא חו\"ב<sup data-n=\"4307\">29</sup> תרין ריעין כו' ע\"י התורה שהיא בבחי' הדעת שהוא עושה השלום כנ\"ל וד\"ל.\n<b>וזהו</b> או יחזק במעוזי יעשה שלום לי בפמליא ש\"מ כו', פי' בפמליא ש\"מ היינו להיות בחי' נקודא בהיכלא כנ\"ל והיינו יעשה שלום לי מלמעלה למטה מעצמו' אור הא\"ס כנ\"ל ואח\"כ שלום יעשה לי בפמליא של מטה בו\"ה ונק' שלום זה שלום התחתון כו' כי הנה כתיב כי<sup data-n=\"4308\">30</sup> אל דיעו' הוי' שיש ב' דיעות ונק' דעת עליון",[["4303","25","<b>אימא מקננא בכורסייא</b>: תיקוני זהר תיקון ו (כג, א). ע\"ח שער סדר אבי\"ע (שמ\"ז) פ\"ג. שער דרושי אבי\"ע (שמ\"ב) פי\"ג. תניא פל\"ט."],["4304","26","<b>הבינה אלקים חיים</b>: ראה זהר יתרו סח, ב. ובהגהות הרח\"ו שם: אור החמה שם. ע\"ח שער (כו') הצלם רפ\"ג. לקו\"ת להאריז\"ל ירמי' י, י. סידור האריז\"ל ומשנת חסידים ב[תפלת הבריאה פ\"ב מ\"א] בברכת יוצר."],["4305","27","<b>בזוהר דוד קשיר אורייתא דלעילא בקדב\"ה</b>: זח\"ג רכב, ב. וראה אוה\"ת שבועות ע' קעז."],["4306","28","<b>יש חכמה בראש וחכמה בסוף</b>: ראה זח\"א כו, ב."],["4307","29","<b>חו\"ב תרין ריעין</b>: נסמן לעיל ע' תקג."],["4308","30","<b>כי אל דעות הוי'. . . דעת עליון ודעת תחתון</b>: שמואל-א ב, ג. ראה ס' מאמרי אדה\"א ויקרא ח\"א ע' רסב, וש\"נ בארוכה."]]],[2100990225,"ודעת תחתון דעת עליון הוא המחבר ומייחד חו\"ב ודעת תחתון הוא המחבר זו\"נ שנק' ו\"ה והוא בחי' דעת המתפשט במדו' כו' וזהו שלום יעשה לי כו'.\n<b>וביאור</b> הדברים הנה זהו ענין בחי' ההתכללו' במדות המבואר למעלה שהוא ענין לאכללא שמאלא בימינא המתקו' הגבורו' בחסדי' כו'. דהנה בחי' גבורו' שאינן נמתקין בחסדי' היינו כמו היסורין שבאין לעונש ממש כנ\"ל והדוגמא לדבר דור המבול שאמרו ז\"ל שאין<sup data-n=\"4309\">31</sup> להם חלק לעוה\"ב ומאחר שאין להם חלק לעוה\"ב הרי מה שקיבלו עונש במי המבול לא יצא להם מזה שום תיקון ותועלת כלל אלא רק עונש ודין ממש וכן במבול של אש במהפכת סדום ועמרה שגם להם אין חלק לעוה\"ב כידוע לא היה במבול של אש שום חסד וטוב כלל וכיוצא בזה בעשרה מכות במצרים אך מ\"מ יש קצת תועלת מזה אבל לא להם אלא לעולם כמ\"ש באבוד<sup data-n=\"4310\">32</sup> רשעים רינה שיש רינה בעולם באיבוד הרשעי' ורינה זו מפני שנעשה בחי' תיקון לעולם באיבוד הרשעי' כו' אבל יסורין שבאין בשביל תיקון דוקא נק' יסורי' של אהבה שאינם דין ועונש כלל עבור החטא והעון כי החטא &lt;רצז&gt;\nוהעון נמחל כבר בלא\"ה רק בשביל תיקון הנפש ע\"ד שהאם רוחץ<sup data-n=\"4311\">33</sup> לצואת התינוק כמ\"ש אם<sup data-n=\"4312\">34</sup> רחץ ה' צואת כו' א\"ת<sup data-n=\"4313\">35</sup> א ם אלא א ם והוא הדינין דמתערין מאימא עילא' שהם בחי' גבורו' ממותקו' רק לרחוץ הרע שנאחז מצד יניקו' החיצוני' כו' וד\"ל ואמנם כל ענין בחי' גבורו' ממותקו' הנ\"ל אינם באים רק מצד ריבוי המשכת מוחי' דגדלו' בז\"א מאו\"א כמ\"ש כי<sup data-n=\"4314\">36</sup> את אשר יאהב הוי' הוי' דוקא שהוא בחי' ז\"א יוכיח ביסורין של אהבה הנ\"ל שנק' גבורו' ממותקו' כנ\"ל וענין המשכו' המוחי' הללו היינו ע\"י בחי' הדעת המתפשט במדות לעשות בהם בחי' ההתכללו' כמו מגבורה שבחסד עם חסד שבגבור' וכיוצא כנ\"ל וענין התכללות זאת ממתקת כל הדינין להיו' הכל גבורו' ממותקו' עד\"מ המשכיל על דבר יוכל למצוא זכות לחייב וגם אם יענוש אותו הכל יהי' במשפט רק כדי שיתוקן וכל שישכיל יותר יותר יזכה לחייב כמו שאמר רשב\"י יכולני<sup data-n=\"4315\">37</sup> לפטור כל העולם מן הדין כו' מפני ריבוי מוחי' דגדלו' שהמשיך בשרש כללו' נ\"י מצד מעלת נשמתו כידוע וד\"ל ודעת זה הממשיך המוחי' לז\"א מנה\"י דאו\"א נק' דעת תחתון והוא ג\"כ גנוז בתורה להיות שע\"י התורה נמשך מוחי' חדשי' לז\"א בבחי' תוס' וריבוי גדול כמאמר הקדב\"ה<sup data-n=\"4316\">38</sup> יושב ועוסק בתורה וידוע שהקדב\"ה הוא בחי' ז\"א ועסק התורה שלו הוא ענין המשכו' מוחי' לז\"א מאו\"א והיינו ענין השלום בפמליא ש\"מ ע\"י הדעת תחתון להמשיך מוחי' בתוס' לז\"א להיו' בו בחי' גבורו' ממותקו' אך מתחלה אמר יעשה שלום לי מלמעלה למטה באו\"א ואח\"כ שלום יעשה שמאו\"א נמשך מוחי' לזו\"נ להיו' שם בחי' ההתכללו' כנ\"ל וד\"ל.",[["4309","31","<b>שאין להם חלק לעוה\"ב</b>: סנהדרין פ\"ו, מ\"ב."],["4310","32","<b>באבוד רשעים רינה</b>: משלי יא, יוד."],["4311","33","<b>רוחץ לצואת התינוק</b>: ראה תנחומא חוקת ה. במד\"ר פי\"ט, ח. וראה גם אגרת הקודש פרק כב."],["4312","34","<b>אם רחץ ה' צואת</b>: ישעי' ד, ד."],["4313","35","<b>א\"ת אם אלא אם</b>: פרע\"ח שער (יח) השבת פ\"ג. מאמרי אדה\"א ויקרא ח\"ב ע' תקיב, וש\"נ."],["4314","36","<b>כי את אשר יאהב הוי'</b>: משלי ג, יב."],["4315","37","<b>יכולני לפטור כל העולם מן הדין</b>: סוכה מה, ב. וראה ב\"ר פל\"ה."],["4316","38","<b>הקב\"ה יושב ועוסק בתורה</b>: ראה ע\"ז ג, ב."]]],[2100990226,"<b>ועתה</b> יש להבין שרש ענין ב' שלומות הללו בנפש האדם כנ\"ל. דהנה מ\"ש בזוהר דהנסתרו'<sup data-n=\"4317\">39</sup> לה' אלקינו הן מוחא ולבא כו' הענין הוא לפי שידוע בע\"ח דבחי' יסוד<sup data-n=\"4318\">40</sup> אימא מסתיים בחזה דז\"א כו' והענין הוא דהבינה שבמוח מתפשטת במדות בבחי' נה\"י שבה עד שמגעת להאיר גם בחיצוניו' המדות דז\"א שנק' חזה כו' ושם מסתיים האור שלה ועכ\"פ הרי בלב עדיין מאיר הארת אור הבינה וע\"כ אמרו בינה<sup data-n=\"4319\">41</sup> לבא בה הלב מבין כו' ומזה נולד ההתפעלו' בלב בבחי' רצוא כי ל\"ב אורות דאימא דמתפשטי' בז\"א ולא יוכלו להתיישב שם ע\"כ מצד הדוחק יצאו ויאירו לחוץ והוא ענין סיבת התפעלו' הלב ברשפי אש שהוא דוקא מצד הארת הבינה וכמ\"ש בע\"ח בענין הלב וכמ\"ש במ\"א וע\"כ מאחר שבדחיקת האורו' דאימא מתפעל הלב א\"כ זהו הסיבה שבהתפעלו' הלב מתמעט אור השכל ובהתגברו' השכל מתמעט ההתפעלו' כו' וצריך לעשות שלום בין השכל והלב והוא ענין חיבור י\"ה יו\"ד במוח וה\"א דבינה בלב שהם ב' הפכים שזה יורד מגבוה לנמוך וזה עולה מלב למעלה כו' והשלום הוא שיהא המוח שליט על הלב והוא ע\"י התורה כי ע\"י עסק התורה לשמה כנ\"ל נמשך תוספת מוחי' מאו\"א לז\"א כנ\"ל ועי\"ז המוח שליט על הלב להיו' התפעלו' הלב עפ\"י אופן התפעלו' המוח דוקא כנ\"ל כי ע\"י התורה מתמתקין הגבורו' בחסדים לאכללא שמאלא בימינא כנ\"ל ועי\"ז גם בחי' הרצוא דלב נכלל בבחי' השוב דחכמה שבמוח לפי שבחי' &lt;חצר&gt;\nהחסדים הוא שגוברין על הגבורו' כו' וזהו שלום הראשון וענין השלום השני הוא בו\"ה שבנפש בסור מרע ועשה טוב לברר המדו' מהרע כו' כנ\"ל שהוא ג\"כ ע\"י התורה מפני שנאמר בה להבדיל בין הטמא כו' כידוע וד\"ל.\n<b>וזהו</b> החלצו מאתכם אנשים לצבא כו' לתת נקמת הוי' במדין. דהנה ידוע דקודם התיקון לא הי' עדיין בחי' שם הוי' אלא שמות אחרים כמאמר הידוע בזוהר<sup data-n=\"4320\">*41</sup> דהוה קראן לי' בשמות נוכראן כו' ואחר התיקון הוא שנק' בשם הוי' דוקא כי ד' אותיו' הללו מורין דוקא על בחי' התיקון כי עיקר ענין התיקון הוא בחי' ההתכללו' דוקא וכאן באות י\"ה יש שלום וחיבור בין ב' הפכי' צמצום<sup data-n=\"4321\">42</sup> דיו\"ד עם התפשטו' דה\"א וכן באותיו' ו\"ה והיינו ענין ב' השלומות הנ\"ל בפמליא ש\"מ ובפמליא ש\"מ כנ\"ל וע\"כ קודם בחי' התיקון לא הי' נקרא בשם הוי' עדיין אלא בשמות נוכראין וד\"ל. והנה מבואר למעלה בשרש ענין קליפת מדין שהוא בחי' הפירוד דתוהו שלפני התיקון וע\"כ קודם מ\"ת בא יתרו כהן מדין להכניע א\"ע כו' וכאן ציוה ה' לעשו' מלחמה במדין להכניעם לגמרי כדי לעשו' שם הוי' דתיקון בשלימות בבחי' ההתכללו' ומפני שזה א\"א כ\"א ע\"י הכנעת קליפת מדין בתחלה שהוא ההיפך ממש בבחי' הפירוד וזהו לתת נקמת הוי' שם במדין בשביל שם הוי' דוקא שהוא בחי'",[["4317","39","<b>דהנסתרות. . . מוחא ולבא</b>: תקו\"ז בהקדמה."],["4318","40","<b>יסוד אימא. . . בחזה דז\"א</b>: ראה ע\"ח (שער לידת המוחין) שכ\"א, פ\"ג."],["4319","41","<b>בינה ליבא בה הלב מבין</b>: ת\"ז בהקדמה שם."],["4320","*41","<b>בזוהר דהוה קראן לי' בשמות נוכראן</b>: ראה ג\"כ לקו\"ת (כאן) מטות פח, ב. המשך תער\"ב ע' רנב."],["4321","42","<b>צמצום דיו\"ד. . . התפשטות דה\"א</b>: ראה זהר (אדרא זוטא) האזינו רצ, ב. אגרת התשובה פ\"ד."]]],[2100990227,"התיקון ומה שאמר לתת נקמת הוי' במדין בהם דוקא היינו לעשו' מבחי' הפירוד דתוהו בחי' היחוד דשם הוי' דתיקון וזהו לתת נקמת הוי' במדין וד\"ל. וענין הנקמה הזאת הוא להעמיד דוקא את ההיפך דתוהו המנגדו להיות עומד כפוף לבחי' התיקון כו'.\n<b>ומה</b> שאמר החלצו מאתכם דמאתכם משמע מקצת מכל שבט ולא כולם והל\"ל לפ\"ז יחלצו דהחלצו כולכם משמע דהא כתיב וידבר אל העם החלצו כו' הענין הוא לפי שפי' החלצו יש בו ג\"כ מענין בחי' התיקון וכתרגום החלצו הוא ויזדרזון כו' כאדם החוגר כלי קרב שאוזר את חגורו כמו שפי' הראב\"ע והתיקון הזה למעלה הוא ענין הנ\"ל לעשות בחי' שם הוי' דתיקון לחבר ולייחד דוקא היפך בחי' הפירוד, ותיקון זה צריך להיו' מן אנשים המבוררי' כבר שניתקנו בעצמם כענין קשט<sup data-n=\"4322\">53</sup> עצמך כו' וע\"כ ציוה להם בתיקון זה שיהי' התיקון בעצמם בתחלה ואח\"כ יוכלו לתקן את מדין כו' והיינו שאמר החלצו דמשמע כולכם פי' שכולכם יתנו לב להתתקן בעצמם תחלה ואיך יהי' אופן התיקון מכולם הענין הוא שכולם יהיו תחלה בבחי' ההתכללו' ואח\"כ יחלצו מכל שבט בחי' הברורי' שבהם אלף למטה כו' לכל מטות ישראל פי' שיהי' אותן הנבררי' כלולים דוקא מכל מטו' ישראל כי כדי לתקן ההיפך צ\"ל דוקא מבחי' ההתכללו' דכולם ואמנם לפ\"ז הל\"ל מכל מטות כו' אך מפני שא\"צ שיהי' ההתכללו' מכולם רק כדי שיתתקנו בעצמם תחלה אבל אחר שתיקנו א\"ע יחלצו מאתכם רק מקצת מכל שבט ומטה רק שיהיו כלולי' מכל שבט כנ\"ל והיינו כמשל המתקן א\"ע לאזור חגורו שאע\"פ שמכין כל גופו לתיקון זה מ\"מ אין עיקר התיקון אלא באזירת חגורו בלבד וכיוצא רק שצריך להזדרז בכל גופו לזה וזהו ענין התרגום ויזדרזון כו' וד\"ל. ובכל זה מתורץ הקושיא במה שאמר לכל מטות ולא מכל &lt;רצט&gt;\nמטות ואמר החלצו ולא יחלצו משום דברישא מיירי בתיקון עצמם כנ\"ל ובסיפא מיירי בתיקון מדין כמו שהקדים לתת נקמת הוי' במדין וכנ\"ל וד\"ל.\n<b>ובכל</b> זה יובן ג\"כ עוד ענין אחר והוא בענין התחלת פ' זו במ\"ש וידבר<sup data-n=\"4323\">44</sup> ה' אל משה לאמר נקום נקמת בנ\"י מאת המדינים אחר תאסף אל עמך כו' ואח\"כ אמר וידבר משה אל העם החלצו מאתכם כו'. דלכאורה אינו מובן למה תלה ענין פטירת משה במלחמה זו באמרו דאחר המלחמה הזאת דוקא תאסף אל עמך ולמה לא תהא מלחמה זו אחר פטירתו כשאר המלחמו' שהיו עתידין להיו' ע\"י יהושע וגם הלא כבר נצטווה משה עלה<sup data-n=\"4324\">45</sup> אל הר העברים הזה כו' ונאספת<sup data-n=\"4325\">46</sup> אל עמך כאשר נאסף אהרן אחיך כו' ולמה המתין לו עד שיעשה מלחמה במדין ואחר יאסף אל עמיו כו' וכי הי' כדאי מלחמה זו להיו' ע\"י משה להמתין לו כ\"כ גם אחר שכבר נקנסה עליו גזרת ה' כו'.",[["4322","53","<b>קשוט עצמך</b>: ב\"מ קז, סע\"ב."],["4323","44","<b>וידבר ה'. . . נקום נקמת בנ\"י</b>: מטות לא, א-ב."],["4324","45","<b>עלה אל הר העברים</b>: פינחס כז, יב."],["4325","46","<b>ונאספת אל עמך</b>: שם יג."]]],[2100990228,"<b>אך</b> הענין הוא משום דדוקא מלחמה זו דמדין לא הי' באפשרי כ\"א בהיות משה חי והוא יפקוד האנשי' למלחמה כו' להיות כי בחי' משה הי' דוקא עיקר המנצח לקליפת מדין כי הוא המנגד באמת לבחי' הפירוד דמדין וע\"כ בלעדו לא הי' ניצוח מלחמה זו כלל וגם במלחמה זו דוקא נשלם שלימות שרש נשמתו וע\"כ אמר אחר תאסף אל עמך אחר מלחמה זו דוקא.\n<b>וביאור</b> הדברים דהנה שרש בחי' משה<sup data-n=\"4326\">47</sup> הי' מבחי' פנימי' אור אבא שמשם נמשך השרש לבחי' התיקון כי הנה משה<sup data-n=\"4327\">48</sup> נק' מחוקק כמ\"ש כי<sup data-n=\"4328\">49</sup> שם חלקת מחוקק ספון והיינו מבחי' יסוד אבא שנק' מחוקק וע\"כ כל התורה כולה נקרא' ע\"ש משה דוקא כמ\"ש תורה<sup data-n=\"4329\">50</sup> ציוה לנו משה כו' כאילו משה ציוה כו' ונק' ג\"כ תורת משה כו' לפי ששרש נשמתו הי' מבחי' פנימי' החכמה שהוא מקור החכמה שבתורה וע\"כ ע\"י משה דוקא ניתנו כל פ' ופ' שבתורה כמ\"ש וידבר<sup data-n=\"4330\">51</sup> ה' אל משה כו' וכמ\"ש וירא<sup data-n=\"4331\">52</sup> ראשית לו כו' אלא שזכה<sup data-n=\"4332\">53</sup> גם לבינה כו' אבל שרשו מבחי' החכמה<sup data-n=\"4333\">54</sup> שנק' ראשית כו' והנה מבואר למעלה שהמדינים שרשם מבחי' התוהו שקודם התיקון כמו שהי' ז' נקודות זה תחת זה כו' וכמאמר עד<sup data-n=\"4334\">55</sup> לא הוה מתקלא לא הוו משגחין אפין באפין כו' והנה משה<sup data-n=\"4335\">56</sup> שנק' מחוקק ונק' ג\"כ ספרא רבא הי' בחי' היפך האמיתי לפירוד זה דתוהו כו' כי ענין המחוקק הוא להמשיך אורו' בכלים ולחבר ולעשו' יחודי' עליונים דוקא והוא להיו' דוקא בחי' ההתכללו' מאורו' וכלים הגם שהם ב' הפכי' כנ\"ל וכן מחו\"ג לאכללא שמאלא בימינא כו' שזהו שרש כל התורה כולה כנ\"ל ולפי שמשה הי' שרש התורה דהיינו שרש בחי' התיקון ע\"כ ביכולתו דוקא הי' להכניע המנגד אליו ולא ע\"י זולתו וע\"כ נצטווה נקום נקמת בנ\"י מאת המדינים ואחר תאסף אל עמך משום דבדידי' דוקא תליא מלתא ולא הי' נצחון מלחמה זו ע\"י אחר מטעם הנ\"ל וגם בזאת המלחמה נשלם שלימו' שרש נשמתו כי אחר שעשה מלחמה במדין והכניע כל בחי' פירוד ממילא נכלל על ידו בחי' ההתכללו' בתכלית השלימות וע\"כ הגם שכבר נצטווה עלה אל הר העברים ונאספת אל עמך כו' כדאי הי' להמתין לו עד שינצח מלחמת מדין מטעם הנ\"ל וד\"ל.\n&lt;ש&gt;\n<b>ועוד</b> יש טעם בזה והכל עולה לענין א' והוא לפי שא\"א הי' להיו' בחי' ההתכללו' מכללו' נ\"י דוקא כמ\"ש החלצו כו' כ\"א ע\"י משה דוקא כו'. דהנה ידוע בענין הדגלים שהיו כללות נ\"י נחלקים בזה לד'<sup data-n=\"4336\">57</sup> מדרגות לנגד ד' סטרי עלמא מזרח",[["4326","47","<b>משה. . . אור אבא</b>: ראה לקו\"ש ח\"ו ע' 246, וש\"נ."],["4327","48","<b>משה נק' מחוקק</b>: ראה בבא בתרא טו, א."],["4328","49","<b>כי שם חלקת מחוקק ספון</b>: דברים לג, כא."],["4329","50","<b>תורה צוה לנו משה</b>: שם לג, ד."],["4330","51","<b>וידבר ה' אל משה</b>: בא יג, א. יב, א. מג."],["4331","52","<b>וירא ראשית לו</b>: ברכה לג, כא."],["4332","53","<b>שזכה גם לבינה</b>: ראה ר\"ה כא, ב. זח\"ב קטו, א. ובניצוצי זהר שם."],["4333","54","<b>החכמה שנק' ראשית</b>: ראה תהלים קיא, א."],["4334","55","<b>עד לא הוה מתקלא</b>: ראה זהר (ספרא דצניעותא) תרומה קעו, ב."],["4335","56","<b>משה. . . ספרא רבא</b>: ברכה לג, כא תרגום אונקלוס שם."],["4336","57","<b>לד' מדריגות לנגד ד' סטרי. . . בזוהר פקודי</b>: רל, א."]]]]});
